INSERT INTO `knowledge_chapter` (`id`, `course_id`, `parent_id`, `chapter_code`, `title`, `level`, `sort_order`, `description`, `summary`) VALUES
(124, 1, 0, '6', '第 6 章 面向对象程序设计（上）', 1, 6, '本章围绕类与对象展开，依次介绍面向对象概述（面向过程与面向对象的抽象、封装、继承、多态）、类的定义与对象的创建和访问、静态成员、可见性修饰符（包、模块 module、public、private、包私有访问权限）、数据域封装、变量作用域、对象作为方法的形参与返回值及 var 声明、对象数组、ArrayList、this 引用，以及基本数据类型包装类、BigInteger 与 BigDecimal、Random、Date 等 Java 常用类。', '在信息技术发展过程中，早期的软件规模较小，面向过程的软件开发方法就能很好地解决。随着，软件规模越来越大，问题越来越复杂，面向过程的软件开发方法不足以应对大规模和复杂性高的软件系统开发。于是，面向对象的软件开发方法被提出，并迅速成为一种主流的软件开发方法。支持面向对象软件开发方法的面向对象程序设计语言也如雨后春笋般涌现，并不断发展。面向对象方法是一种软件开发方法，也是一种程序设计范式，比早期的面向过程方法具有明显的优势。面向对象程序设计的主要思想是把构成问题的各个事物抽象成一个个对象，通过对象之间的通信和协作解决问题。面向对象程序设计涉及的主要概念包括：对象、类、封装、继承、多态性、动态绑定、抽象类、接口等。Java 语言是 C++语言之后出现的一种面向对象程序设计语言，它实现了面向对象程序设计的主要概念。\n本章主要围绕类和对象展开介绍，介绍类的定义、对象的创建与使用、静态成员、模块和包、可见性修饰符 public 和 private、数据域封装、变量作用域、对象与方法、对象数组、this 引用等，并介绍了几个 Java 常用类。'),
(125, 1, 124, '6.1', '面向对象概述', 2, 1, '面向对象（Object Oriented，简称 OO）是一种软件开发方法，也是一种编程范式，还是一种对现实世界进行理解和抽象的方法，是计算机软件技术发展到一定阶段产生的。面向对象方法相比于早期的面向过程方法，更加符合人类的思维模式，具有明显的优势。它能把相关的数据和方法封装成一个整体，以更加自然的方式对现实世界进行建模。面向对象程序设计具有三大基本特征：封装、继承、多态。', NULL),
(126, 1, 125, '6.1.1', '面向过程与面向对象的抽象', 3, 1, NULL, NULL),
(127, 1, 125, '6.1.2', '封装', 3, 2, NULL, NULL),
(128, 1, 125, '6.1.3', '继承', 3, 3, NULL, NULL),
(129, 1, 125, '6.1.4', '多态', 3, 4, NULL, NULL),
(130, 1, 124, '6.2', '类与对象', 2, 2, NULL, NULL),
(131, 1, 130, '6.2.1', '类的定义', 3, 1, NULL, NULL),
(132, 1, 130, '6.2.2', '对象创建', 3, 2, NULL, NULL),
(133, 1, 130, '6.2.3', '对象访问', 3, 3, NULL, NULL),
(134, 1, 124, '6.3', '静态成员', 2, 3, '6.2 节介绍的实例成员都是与一个类的某个实例关联在一起的。在访问实例成员时，需要使用某个具体的实例。然而，在有些场景中，有些信息需要被一个类的所有实例共享，或者在调用成员方法时，直接使用类名调用。在这些场景中，类的静态成员需要被使用。', NULL),
(135, 1, 124, '6.4', '可见性修饰符', 2, 4, '可见性修饰符是指确定一个类及其成员可见性的符号，可见性决定了一个类及其成员的可访问性。在 Java 语言中，可见性修饰符有三个：public（公有）、private（私有）、protected（保护），放置在类及其成员之前。可见性修饰符决定了 3 种可访问权限：公有访问权限、私有访问权限、保护访问权限。如果一个类及其成员之前没有使用可见性修饰符，那么该类可以被同一个包中的任何一个类访问。这种默认访问权限被称为包私有（package-private）访问权限或包访问（package-access）权限。', NULL),
(136, 1, 135, '6.4.1', '包', 3, 1, NULL, NULL),
(137, 1, 135, '6.4.2', '模块 module', 3, 2, NULL, NULL),
(138, 1, 135, '6.4.2', 'public、private、包私有访问权限', 3, 3, NULL, NULL),
(139, 1, 124, '6.5', '数据域封装', 2, 5, '在程序清单 6-2 中定义了一个类 Person，其数据域（姓名 name、年龄 age、身高 height、血型、健康否 isHealth 等）都是包私有访问权限。在同一包中的其他类可以直接修改这些数据域。如果数据域是公有访问权限，这些数据域被修改的可能性会扩展到其他任何类。这有可能导致如下两个问题。', NULL),
(140, 1, 124, '6.6', '变量作用域', 2, 6, '类的实例变量和静态变量都是类的变量（class variable）。无论类的变量在类的何处声明，其作用域是整个类。类的变量和方法可以在类中以任意顺序出现，如图 6-19(a)所示。然而，当类的一个变量基于类的另一个变量来进行初始化时，则另一个变量必须先声明，如图 6-19(b)所示。', NULL),
(141, 1, 124, '6.7', '对象与方法', 2, 7, '对象是一种引用类型，一个对象既可以作为一个方法的形参，也可以作为一个方法的返回值类型，还可以在方法中创建一个对象作为局部变量。', NULL),
(142, 1, 141, '6.7.1', '对象作为方法的形参', 3, 1, NULL, NULL),
(143, 1, 141, '6.7.2', '对象作为方法的返回值', 3, 2, NULL, NULL),
(144, 1, 141, '6.7.3', 'var 声明对象作为方法的局部变量', 3, 3, NULL, NULL),
(145, 1, 124, '6.8', '对象数组', 2, 8, '当数组元素是某种类型的对象时，这样的数组可被称为对象数组。例如，下面的语句声明并创建具有 5 个矩形对象的数组：', NULL),
(146, 1, 124, '6.9', 'ArrayList', 2, 9, '对象数组是长度固定的，如果用于存储个数不定的对象，就会出现问题：要么由于对象数组长度不够而不能存储所有对象，要么由于对象数组长度太大而浪费存储空间。为了避免上述问题，Java 语言提供了一个数组列表类 ArrayList（位于 java.util 包中），用来存储不限定个数的某类对象。', NULL),
(147, 1, 124, '6.10', 'this 引用', 2, 10, '关键字 this 用于一个对象引用自身。通过关键字 this，可以引用对象的实例成员。通常，关键字 this 是被隐式使用的。例如，图 6-23 所示的例子，子图(a)的代码与子图(b)的代码是等价的。在子图(b)中，关键字 this 显式引用了对象的实例成员 width、height。程序员编码时，为了简洁通常是按子图(a)的形式编码。基于子图(a)的代码，Java 编译器会生成子图(b)所示的具有关键字 this 的代码。（图 6-23　this 引用隐式使用：a) 类 Rect 中 getArea 方法写为 return width * height；b) 与之等价的代码为 return this.width * this.height，显式使用关键字 this 引用实例成员）', NULL),
(148, 1, 147, '6.9.1', 'this 引用被隐藏数据域', 3, 1, NULL, NULL),
(149, 1, 147, '6.9.2', 'this 调用构造方法', 3, 2, NULL, NULL),
(150, 1, 124, '6.11', 'Java 常用类', 2, 11, NULL, NULL),
(151, 1, 150, '6.11.1', '基本数据类型的包装类', 3, 1, NULL, NULL),
(152, 1, 150, '6.11.2', 'BigInteger 类和 BigDecimal 类', 3, 2, NULL, NULL),
(153, 1, 150, '6.11.3', 'Random 类', 3, 3, NULL, NULL),
(154, 1, 150, '6.11.4', 'Date 类', 3, 4, NULL, NULL),
(155, 1, 124, '6.12', '课程思政', 2, 12, NULL, NULL),
(156, 1, 155, '6.12.1', '树立合作共赢观念，培养团队合作精神', 3, 1, NULL, NULL),
(157, 1, 155, '6.12.2', '树立软件安全意识', 3, 2, NULL, NULL);
