INSERT INTO `knowledge_concept` (`id`, `chapter_id`, `name`, `definition`, `difficulty`, `page`, `page_order`) VALUES
(292, 125, '面向对象', '面向对象（Object Oriented，简称 OO）是一种软件开发方法，也是一种编程范式，还是一种对现实世界进行理解和抽象的方法，是计算机软件技术发展到一定阶段产生的。', 1, 227, 1),
(293, 126, '抽象', '抽象是透过事物的表面现象抽取事物本质特征，同时舍弃事物非本质特征的过程。', 1, 227, 1),
(294, 126, '面向过程抽象', '面向过程抽象是基于功能分解、逐步精化的方式进行的。图 6-1 展示了面向过程抽象的程序结构。现实世界问题域按照功能分解，分解为一个个过程，每个过程对应一个子功能，每个子功能在程序实现时，有其对应的子程序模块。', 1, 228, 1),
(295, 126, '面向对象抽象', '面向对象抽象是一种符合人类习惯的抽象方式。人类观察现实世界时，会把现实世界的事物分为一个个实体，每个实体能做什么，它和其他实体协作做了什么，从而理解现实世界的运作。', 1, 228, 2),
(296, 126, '聚合', '在面向对象方法中，多个对象结合在一起形成一个新的对象，被称为聚合。', 1, 229, 1),
(297, 127, '封装', '在面向对象程序设计语言中，封装（Encapsulation）就是把从现实世界中抽象出来的客观实体封装成类，并且类可以隐藏自己内部的实现细节，让外界不可见，并把需要提供给外界的接口，向外发布。', 1, 229, 1),
(298, 127, '信息隐藏', '因此，封装体现了信息隐藏（information hiding），面向对象程序设计语言一般提供了公有(public)、私有(private)、保护(protected)等访问权限来实现信息隐藏。', 1, 229, 2),
(299, 127, '类', '在程序设计中，类(class)是创建对象的模板，是一组对象公共属性和行为的抽象。', 1, 229, 3),
(300, 127, '实例', '对象也称为实例（instance），一个类的实例就是该类的一个对象。', 1, 229, 4),
(301, 128, '继承', '继承（Inheritance）是指一个类可以无需重新编写现有类的代码而具备现有类的所有功能，并在此基础上可以扩展。通过继承所创建的新类被称为“派生类”、“子类”、“扩展类”，被继承的类被称为“基类”、“父类”、“超类”。', 1, 230, 1),
(302, 128, '单继承', '继承可以分为单继承和多继承。单继承就是一个类只有一个直接父类。', 1, 230, 2),
(303, 128, '多继承', '多继承是指一个扩展类有多个直接父类。', 1, 230, 3),
(304, 129, '多态', '多态（Polymorphism）是指一个对象引用变量在程序运行的不同时刻具有多种形态，具体来讲，就是一个父类类型的引用变量能够指向其任何不同子类的一个实例，从而表现出相应子类实例的行为。多态机制使具有不同内部结构的对象可以共享相同的外部接口。', 1, 230, 1),
(305, 131, '对象标识', '对象标识：也称为对象 ID，是程序中唯一标识一个对象的有效标识符。', 1, 231, 1),
(306, 131, '对象属性', '对象属性：也称为对象的状态或特征，是由具有当前值的数据域来表示的。', 1, 231, 2),
(307, 131, '对象行为', '对象行为：也称为对象操作。对象操作体现了对象的能动性和功能，在程序设计语言中，对象操作由方法(或函数)来定义。', 1, 231, 3),
(308, 131, '构造方法', '类还提供了一种称为构造方法（constructor）的特殊类型方法。一个新对象的创建必须调用相应的构造方法。构造方法虽然也能完成其他操作，但是设计构造方法的目的是为了实例化对象，完成对象属性的初始化工作。', 1, 231, 4),
(309, 131, '类体', '类体一般由三个部分的定义组成，即数据域定义部分、构造方法定义部分、方法定义部分。', 1, 231, 5),
(310, 131, 'UML 类图', '在面向对象分析和设计过程中，程序员可以使用 UML（Unified Modelling Language，统一建模语言）的图形符号进行建模，协助程序员进行可视化分析。', 1, 232, 1),
(311, 132, '引用类型', '用户定义的类是一种用户自定义的数据类型，也是一种引用类型（referrence type）。一个引用类型的变量可以引用该类型的一个实例（对象）。', 1, 233, 1),
(312, 132, '对象引用变量', '引用类型的变量是一个合法的标识符，被称为对象引用变量（referrence variable），也被称为对象名。对象引用变量引用一个对象。', 1, 233, 2),
(313, 132, '对象实体', 'new SimpleRect(3.5, 4.5)会在内存堆中为新创建的对象分配一块内存并初始化该对象的数据域，这个初始化之后的内存块可以被称为对象实体。', 1, 233, 3),
(314, 132, '垃圾回收', 'JVM 会检测垃圾并自动回收垃圾所占据的内存空间，这个过程被称为垃圾回收（garbage collection）。', 1, 234, 1),
(315, 132, '无参构造方法', '通常，一个类会提供一个没有形式参数的构造方法（例如：SimpleRect( )），这样的构造方法被称为无参构造方法。', 1, 234, 2),
(316, 132, '默认构造方法', '这是因为 Java 编译器对源程序进行编译后，会给一个没有明确定义任何构造方法的类自动提供一个默认构造方法（default constructor）。默认构造方法是一个方法体为空的无参构造方法。', 1, 234, 3),
(317, 132, '数据域的默认值', '在 Java 语言中，一个类的数据域是有默认值的。数值类型数据域的默认值是零值，布尔类型数据域的默认值是 false，字符类型数据域的默认值是’\\u0000’，引用类型数据域的默认值是 null。', 1, 235, 1),
(318, 133, '对象成员访问操作符', '使用点操作符(.)，也称为对象成员访问操作符（object member acces operator），通过“对象名.成员变量”的方式访问 person 对象的各个数据域，得到其默认值。', 1, 235, 1),
(319, 133, '实例变量', '数据域 width、height 都是 SimpleRect 类的实例成员变量（简称实例变量）。', 1, 236, 1),
(320, 133, '实例方法', '而成员方法 getArea、getPerimeter，也只能被具体的实例所调用，并能使用具体实例的数据域。这些成员方法被称为实例成员方法（简称实例方法）。', 1, 236, 2),
(321, 134, '静态成员', '静态成员分为静态成员变量（简称静态变量，又称类变量）和静态成员方法（静态方法，又称类方法）。', 1, 237, 1),
(322, 134, '静态变量', '一个类的静态变量是将变量值放在一个该类所有对象都能访问的公共内存位置中的。如果该类的一个实例对静态变量进行了修改，该类的其他实例也会受到影响。', 1, 237, 2),
(323, 134, '静态方法', '一个类的静态方法是无须创建该类的实例就可以被调用的成员方法。例如，Math.sqrt()就是使用类名 Math 调用求平方根运算的方法 sqrt( )，不必创建任何实例。', 1, 237, 3),
(324, 134, '实例成员与静态成员的访问关系', '一个类的实例方法可以访问该类的实例数据域和静态数据域，也可以调用该类的实例方法和静态方法。而一个类的静态方法只能访问该类的静态数据域和调用该类的静态方法，不能访问该类的实例数据域和调用该类的实例方法。', 1, 239, 1),
(325, 135, '可见性修饰符', '可见性修饰符是指确定一个类及其成员可见性的符号，可见性决定了一个类及其成员的可访问性。', 1, 241, 1),
(326, 136, '包', '包（package）可以将一组相关的类或接口（见 7.11 节）组织在一起。当一个应用程序所包含的类较多时，程序员通常会把这些源代码分组放置到不同的包（package）中，从而可以更好地管理已经开发的源代码。', 1, 241, 1),
(327, 136, '包声明语句', '在创建包或将新定义的类、接口放置于某个包中时，需要使用包声明语句。包声明语句要求是程序的第一条非注释和非空白行的语句，而且必须是某源文件的第一条语句，使用关键字 package', 1, 241, 2),
(328, 136, '默认包', '如果一个类在定义时，没有声明包，那么表示该类被放在默认包中。', 1, 241, 3),
(329, 137, '模块', '模块（module）用于组织一组相关包。如果一些包具有较强的相关性，那么可以将这些包分组为一个模块。', 1, 246, 1),
(330, 137, 'requires 与 exports', '一个模块能够通过两个关键字 requires 和 exports，对自身所依赖（requires）的模块和自身导出（exports）的包（package）进行声明。一个模块只能使用其他模块导出（exports）的包（package），其他模块也只能使用该模块导出（exports）的包（package）。', 1, 246, 2),
(331, 137, '模块描述符文件', '在该文件夹（如 edu.guet.module）下创建一个 module-info.java 文件，这个文件被称为模块描述符文件。', 1, 246, 3),
(332, 137, '定向导出', 'exports 还支持定向导出包，即导出的包仅仅向特定模块公开', 1, 247, 1),
(333, 138, 'public 访问权限', '可见性修饰符 public（公有的）可以放置在类、方法和数据域前，表示这些类、方法和数据域可以被任何其他的类访问。', 1, 247, 1),
(334, 138, 'private 访问权限', '可见性修饰符 private（私有的）可以放置在方法、数据域前，表示这些方法、数据域只能被它们所在的类访问，不能被其他的类访问。此外，private 不能用来修饰类。', 1, 247, 2),
(335, 138, '包私有访问权限', '如果没有使用可见性修饰符放置在类、方法和数据域前，那么这些类、方法、数据域默认具有包私有访问权限，可以被同一个包中的成员访问，但是不能被其他包中的成员访问。', 1, 248, 1),
(336, 139, '数据域封装', '为了避免外部其他类对一个类的数据域直接进行修改，可以使用 private 修饰符将数据域声明为私有的，这被称为数据域封装。将数据域设置为私有的，可以保护数据不被外部其他类直接修改，使得程序更容易维护。', 1, 249, 1),
(337, 139, '获取方法与设置方法', '为了获取私有数据域的值，可以提供一个获取方法（getter）返回数据域的值。为了修改私有数据域的值，可以提供一个设置方法(setter)为数据域设置新值。', 1, 249, 2),
(338, 140, '类的变量', '类的实例变量和静态变量都是类的变量（class variable）。无论类的变量在类的何处声明，其作用域是整个类。', 1, 250, 1),
(339, 140, '局部变量', '在方法内定义的变量被称为局部变量。局部变量作用域是从声明的地方开始有效，直到包含它的块结束。', 1, 251, 1),
(340, 140, '变量隐藏', '如果一个局部变量和类的变量同名，那么局部变量优先，而同名的类的变量将被隐藏(hidden)，这被称为变量隐藏。', 1, 251, 2),
(341, 142, '对象作为方法的形参', '当对象作为方法的形参时，实参将自己的引用值传递给形参，形参和实参会引用同一片内存区域，因此形参对内存区域的改变也会影响到实参。', 1, 251, 1),
(342, 142, '值传递', '在 Java 语言中，参数传递本质上仅有一种方式，即值传递。无论一个方法的形参是基本数据类型或是引用数据类型，实参传递给形参的都是实参的值。', 1, 251, 2),
(343, 143, '对象作为方法的返回值', '当一个对象类型作为方法返回值，需要使用类名作为方法的返回值类型。', 1, 253, 1),
(344, 144, 'var 声明方式', 'var 声明方式可以使用关键字 var 替代类名，使得代码更简洁。局部变量的类型通过赋值语句右边的表达式进行推断。', 1, 254, 1),
(345, 144, 'var 的使用限制', '使用关键字 var 还需注意：关键字 var 只能用于方法中的局部变量定义，不能用于形式参数声明。', 1, 254, 2),
(346, 145, '对象数组', '当数组元素是某种类型的对象时，这样的数组可被称为对象数组。', 1, 255, 1),
(347, 145, '对象数组的两个层次引用', '访问对象数组的数组元素时，系统会执行两个层次的引用。', 1, 255, 2),
(348, 146, 'ArrayList', '为了避免上述问题，Java 语言提供了一个数组列表类 ArrayList（位于 java.util 包中），用来存储不限定个数的某类对象。', 1, 257, 1),
(349, 146, '数组列表的初始容量', '数组列表类 ArrayList 对象在创建时具备初始容量，一个 ArrayList 对象实际上就是一个能够容纳多个同类对象的列表。当一个列表中存储的对象数量快要超过其初始容量时，列表会自动扩充容量。', 1, 257, 2),
(350, 146, 'Arrays.asList', '首先，使用方法 Arrays.asList()可以实现从一个对象数组创建一个数组列表对象', 1, 260, 1),
(351, 146, 'toArray', '其次，使用 ArrayList 的实例方法 toArray()可以实现从一个数组列表对象创建一个对象数组', 1, 260, 2),
(352, 147, 'this 引用', '关键字 this 用于一个对象引用自身。通过关键字 this，可以引用对象的实例成员。通常，关键字 this 是被隐式使用的。', 1, 260, 1),
(353, 147, 'this 必须显式使用的两种情况', '然而，this 引用在两种情况下是必须显式使用的：（1）需要引用被方法或构造方法的参数所隐藏的数据域时；（2）需要调用一个重载的构造方法时。', 1, 260, 2),
(354, 147, 'this 引用被隐藏数据域', '由于参数与数据域同名，在构造方法或设置方法中，需要显式使用关键字 this 来引用被隐藏的数据域名称。', 1, 261, 1),
(355, 147, '被隐藏变量的访问方式', '被隐藏的实例变量，可以通过 this 引用来访问。被隐藏的静态变量，可以通过类名来访问。其访问形式为：类名.静态变量。', 1, 261, 2),
(356, 147, 'this 调用构造方法', '关键字 this 可以在一个类的构造方法中使用，用于调用该类的另一个构造方法。', 1, 261, 3),
(357, 147, 'this 调用构造方法的位置要求', '需要注意的是，在一个构造方法使用 this 调用其他构造方法时，this 调用其他构造方法的语句应该是该构造方法的第一条语句。', 1, 261, 4),
(358, 151, '基本数据类型的包装类', 'Java 语言的所有基本类型都有其对应包装类。即，针对八个基本数据类型(byte、short、int、long、float、double、char、boolean)，Java 提供了对应八个包装类（Byte、Short、Integer、Long、Float、Double、Character、Boolean）。', 1, 262, 1),
(359, 151, '数值包装类的共有方法', '数值包装类（Byte、Short、Integer、Long、Float、Double）的使用非常相似，都具有方法：byteValue( )、shortValue( )、intValue( )、longValue( )、floatValue( )、doubleValue( )。这些方法可将对象转化为基本数据类型值。', 1, 262, 2),
(360, 151, '不可变对象', '基本数据类型包装类都是最终类（7.4 节介绍），意味着所有包装类的实例一旦创建，就都是不可变的，即包装类实例包含的值就不能再改变了。', 1, 264, 1),
(361, 151, '静态工厂方法 valueOf', '为了提升性能，构建基本数据类型包装类对象，建议采用静态的工厂方法 valueOf（工厂模式是一种设计模式，这里不展开介绍）进行创建。这种创建方式具有更好的空间和时间性能。', 1, 264, 2),
(362, 151, 'MAX_VALUE 与 MIN_VALUE', '每一个数值包装类都有常量 MAX_VALUE 和 MIN_VALUE。常量 MAX_VALUE 表示对应的基本数据类型的最大值。对于 Byte、Short、Integer 和 Long 而言，常量 MIN_VALUE 表示对应的基本数据类型的最小值。', 1, 265, 1),
(363, 151, '解析方法 parseXXX', '每个数值包装类都提供了相应的静态解析方法 parseXXX(String s)（XXX 代表 Byte、Short、Int、Long、Float、Double 中的任意一个），将字符串转换成相应的基本数据类型。', 1, 266, 1),
(364, 151, '装箱', '基本数据类型值被转换为包装类对象的过程被称为装箱（boxing），与之相反的过程被称为拆箱（unboxing）。', 1, 268, 1),
(365, 151, '自动装箱与自动拆箱', '如果一个基本数据类型值出现在需要使用对象的上下文环境中，Java 编译器会对基本数据类型值进行自动装箱。如果一个包装类对象出现在需要使用基本数据类型值的上下文环境中，Java 编译器会对包装类对象进行自动拆箱。', 1, 268, 2),
(366, 151, '泛型参数必须是引用类型', '虽然基本数据类型和其包装类类型之间可以自动转换，但是这并不表示在创建 ArrayList 对象时能用基本类型代替包装类。', 1, 268, 3),
(367, 152, 'BigInteger 类与 BigDecimal 类', 'java.math 包中提供了 BigInteger 类和 BigDecimal 类。它们都是最终类，可以分别用于表示任意大小和精度的整数和十进制数，支持非常大的数的计算或者高精度浮点值的计算。', 1, 270, 1),
(368, 152, 'scale', '这里的 scale 是指浮点数指数部分值取反', 1, 272, 1),
(369, 152, 'BigDecimal 的 divide 异常', '其中，方法 divide 被调用时，如果不能终止运行，就会抛出 ArithmeticException 异常。', 1, 272, 2),
(370, 153, 'Random 类', '另一种产生随机数的方法就是使用 java.util.Random 类，Random 类不仅可以产生随机 double 类型值，还可以产生 int、long、float、boolean 类型的随机值。', 1, 272, 1),
(371, 153, '随机数种子', '当创建一个 Random 对象时，必须设置种子或者使用默认的种子。种子是一个用于初始化随机数生成器的数字。如果 Random 的两个实例是采用相同的种子创建的，那么这两个实例会产生相同的随机数列。', 1, 273, 1),
(372, 154, 'Date 类', 'Java 语言提供了与系统无关的对日期和时间的封装类 java.util.Date，它表示以毫秒为单位的具体时刻。', 1, 273, 1),
(373, 154, 'Unix 时间戳', '1970 年是操作系统 Unix 正式发布的时间。Unix 时间戳是 Java 语言时间系统的一个基准时间。', 1, 274, 1),
(374, 157, '软件安全', '软件安全（Software Security）就是使软件在受到恶意攻击的情形下依然能够继续正确运行及确保软件被在授权范围内合法使用的思想。', 1, 275, 1);
INSERT INTO `knowledge_code_snippet` (`id`, `chapter_id`, `title`, `code`, `is_key_example`, `page`, `page_order`) VALUES
(294, 131, '类声明的一般形式', '[修饰符] class 类名{\n\n      //数据域定义部分\n      //构造方法定义部分\n      //方法定义部分\n}', 0, 231, 1),
(295, 131, '程序清单 6-1　SimpleRect.java', '1  public class SimpleRect {\n2    //数据域定义\n3    double width;\n4    double height;\n5\n6    //构造方法定义\n7    SimpleRect(){\n8    }\n9    SimpleRect(double w, double h){\n10     width = w;\n11     height = h;\n12  }\n13\n14 //方法定义\n15 void setWidth(double w){\n16       width = w;\n17    }\n18    void setHeight(double h){\n19       height = h;\n20    }\n21    double getArea(){\n22       return width * height;\n23    }\n24    double getPerimeter(){\n25    return 2 * (width + height);\n26    }\n27 }', 0, 232, 2),
(296, 131, 'UML 类图中数据域的表示形式', '数据域名: 数据类型', 0, 232, 3),
(297, 131, 'UML 类图中构造方法的表示形式', '类名（参数名 1: 数据类型 1, 参数名 2: 数据类型 2, …）', 0, 232, 4),
(298, 131, 'UML 类图中方法的表示形式', '方法名(参数名 1: 数据类型 1, 参数名 2: 数据类型 2, …): 返回值类型', 0, 233, 5),
(299, 132, '对象声明的一般形式', '类名 对象名;', 0, 233, 6),
(300, 132, '对象创建的一般形式', '对象名 = new 类名(实参列表);', 0, 233, 7),
(301, 132, '对象声明与创建结合的一般形式', '类名 对象名 = new 类名(实参列表);', 0, 233, 8),
(302, 132, '先声明后创建 rect1 对象的两行语句', 'SimpleRect rect1;\n\nrect1 = new SimpleRect(3.5, 4.5);', 0, 233, 9),
(303, 132, '声明与创建合为一行的 rect1 对象创建语句', 'SimpleRect rect1 = new SimpleRect(3.5, 4.5);', 0, 233, 10),
(304, 132, '基本数据类型变量赋值示例', 'int i = 2;', 0, 233, 11),
(305, 132, '构造方法误加 void 的错误定义', 'public void SimpleRect( ){\n}', 0, 234, 12),
(306, 132, '调用无参构造方法创建矩形对象 rect2', 'SimpleRect rect2 = new SimpleRect( );', 0, 234, 13),
(307, 132, '程序清单 6-2　Person.java', '1  public class Person {\n\n2    String name;             //一个人的姓名\n\n3    int age;                 //一个人的年龄\n\n4    double height;           //一个人的身高\n\n5    char  血型;              //一个人的血型\n\n6    boolean isHealth;        //一个人是否处于健康状态\n\n7  }', 0, 235, 14),
(308, 132, '程序清单 6-3　TestPerson.java', '1  public class TestPerson {\n\n2    public static void main(String[] args) {\n\n3         //默认构造方法创建一个对象\n\n4         Person person = new Person();\n\n5         System.out.println("姓名：" + person.name);\n\n6         System.out.println("年龄：" + person.age);\n\n7         System.out.println("身高：" + person.height);\n\n8         System.out.println("血型：" + person.血型);\n\n9         System.out.println("是否健康：" + person.isHealth);\n\n10   }\n\n11 }', 0, 235, 15),
(309, 132, '程序清单 6-3 运行结果', '姓名：null\n\n年龄：0\n身高：0.0\n\n血型：\n\n是否健康：false', 0, 235, 16),
(310, 133, '对象成员访问操作符使用的一般形式', '对象引用变量.数据域;\n对象引用变量.方法(实参列表);', 0, 235, 17),
(311, 133, '程序清单 6-4　TestSimpleRect.java', '1  public class TestSimpleRect {\n\n2      public static void main(String[] args) {\n\n3        //创建对象\n\n4        SimpleRect rect1 = new SimpleRect();\n\n5        SimpleRect rect2 = new SimpleRect(3, 4);\n\n6\n\n7        System.out.printf("%-8s%-8s%-8s%-8s%-8s\\n","矩形","宽","高","面积","周长");\n\n8        System.out.printf("%-8s%-8.2f%-8.2f%-8.2f%-8.2f\\n","矩形 1", rect1.width,\n\n9             rect1.height, rect1.getArea(),rect1.getPerimeter());\n\n10       System.out.printf("%-8s%-8.2f%-8.2f%-8.2f%-8.2f\\n","矩形 2", rect2.width,\n\n11          rect2.height, rect2.getArea(),rect2.getPerimeter());\n\n12\n\n13       rect1.setHeight(2.5);\n\n14       rect1.setWidth(5.5);\n\n15       System.out.println("矩形 1 在修改宽和高之后---------");\n\n16       System.out.printf("%-8s%-8.2f%-8.2f%-8.2f%-8.2f\\n","矩形 1", rect1.width,\n\n17          rect1.height, rect1.getArea(),rect1.getPerimeter());\n\n18   }\n\n19 }', 0, 236, 18),
(312, 133, '程序清单 6-4 运行结果', '矩形  宽       高                面积             周长\n\n矩形 1 0.00 0.00 0.00 0.00\n\n矩形 2 3.00 4.00 12.00 14.00\n\n矩形 1 在修改宽和高之后---------\n\n矩形 1 5.50 2.50 13.75 16.00', 0, 236, 19),
(313, 134, '静态变量声明的一般形式', 'static 数据类型 变量名;', 0, 237, 20),
(314, 134, '静态方法声明的一般形式', '[其他修饰符] static 返回值类型 方法名(形参列表);', 0, 237, 21),
(315, 134, '程序清单 6-5　RectStaticDemo.java', '1  public class RectStaticDemo {\n\n2     /**矩形的宽和高 */\n\n3     double width, height;\n\n4     /**统计对象数量的静态计数器变量*/\n\n5     static int numOfObject;\n\n6     /**以初值 2、1 创建一个矩形对象，\n\n7     * 计数器变量自增 1 */\n\n8     RectStaticDemo(){\n\n9     width = 2;\n\n10    height = 1;\n\n11    numOfObject++;\n\n12 }\n\n13 /**以指定的值 w、h 创建一个矩形对象，\n\n14    * 计数器变量自增 1 */\n\n15 RectStaticDemo(double w, double h){\n\n16    width = w;\n\n17    height = h;\n\n18    numOfObject++;\n\n19 }\n\n20 /**返回静态计数器变量的值 */\n\n21 static int getNumOfObject(){\n\n22    return numOfObject;\n\n23 }\n\n24 /**返回矩形的面积 */\n\n25 double getArea(){\n\n26    return width * height;\n\n27 }\n\n28 //其他部分略\n\n29 }', 0, 237, 22),
(316, 134, '程序清单 6-6　TestRectStaticDemo.java', '1  public class TestRectStaticDemo {\n\n2      public static void main(String[] args) {\n\n3      //访问静态变量初始值\n\n4      System.out.println("----在创建对象之前----");\n\n5      System.out.println("矩形对象的数量(通过静态方法)："\n\n6                          + RectStaticDemo.getNumOfObject());\n\n7      System.out.println("矩形对象的数量(通过静态变量)："\n\n8                          + RectStaticDemo.numOfObject);\n\n9      //创建对象 rect1\n\n10     RectStaticDemo rect1 = new RectStaticDemo();\n\n11     System.out.println("----在创建对象 rect1 之后----");\n\n12     System.out.printf("矩形对象 rect1 的宽：%.1f,高：%.1f\\n", rect1.width, rect1.height);\n\n13     System.out.println("矩形对象的数量：" + rect1.numOfObject);\n\n14\n\n15     //创建对象 rect2\n\n16     RectStaticDemo rect2 = new RectStaticDemo(3, 4);\n\n17     //修改对象 rect1\n\n18     rect1.width = 2.5;\n\n19     rect1.height = 3.5;\n\n20\n\n21     System.out.println("---在创建对象 rect2 和修改对象 rect1 之后---");\n\n22     System.out.printf("矩形对象 rect2 的宽：%.1f,高：%.1f\\n", rect2.width, rect2.height);\n\n23     System.out.printf("矩形对象 rect1 的宽：%.1f,高：%.1f\\n", rect1.width, rect1.height);\n\n24     System.out.println("矩形对象的数量(通过 rect2 访问)：" + rect2.numOfObject);\n\n25     System.out.println("矩形对象的数量(通过 rect1 访问)：" + rect1.getNumOfObject());\n\n26     System.out.println("矩形对象的数量(通过类名访问)："\n\n27                    + RectStaticDemo.numOfObject);\n\n28 }\n\n29 }', 0, 238, 23),
(317, 134, '程序清单 6-6 运行结果', '----在创建对象之前----\n\n矩形对象的数量(通过静态方法)：0\n\n矩形对象的数量(通过静态变量)：0\n\n----在创建对象 rect1 之后----\n\n矩形对象 rect1 的宽：2.0,高：1.0\n\n矩形对象的数量：1\n\n---在创建对象 rect2 和修改对象 rect1 之后---\n\n矩形对象 rect2 的宽：3.0,高：4.0\n\n矩形对象 rect1 的宽：2.5,高：3.5\n\n矩形对象的数量(通过 rect2 访问)：2\n\n矩形对象的数量(通过 rect1 访问)：2\n\n矩形对象的数量(通过类名访问)：2', 0, 239, 24),
(318, 134, '静态方法直接访问实例成员的编译错误示例', '1  public class TestStatic {\n\n2      int i = 1;\n\n3      static int j = 2;\n\n4      public static void main(String[] args) {\n\n5         int k1 = i; //错误，静态方法不能访问实例变量 i\n\n6         method1(); //错误，静态方法不能调用实例方法 method1\n\n7         int k2 = method2(2);//正确，静态方法可以调用另一个静态方法\n\n8      }\n\n9      //实例方法可以访问静态变量和静态方法\n\n10 public void method1(){\n\n11       i = i + j + method2(i);\n\n12 }\n\n13 //静态方法可以访问静态变量\n\n14 public static int method2(int k){\n\n15       return k * j;\n\n16 }\n\n17 }', 0, 239, 25),
(319, 134, '静态方法通过对象访问实例成员的正确示例', '1  public class TestStatic {\n\n2      int i = 1;\n\n3      static int j = 2;\n\n4      public static void main(String[] args) {\n\n5         TestStatic obj = new TestStatic ();\n\n6         int k1 = obj.i; //正确，静态方法访问的是对象 obj 的实例变量 i\n\n7         obj.method1(); //正确，静态方法调用的是对象 obj 的实例方法 method1\n\n8         int k2 = method2(2);//正确，静态方法可以调用另一个静态方法\n\n9    }\n\n10   //实例方法可以访问静态变量和静态方法\n\n11 public void method1(){\n\n12       i = i + j + method2(i);\n\n13 }\n\n14   //静态方法可以访问静态变量\n\n15 public static int method2(int k){\n\n16       return k * j;\n\n17 }\n\n18 }', 0, 240, 26),
