(329, 138, 'private 修饰类成员的访问特性示例（图 6-16）', 'public class Cls1{\n   public static void main(String[ ] args){\n      Cls1 c = new Cls1();\n      System.out.println(c.x);\n      System.out.println(c.f1());\n  }\n  private int x;\n  private int f1( ){\n     return ++x;\n  }\n}\n\npublic class Cls2{\n   public static void main(String[ ] args){\n      Cls1 c = new Cls1();\n      System.out.println(c.x); //错误\n      System.out.println(c.f1()); //错误\n  }\n}', 0, 248, 36),
(330, 138, '可见性修饰符修饰数据域和方法（图 6-17）', 'package pkg1;\npublic class Cls1{\n\n   private int x;\n   int y;\n   public int z;\n   private void f1( ){ }\n   void f2( ){ }\n   public void f3( ){ }\n}\n\npackage pkg1;\npublic class Cls2{\n\n   void f( ){\n      Cls1 c1=new Cls1( );\n      不可访问 c1.x;\n      可访问 c1.y;\n      可访问 c1.z;\n      不能调用 c1.f1();\n      能调用 c1.f2();\n      能调用 c1.f3();\n      }\n\n}\n\npackage pkg2;\npublic class Cls3{\n\n   void f( ){\n      Cls1 c1=new Cls1( );\n      不可访问 c1.x;\n      不可访问 c1.y;\n      可访问 c1.z;\n      不能调用 c1.f1();\n      不能调用 c1.f2();\n      能调用 c1.f3();\n      }\n\n}', 0, 248, 37),
(331, 138, '可见性修饰符修饰类（图 6-18）', 'package pkg1;\nclass Cls1{\n\n     能访问 Cls2\n     能访问 Cls3\n}\n\npackage pkg1;\npublic class Cls2{\n\n     能访问 Cls1\n}\n\npackage pkg2;\npublic class Cls3{\n\n     不能访问 Cls1\n     能访问 Cls2\n}', 0, 249, 38),
