(335, 139, '程序清单 6-7　Rect_v1.java', '1  public class Rect_v1 {\n\n2  //私有数据域定义\n\n3  private double width;\n\n4  private double height;\n\n5\n\n6  //构造方法定义\n\n7  public Rect_v1(){\n\n8  }\n\n9     public Rect_v1(double w, double h){\n\n10    setWidth(w);\n\n11    setHeight(h);\n\n12 }\n\n13\n\n14 //私有数据域的设置方法和获取方法\n\n15 public void setWidth(double w){\n\n16    if(w > 0)\n\n17          width = w;\n\n18    else\n\n19          width = 0;\n\n20 }\n\n21 public double getWidth(){\n\n22    return width;\n\n23 }\n\n24 public void setHeight(double h){\n\n25    if(h > 0)\n\n26          height = h;\n\n27    else\n\n28          height = 0;\n\n29 }\n\n30 public double getHeight() {\n\n31    return height;\n\n32 }\n\n33 //求面积和周长方法\n\n34 double getArea(){\n\n35    return getWidth() * getHeight();\n\n36 }\n\n37 double getPerimeter(){\n\n38    return 2 * (getWidth() + getHeight());\n\n39 }\n\n40 }', 0, 249, 42),
(336, 140, '类变量作用域与声明顺序示例（图 6-19）', '// 图 6-19a　数据域 x、y 和方法 add 以任意顺序声明\npublic class Cls1{\n   public int add( ){\n     return x + y;\n  }\n  private int x;\n  private int y;\n}\n\n// 图 6-19b　x 必须在 y 之前声明\npublic class Cls2{\n   private int x;\n   private int y = x * x;\n   …\n}', 0, 251, 43),
(337, 140, '程序清单 6-7 运行结果', '// 图 6-20a　类变量被隐藏\npublic class Cls1{\n   public void m1(){\n    int y = 5;\n    System.out.println("x=" + x);\n    System.out.println("y=" + y);\n  }\n  private int x;\n  private int y;\n}\n\n// 图 6-20b　运行测试\npublic class Test{\n   public static void main(String[] args){\n      Cls1 c = new Cls1();\n      c.m1();\n   }\n}', 0, 251, 44),
(338, 140, '程序清单 6-7 运行结果', '运行结果：\nx=0\ny=5', 0, 251, 45),
(339, 142, '程序清单 6-8　TestPassValue.java', '1  public class TestPassValue {\n\n2    public static void main(String[] args) {\n\n3         Rect_v1 r1 = new Rect_v1(2.0, 3.0);\n\n4         System.out.printf("Before Invoking, Rect Area:%.2f; height=%.2f",\n\n5            r1.getArea(), r1.getHeight());\n\n6\n\n7         int count = 5;\n\n8         printRect(r1, count);\n\n9\n\n10        System.out.printf("\\nAfter Invoking, Rect Area:%.2f; height=%.2f",\n\n11           r1.getArea(), r1.getHeight());\n\n12        System.out.println("\\ncount = " + count);\n\n13 }\n\n14 //n>=1\n\n15 public static void printRect(Rect_v1 r, int n){\n\n16        System.out.println("\\nWidth \\t Height \\t Area");\n\n17        for(int i = 0;i < n; i++){\n\n18           System.out.printf("%6.2f \\t %6.2f \\t %.2f\\n", r.getWidth(),\n\n19           r.getHeight(), r.getArea());\n\n20           r.setHeight(r.getHeight() + 1);\n\n21        }\n\n22 }\n\n23 }', 0, 252, 46),
