(352, 146, '程序清单 6-11　ArrayListDemo1.java', '1  import java.util.ArrayList;\n\n2  public class ArrayListDemo1 {\n\n3      public static void main(String[] args) {\n\n4       //创建一个列表存储历史人物名称\n\n5       ArrayList<String> names = new ArrayList<>();\n\n6       names.add("刘备");\n\n7       names.add("关羽");\n\n8       names.add("张飞");\n\n9       names.add("诸葛亮");\n\n10       names.add("庞统");\n\n11       names.add("赵云");\n\n12       //测试常用方法，并输出结果\n\n13       System.out.println("三国-蜀人物："+names);\n\n14       System.out.println("列表大小：" + names.size());\n\n15       System.out.println(names.contains("张飞")?"张飞在列表":"张飞不在列表" );\n\n16       System.out.println("张飞的索引值："+names.indexOf("张飞"));\n\n17       System.out.println("马超的索引值："+names.indexOf("马超"));\n\n18       System.out.println("列表是否为空：" + names.isEmpty());\n\n19       System.out.println("取索引为 3 的值：" + names.get(3));\n\n20       //变更列表\n\n21       System.out.println("列表中人物变更：");\n\n22       //移除庞统,列表变为[刘备, 关羽, 张飞, 诸葛亮, 赵云]\n\n23       names.remove("庞统");\n\n24       //增加法正，[刘备, 关羽, 张飞, 诸葛亮, 法正, 赵云]\n\n25       names.add(4, "法正");\n\n26       //通过索引值 2，移除张飞，[刘备, 关羽, 诸葛亮, 法正, 赵云]\n\n27       names.remove(2);\n\n28       //通过循环输出列表\n\n29       for(int i = 0; i < names.size(); i++)\n\n30            System.out.printf("%-4s", names.get(i));\n\n31       //再次调整列表\n\n32       System.out.println("列表中人物再次变更：");\n\n33       //修改指定位置 0 的元素，[刘禅, 关羽, 诸葛亮, 法正, 赵云]\n\n34       names.set(0, "刘禅");\n\n35       System.out.println("取索引为 0 的值：" + names.get(0));\n\n36       //修改指定位置 3 的元素，[刘禅, 关羽, 诸葛亮, 魏延, 赵云]\n\n37       names.set(3,"魏延");\n\n38       //通过 foreach 循环输出列表\n\n39       for(String s: names)\n\n40            System.out.printf("%-4s", s);\n\n41\n\n42       //使用列表存储自定义类 Rect_v1 对象\n\n43       ArrayList<Rect_v1> rectList = new ArrayList<>();\n\n44       //增加两个矩形对象\n\n45       rectList.add(new Rect_v1());\n\n46       rectList.add(new Rect_v1(2.5, 3.5));\n\n47       //输出索引值为 1 的矩形对象周长\n\n48       System.out.println("\\n 一个矩形的周长：" +\n\n49             rectList.get(1).getPerimeter());\n\n50  }\n\n51 }', 0, 258, 59),
(353, 146, '程序清单 6-11 运行结果', '三国-蜀人物：[刘备, 关羽, 张飞, 诸葛亮, 庞统, 赵云]\n列表大小：6\n\n张飞在列表\n\n张飞的索引值：2\n\n马超的索引值：-1\n列表是否为空：false\n取索引为 3 的值：诸葛亮\n列表中人物变更：\n刘备 关羽 诸葛亮 法正 赵云 列表中人物再次变更：\n取索引为 0 的值：刘禅\n刘禅 关羽 诸葛亮 魏延 赵云\n一个矩形的周长：12.0', 0, 259, 60),
