(366, 152, 'BigDecimal 字符串构造的 [BigInteger, scale] 示例', '"0"           [0, 0]\n"0.00"        [0, 2]\n"123"         [123, 0]\n"-123"        [-123, 0]\n"1.23E3"      [123, -1]\n"1.23E+3"     [123, -1]\n"12.3E+7"     [123, -6]\n"12.0"        [120, 1]\n"12.3"        [123, 1]\n"0.00123"     [123, 5]\n"-1.23E-12"   [-123, 14]\n"1234.5E-4"   [12345, 5]\n"0E+7"        [0, -7]\n"-0"          [0, 0]', 0, 272, 73),
(367, 153, '程序清单 6-13　TestRandom.java', '1  public class TestRandom {\n2     public static void main(String[] args) {\n3             Random random1 = new Random(5);\n4             System.out.print("From random1: ");\n5             for (int i = 0; i < 10; i++)\n6             System.out.print(random1.nextInt(100) + " ");\n7             Random random2 = new Random(5);\n8             System.out.print("\\nFrom random2: ");\n9             for (int i = 0; i < 10; i++)\n10            System.out.print(random2.nextInt(100) + " ");\n11   }\n12 }', 0, 273, 74),
(368, 153, '程序清单 6-13 运行结果', 'From random1: 87 92 74 24 6 5 54 91 22 21\nFrom random2: 87 92 74 24 6 5 54 91 22 21', 0, 273, 75),
(369, 154, 'Date 的 toString 返回字符串格式', 'dow mon dd hh:mm:ss zzz yyyy', 0, 274, 76),
(370, 154, '程序清单 6-14　TestDate.java', '1  public class TestDate {\n2         public static void main(String[] args) {\n3            java.util.Date date = new java.util.Date();\n4            System.out.println("自 1970 年 1 月 1 日起，消逝的时间为：" +\n5            date.getTime() + "毫秒");\n6            System.out.println(date.toString());\n7\n8            date.setTime(60000);\n9            System.out.println("自 1970 年 1 月 1 日起消逝 60 秒后的时间："\n10           + date.toString());\n11\n12           System.out.println("自 1970 年 1 月 1 日起,消逝的时间："\n13                         + System.currentTimeMillis() + "毫秒");\n14        }\n15 }', 0, 274, 77),
(371, 154, '程序清单 6-14 运行结果', '自 1970 年 1 月 1 日起，消逝的时间为：1674007257486 毫秒\nWed Jan 18 10:00:57 CST 2023\n自 1970 年 1 月 1 日起消逝 60 秒后的时间：Thu Jan 01 08:01:00 CST 1970\n自 1970 年 1 月 1 日起,消逝的时间：1674007257553 毫秒', 0, 274, 78);
INSERT INTO `knowledge_content` (`id`, `chapter_id`, `knowledge_point_id`, `content_type`, `content`, `page`, `page_order`) VALUES
(1144, 124, NULL, 1, '(1) 理解面向过程抽象与面向对象抽象', 227, 1),
(1145, 124, NULL, 1, '(2) 理解面向对象三大特征', 227, 2),
(1146, 124, NULL, 1, '(3) 理解类与对象的关系，能够定义类、创建对象和访问对象成员', 227, 3),
(1147, 124, NULL, 1, '(4) 理解 UML 类图', 227, 4),
(1148, 124, NULL, 1, '(5) 理解静态成员概念，能使用静态成员', 227, 5),
(1149, 124, NULL, 1, '(6) 理解模块、包、public、private 等对访问权限的影响', 227, 6),
(1150, 124, NULL, 1, '(7) 理解数据域封装', 227, 7),
(1151, 124, NULL, 1, '(8) 理解变量作用域', 227, 8),
(1152, 124, NULL, 1, '(9) 理解和应用对象作为方法参数和作为方法返回值，能使用 var 定义局部变量。', 227, 9),
(1153, 124, NULL, 1, '(10) 理解对象数组，能使用对象数组', 227, 10),
(1154, 124, NULL, 1, '(11) 理解 this 关键字的含义，能使用 this 引用隐藏数据域和调用构造方法', 227, 11),
(1155, 124, NULL, 1, '(12) 能使用基本数据类型包装类、BigInteger 类、BigDecimal 类、Date 类', 227, 12),
(1156, 124, NULL, 1, '在信息技术发展过程中，早期的软件规模较小，面向过程的软件开发方法就能很好地解决。随着，软件规模越来越大，问题越来越复杂，面向过程的软件开发方法不足以应对大规模和复杂性高的软件系统开发。于是，面向对象的软件开发方法被提出，并迅速成为一种主流的软件开发方法。支持面向对象软件开发方法的面向对象程序设计语言也如雨后春笋般涌现，并不断发展。面向对象方法是一种软件开发方法，也是一种程序设计范式，比早期的面向过程方法具有明显的优势。面向对象程序设计的主要思想是把构成问题的各个事物抽象成一个个对象，通过对象之间的通信和协作解决问题。面向对象程序设计涉及的主要概念包括：对象、类、封装、继承、多态性、动态绑定、抽象类、接口等。Java 语言是 C++语言之后出现的一种面向对象程序设计语言，它实现了面向对象程序设计的主要概念。', 227, 13),
(1157, 124, NULL, 1, '本章主要围绕类和对象展开介绍，介绍类的定义、对象的创建与使用、静态成员、模块和包、可见性修饰符 public 和 private、数据域封装、变量作用域、对象与方法、对象数组、this 引用等，并介绍了几个 Java 常用类。', 227, 14),
(1158, 125, NULL, 1, '面向对象（Object Oriented，简称 OO）是一种软件开发方法，也是一种编程范式，还是一种对现实世界进行理解和抽象的方法，是计算机软件技术发展到一定阶段产生的。面向对象方法相比于早期的面向过程方法，更加符合人类的思维模式，具有明显的优势。它能把相关的数据和方法封装成一个整体，以更加自然的方式对现实世界进行建模。面向对象程序设计具有三大基本特征：封装、继承、多态。', 227, 15),
(1159, 126, 115, 1, '抽象是透过事物的表面现象抽取事物本质特征，同时舍弃事物非本质特征的过程。当现实世界问题被映射到信息世界进行解决时，分析人员需要通过抽象抓住现实世界问题的本质特征。', 227, 16),
(1160, 126, 115, 1, '早期面向过程的抽象方式是把现实世界的问题分解为一个个过程，数据和过程是分离的。而面向对象方法的抽象方式是把现实世界的问题分解过一个一个对象，对象把数据和过程封装在一起。', 228, 1),
(1161, 126, 115, 1, '（1）面向过程抽象', 228, 2),
(1162, 126, 115, 1, '面向过程抽象是基于功能分解、逐步精化的方式进行的。图 6-1 展示了面向过程抽象的程序结构。现实世界问题域按照功能分解，分解为一个个过程，每个过程对应一个子功能，每个子功能在程序实现时，有其对应的子程序模块。每个子程序模块要从数据域中取得自己所需要的数据。（图 6-1　面向过程抽象程序结构：图中上方的“数据域”与中间的若干“子程序模块”相互分离，下方的“现实世界问题域”按功能分解对应到各个子程序模块，子程序模块再到数据域中取数据，体现数据和过程（子程序模块）是分离的）', 228, 3),
(1163, 126, 115, 1, '从图 6-1 中可以看出，面向过程抽象一个重要的特点是功能分解，数据和过程(子程序模块)是分离的。数据和过程的关联关系要由程序员来维护，这对于规模小的程序，不存在太大问题。当程序规模较大时，程序员维护这种关联关系是很费劲的。而且，当需要修改某个子程序模块或某个数据时，要寻找受此次修改影响的所有数据或子程序模块也是一个费劲的事。因此，面向过程抽象是不利于大规模程序的理解和维护的。', 228, 4),
(1164, 126, 115, 1, '（2）面向对象抽象', 228, 5),
(1165, 126, 115, 1, '面向对象抽象是一种符合人类习惯的抽象方式。人类观察现实世界时，会把现实世界的事物分为一个个实体，每个实体能做什么，它和其他实体协作做了什么，从而理解现实世界的运作。面向对象抽象也是按照这种思维方式，从现实世界问题域抽象出一个个相互独立的对象，表示现实世界的实体，弄清楚每个实体具有什么属性，具有哪些动态特征，会与哪些实体进行交互等。面向对象抽象的程序结构如图 6-2 所示。首先，从现实世界问题域中抽象出一个个独立的对象，并确定对象拥有的数据和操作，还要确定对象之间的相互协作，这也是人类观察现实世界的思维方式。然后，程序员用面向对象程序设计语言实现各个对象以及对象之间的协作。由于面向对象抽象将数据和操作封装到一个个能动的对象中，数据和操作之间的对应关系不再由程序员来维护，而由系统自动维护。因此，在面对大规模软件系统开发时，面向对象方法能减轻程序员的负担，有利于提升软件开发和维护的效率。（图 6-2　面向对象抽象程序结构：图中下方的“现实世界问题域”被抽象为上方的“面向对象程序”，其中包含对象 1、对象 2、对象 3、对象 4 直至对象 n 一个个相互独立的对象，对象之间通过协作关系连接）', 228, 6),
(1166, 126, 115, 1, '在面向对象系统中，一些独立的对象依据某种构造结合在一起，能形成新的、特有的属性和功能，可以形成一个更大更复杂的对象。这个更大更复杂的对象也可以成为另一个更大对象的一个组成部分，从而构造出一个更为庞大的系统，这也是面向对象抽象能应对复杂性的原理。这种思维方式，与人类生产复杂实体的思维是一样的。例如，一辆汽车一般由发动机、底盘、车身、电气设备等组成，而一个发动机、一个底盘、一个车身、一个电气设备等本身也是一个对象，它们装配在一起可以形成更为复杂、具有独特功能的一个汽车对象。在面向对象方法中，多个对象结合在一起形成一个新的对象，被称为聚合。', 229, 1),
(1167, 126, 115, 1, '基于面向对象方法对问题求解，抽象出来的一个个对象可表现出如下三个特征。第一个是封装性，从对象的外部来看，除了它用来与外界进行交互的接口之外，对象内部就是一个黑匣子，外部看不到对象的实现细节，这就是封装。例如，一个发动机对象的内部是一个黑匣子，汽车整车生产商无需了解发动机的内部实现细节，它仅需要知道发动机提供的装配接口，就可以在生产线上装配出一辆汽车了。这样也降低了汽车生产商造汽车的难度。第二个是继承性，对象可以衍生出后代，后代对象将拥有父辈的全部能力，这就是继承。例如，一辆汽车对象可以继承交通工具对象的全部能力。第三个是多态性，一个对象变量在程序运行的不同时刻可以具有多种不同形态，即指向不同类型的对象，从而具有不同的功能，这就是多态。例如，一个交通工具对象，在程序运行的某个时刻，成为一辆汽车对象，表现出汽车的能力；在另外一个时刻，它变成一艘轮船对象，表现出轮船的能力。', 229, 2),
(1168, 127, 116, 1, '在面向对象程序设计语言中，封装（Encapsulation）就是把从现实世界中抽象出来的客观实体封装成类，并且类可以隐藏自己内部的实现细节，让外界不可见，并把需要提供给外界的接口，向外发布。因此，封装体现了信息隐藏（information hiding），面向对象程序设计语言一般提供了公有(public)、私有(private)、保护(protected)等访问权限来实现信息隐藏。', 229, 3),
(1169, 127, 116, 1, '在程序设计中，类(class)是创建对象的模板，是一组对象公共属性和行为的抽象。例如，张三、李四都是大学生对象，那么可以抽象出一个大学生类，定义一组大学生对象的公共属性和行为。大学生对象的公共属性可以包括：学号、姓名、年龄、籍贯、入学年份、专业、学分绩、已修课程等，其行为可以包括：查询学号、查询专业、查询学分绩、转专业、选课、退课、退学等。通过大学生类，既可以创建张三、李四两个大学生对象，也可以创建其他大学生对象。对象也称为实例（instance），一个类的实例就是该类的一个对象。例如，张三就是大学生类的一个实例。', 229, 4),
(1170, 127, 116, 1, '在抽象一组对象（属于某一类）的公共属性和行为时，要考虑现实世界问题域。例如，大学生对象在不同的问题域中属性和行为是不一样的。当问题域是高校教务管理系统时，大学生对象的属性可以包括：学号、姓名、年龄、籍贯、入学年份、专业、学分绩、已修课程等，其行为可以包括：查询学号、查询专业、查询学分绩、转专业、选课、退课、退学等。当问题域是高校财务管理系统时，大学生对象的属性可以包括：学号、姓名、当前应缴费用、是否缴纳、历史缴费记录等，其行为可以包括：查询应缴费用清单、查询缴费状态、查询历史缴费记录、生成当前缴费收据等。', 230, 1),
(1171, 128, 117, 1, '继承（Inheritance）是指一个类可以无需重新编写现有类的代码而具备现有类的所有功能，并在此基础上可以扩展。通过继承所创建的新类被称为“派生类”、“子类”、“扩展类”，被继承的类被称为“基类”、“父类”、“超类”。本教材为了直观简洁，采用“父类”、“子类”术语。', 230, 2),
(1172, 128, 117, 1, '继承体现了现实世界的分类体系，表达了“是一种”关系，符合人类的思维方式。例如，交通工具可以分为陆地交通工具、水上交通工具、空中交通工具，陆地交通工具、水上交通工具、空中交通工具还可以进一步划分，如图 6-3 所示。 这种分类体系也构成了“是一种”关系，也反映了继承体系。交通工具类是父类，陆地交通工具类、水上交通工具类、空中交通工具类都是交通工具类的子类，并继承了交通工具类的属性和行为。陆地交通工具对于下一层分类而言，也是父类，火车类、汽车类、水陆两栖车类都是陆地交通工具类的子类，并继承了陆地交通工具类的属性和行为。（图 6-3　交通工具分类：三层树状分类图，顶层为“交通工具”，第二层分为“陆地交通工具”“水上交通工具”“空中交通工具”，第三层依次是火车、汽车、水陆两栖车（挂在陆地交通工具下），轮船、快艇（挂在水上交通工具下））', 230, 3),
(1173, 128, 117, 1, '继承可以分为单继承和多继承。单继承就是一个类只有一个直接父类。而多继承是指一个扩展类有多个直接父类。例如，图 6-3 所示火车类只有一个直接父类，就是单继承的情况。而水陆两栖车有两个直接父类，这是多继承的情况。有的面向对象程序语言支持多继承，如 C++语言。而有的面向对象程序设计语言是单继承的，如 Java 语言。支持多继承的语言被称为多继承语言，只支持单继承不支持多继承的语言被称为单继承语言。', 230, 4),
(1174, 129, 118, 1, '多态（Polymorphism）是指一个对象引用变量在程序运行的不同时刻具有多种形态，具体来讲，就是一个父类类型的引用变量能够指向其任何不同子类的一个实例，从而表现出相应子类实例的行为。多态机制使具有不同内部结构的对象可以共享相同的外部接口。例如，以图 6-3 所示的类为例，假设定义了一个引用变量 vehicle 指向一个交通工具类，该引用变量可以在程序运行的某个时刻指向陆地交通工具类的一个实例，也可以指向水上交通工具类或空中交通工具类的一个实例，还可以指向火车类、汽车类等的一个实例。这样，父类引用变量 vehicle 可以在程序运行的不同时刻，具备多种不同的形态。当一个方法的形式参数是交通工具类对象时，那么该方法可以接受的实际参数可以是其任一子类的对象。这样，相同的方法可以接受不同类型的参数，表现出不同的行为。换句话说，这就是同一操作作用于不同类的实例，产生不同的执行结果。这也是多态性的一种外在表现。', 230, 5),
(1175, 131, 119, 1, '在面向对象程序设计语言中，每个对象代表现实世界问题域中可以明确标识的实体，既可以是客观存在的事物，如一个学生、一辆汽车、一个苹果，也可以是抽象的事件，如一场球赛、一次会议。每个对象都有自己独特的标识、属性和行为。', 231, 1),
(1176, 131, 119, 1, '（1）对象标识：也称为对象 ID，是程序中唯一标识一个对象的有效标识符。', 231, 2),
(1177, 131, 119, 1, '（2）对象属性：也称为对象的状态或特征，是由具有当前值的数据域来表示的。例如，一个矩形对象的数据域：宽度（width）为 5.5 和高度（height）为 7.5，它们描述了该矩形对象的当前属性或状态。', 231, 3),
(1178, 131, 119, 1, '（3）对象行为：也称为对象操作。对象操作体现了对象的能动性和功能，在程序设计语言中，对象操作由方法(或函数)来定义。要求一个对象完成一个操作就是调用该对象的一个方法。例如，可以为矩形对象定义计算面积的操作——方法 getArea( )，计算周长的操作——方法 getPerimeter( )，还可以定义设置宽度和高度的操作——方法 setWidth( )、setHeight( )。于是，一个矩形对象（width = 5.5, height = 7.5）要完成计算其面积的操作，可以调用方法 getArea( )，还可以通过调用方法 getPerimeter( )完成计算其周长的操作。另外，还可以通过调用方法 setWidth( )、setHeight( )完成设置其宽度和高度的操作。', 231, 4),
(1179, 131, 119, 1, '一个类定义了同一类型对象的共同属性和行为。类是创建对象的模板，可以通过类创建很多具体的对象。一个类的一个实例（instance）就是该类的一个对象。在面向对象方法中，对象和实例经常可以互换使用。创建对象的过程被称为实例化（instantiation）。', 231, 5),
(1180, 131, 119, 1, '在 Java 语言中，对象的属性（数据域）用变量来定义，对象的行为（操作）用方法来定义。另外，类还提供了一种称为构造方法（constructor）的特殊类型方法。一个新对象的创建必须调用相应的构造方法。构造方法虽然也能完成其他操作，但是设计构造方法的目的是为了实例化对象，完成对象属性的初始化工作。因此，类的组成包括三个部分：数据域定义部分、构造方法定义部分和方法定义部分。', 231, 6),
(1181, 131, 119, 1, '类声明的一般形式是：', 231, 7),
(1182, 131, 119, 1, '关键字 class 在定义类时是必不可少的，其前面既可以不加修饰符，也可以加修饰符。例如，加上修饰符 public，一个类就成为了公有类，一个 Java 源文件只能有一个公有类。在关键字 class 前面还可以加的其他修饰符在后续章节介绍。关键字 class 之后是类名，类名要求是一个合法的标识符。类名之后接着的是一对花括号，这对花括号之间的内容是类体。类体一般由三个部分的定义组成，即数据域定义部分、构造方法定义部分、方法定义部分。数据域定义部分刻画了一类对象共有的属性，方法定义部分描述了一类对象共有的行为，构造方法定义部分主要提供如何初始化对象的描述(也可以有其他操作，但不是构造方法机制的主要目的)。数据域部分和方法部分都是类的成员，数据域部分是类的数据成员，包括成员变量和成员常量，方法部分是类的成员方法。', 231, 8),
(1183, 131, 119, 1, '例如，下面定义一个矩形类 SimpleRect，其数据域有宽度（width）和高度（height），其方法有：计算面积方法 getArea、计算周长方法 getPerimeter、设置宽度方法 setWidth、设置高度方法 setHeight。', 232, 1),
(1184, 131, 119, 1, '矩形类的代码如程序清单 6-1 所示。第 3、4 行定义了数据域：width、height，第 7-12 行定了两个构造方法，第 15-26 行定义了 4 个方法：setWidth、setHeight、getArea、getPerimeter。', 232, 2),
(1185, 131, 119, 1, '在面向对象分析和设计过程中，程序员可以使用 UML（Unified Modelling Language，统一建模语言）的图形符号进行建模，协助程序员进行可视化分析。对于程序清单 6-1 所示的类 SimpleRect，在 UML 中，可以使用类图对其建模，如图 6-4 所示。UML 类图包括三个部分：类名、数据域(属性)、构造方法和方法（操作）。其中，数据域的表示形式为：（图 6-4　UML 类图：SimpleRect：类图分为三格，第一格为类名 SimpleRect；第二格为数据域（属性），即 width: double、height: double；第三格为构造方法和方法（操作），即构造方法 SimpleRect() 和 SimpleRect(w: double, h: double)，方法 setWidth(w: double): void、setHeight(h: double): double、getArea(): double、getPerimeter(): double）', 232, 3),
(1186, 131, 119, 1, '构造方法的表示形式为：', 232, 4),
(1187, 131, 119, 1, '方法的表示形式为：', 233, 1),
(1188, 131, 119, 1, '补充：后续内容会介绍 public、protected、private 访问权限，这三个访问权限在 UML 类图中对应符号分别是+、#、-，还有一个包私有访问权限，不需任何符号。', 233, 2),
(1189, 132, 120, 1, '对象可以先声明后创建，声明的一般形式是：', 233, 3),
(1190, 132, 120, 1, '创建对象的一般形式是：', 233, 4),
(1191, 132, 120, 1, '对象的声明和创建也可以结合在一起，其一般形式是：', 233, 5),
(1192, 132, 120, 1, '在对象创建时，对象名是一个合法的标识符，并且要使用关键字 new，它是专用于创建对象的。关键字 new 之后是构造方法，“类名(实参列表)”就是表示构造方法。例如，下面的两行语句：', 233, 6),
(1193, 132, 120, 1, '等价于下面一行语句：', 233, 7),
(1194, 132, 120, 1, '上面的语句都是创建了一个矩形对象，对象名是 rect1，调用了 SimpleRect 类有两个参数的构造方法，rect1 的数据域初始化为：宽是 3.5，高是 4.5。', 233, 8),
(1195, 132, 120, 1, '对象的创建涉及引用类型、构造方法、数据域默认值，下面分别进行介绍。', 233, 9),
(1196, 132, 120, 1, '用户定义的类是一种用户自定义的数据类型，也是一种引用类型（referrence type）。一个引用类型的变量可以引用该类型的一个实例（对象）。引用类型的变量是一个合法的标识符，被称为对象引用变量（referrence variable），也被称为对象名。对象引用变量引用一个对象。下面通过示例引入对象实体概念，深入理解引用类型。例如，rect1 就是一个对象引用变量，它引用一个矩形对象，其内存示意图如图 6-5 所示。new SimpleRect(3.5, 4.5)会在内存堆中为新创建的对象分配一块内存并初始化该对象的数据域，这个初始化之后的内存块可以被称为对象实体。假设该对象实体在内存堆中的地址值是 0xEFEC，那么对象引用变量 rect1 的内存位置所存储的值就是对象实体的地址值 0xEFEC。rect1 通过这个地址引用对象实体。对象实体的地址值在 Java 语言中也被称为引用值。因此，换句话说，对象名 rect1 存储的是对象实体的引用值。（图 6-5　rect1 对象内存示意图：内存堆中地址 0xEFEC 处的对象实体含有数据域 Width: 3.5 和 Height: 4.5，对象引用变量 rect1 中存放的正是该对象实体的地址值 0xEFEC）', 233, 10),
(1197, 132, 120, 1, '在程序设计语言中，每个变量都代表了一个存储某个值的内存位置。图 6-5 展示了引用类型变量的内存示意图，引用类型变量代表的内存位置存储的值是一个引用值。然而，基本数据类型变量代表的内存位置存储的值是基本类型的值。例如，下面语句：', 233, 11),
(1198, 132, 120, 1, '变量 i 所表示的内存位置存储的值就是 2，如图 6-6 所示。（图 6-6　变量 i 的内存示意图：变量 i 所代表的内存位置中直接存储基本类型的值 2）', 233, 12),
(1199, 132, 120, 1, '将一个基本数据类型变量 a 赋给另一个基本数据类型变量 b 时，即 b = a，可以直接将 a 的值赋给 b。例如，假设已知 i 为 2，j 为 0，执行 j = i，这时，直接将 i 的值 2 赋给 j，j 也变为 2。然而，将一个引用类型变量 ref1 赋值给另一引用类型变量 ref2 时，即 ref2 = ref1，仅仅将 ref1 的引用值赋给 ref2，让 ref2 与 ref1 引用同一个对象实体，而不修改被赋值引用变量的对象实体内容。例如，假设 rect2 也是一个矩形对象，赋值语句 rect2 = rect1 是将 rect1 的引用赋给 rect2，然后，rect1、rect2 同时指向一个对象，如图 6-7 所示。（图 6-7　rect2 = rect1 内存变化示意图：赋值前，rect1 存放 0xEFEC 指向内存堆中 Width:3.5、Height:4.5 的对象，rect2 存放 0xEFFD 指向内存堆中 Width:5.5、Height:7.5 的对象；赋值后，rect1 与 rect2 都存放 0xEFEC 而指向同一个对象，原先由 rect2 引用的 Width:5.5、Height:7.5 的对象不再有引用变量指向它）', 233, 13),
(1200, 132, 120, 1, '注意：rect2 原来的对象实体没有引用变量指向它，JVM 就会认为这个对象实体是垃圾(garbage)。JVM 会检测垃圾并自动回收垃圾所占据的内存空间，这个过程被称为垃圾回收（garbage collection）。', 234, 1),
(1201, 132, 120, 1, '构造方法是一种特殊方法，有三个特殊之处：', 234, 2),
(1202, 132, 120, 1, '(1) 构造方法必须与所在类同名，大小写一致。', 234, 3),
(1203, 132, 120, 1, '(2) 构造方法没有返回值类型，也不能加 void 关键字。', 234, 4),
(1204, 132, 120, 1, '(3) 构造方法只能在创建一个对象时由关键字 new 调用。', 234, 5),
(1205, 132, 120, 1, '一个初学者可能会犯的错误，就是在构造方法定义时使用 void，例如：', 234, 6),
(1206, 132, 120, 1, '在这种情况下，SimpleRect( )就变成一个普通的成员方法，而不是构造方法了。', 234, 7),
(1207, 132, 120, 1, '构造方法允许重载，可以有多个同名但是方法签名不一样的构造方法。例如，在程序清单 6-1 所示的源程序中，第 7-8 行是一个构造方法定义，第 9-12 行是另一个构造方法定义。', 234, 8),
(1208, 132, 120, 1, '通常，一个类会提供一个没有形式参数的构造方法（例如：SimpleRect( )），这样的构造方法被称为无参构造方法。', 234, 9),
(1209, 132, 120, 1, '另外，一个类可能没有定义构造方法。在这种情况下，我们还能不能创建对象呢？', 234, 10),
(1210, 132, 120, 1, '答案是肯定的。这是因为 Java 编译器对源程序进行编译后，会给一个没有明确定义任何构造方法的类自动提供一个默认构造方法（default constructor）。默认构造方法是一个方法体为空的无参构造方法。当一个类明确定义了一个或多个构造方法时，默认构造方法就不再被自动提供。', 234, 11),
(1211, 132, 120, 1, '当一个类通过默认构造方法（方法体为空）创建对象时，该类的数据域是如何初始化的？', 234, 12),
(1212, 132, 120, 1, '程序清单 6-1 所示的源程序所提供的无参构造方法与默认构造方法形式一样，不仅无形式参数，而且方法体也为空。下面通过这个无参构造方法来构建一个矩形对象 rect2，如下所示：', 234, 13),
(1213, 132, 120, 1, '那么，rect2 的宽和高是多少呢？', 234, 14),
(1214, 132, 120, 1, '在 Java 语言中，一个类的数据域是有默认值的。数值类型数据域的默认值是零值，布尔类型数据域的默认值是 false，字符类型数据域的默认值是’\\u0000’，引用类型数据域的默认值是 null。于是，前面问题的答案是：rect2 的宽和高都是 0.0。', 235, 1),
(1215, 132, 120, 1, '下面通过一个示例演示一个类的默认构造方法和数据域的默认值，该示例的代码如程序清单 6-2、程序清单 6-3 所示。', 235, 2),
(1216, 132, 120, 1, '运行结果如下：', 235, 3),
(1217, 132, 120, 1, '运行结果验证了数据域的默认值取值情况。', 235, 4),
(1218, 132, 120, 1, '程序清单 6-2 给出 Person 类的定义，Person 类的定义中只有数据域部分，没有构造方法定义和方法定义。这并不表示 Person 类没有构造方法和方法。Person 类的构造方法和方法均由 Java 编译器提供。首先，Java 编译器会为 Person 类提供一个默认构造方法。其次，Person 类默认继承 Object 类（详细描述见 7.6 节），因此，Object 类的方法也成为 Person 类的方法。', 235, 5),
(1219, 132, 120, 1, '程序清单 6-3 给出了一个测试类 TestPerson。程序清单 6-3 第 4 行使用默认构造方法创建了一个 person 对象。由于默认构造方法体为空，所以默认构造方法没有修改数据域的值。因此，person 对象的数据域保持为默认值。然后，第 5 行~9 行，使用点操作符(.)，也称为对象成员访问操作符（object member acces operator），通过“对象名.成员变量”的方式访问 person 对象的各个数据域，得到其默认值。', 235, 6),
(1220, 133, 121, 1, '在对象创建之后，每个对象具有自己的数据域，可以通过对象成员访问操作符来访问对象自身的数据域和调用方法，对象成员访问操作符使用的一般形式是：', 235, 7),
(1221, 133, 121, 1, '下面的示例是对类 SimpleRect 的使用，代码如程序清单 6-4 所示。', 236, 1),
(1222, 133, 121, 1, '运行结果如下：', 236, 2),
(1223, 133, 121, 1, '程序清单 6-4 第 4、5 行分别创建了两个对象，第 7 行是表格化输出的表头。第 8、9 行通过对象引用变量 rect1 引用自己的数据域和方法，显示对象 rect1 的数据域、面积、周长。因为对象 rect1 是调用无参构造方法创建，其数据域都是默认值，即零值。于是，rect1 的面积和周长均为 0.00，运行结果也验证了这一点。第 10、11 行通过对象引用变量 rect2 引用自己的数据域和方法，显示对象 rect1 的数据域、面积、周长。第 13、14 行修改了对象 rect1 的高度和宽度，第 15、16 行显示修改对象 rect1 的数据域、面积、周长。', 236, 3),
(1224, 133, 121, 1, '从该示例中，可以看出，数据域 width、height 的值是依赖于某个具体实例的。数据域 width、height 都是 SimpleRect 类的实例成员变量（简称实例变量）。而成员方法 getArea、getPerimeter，也只能被具体的实例所调用，并能使用具体实例的数据域。这些成员方法被称为实例成员方法（简称实例方法）。调用实例方法的对象被称为调用对象。例如，rect1.getArea()的调用对象是 rect1，rect1 的数据域被方法 getArea 使用；rect2.getArea()的调用对象是 rect2，rect2 的数据域被方法 getArea 使用。一个类的实例变量与实例方法都是该类的实例成员。', 236, 4),
(1225, 134, 122, 1, '6.2 节介绍的实例成员都是与一个类的某个实例关联在一起的。在访问实例成员时，需要使用某个具体的实例。然而，在有些场景中，有些信息需要被一个类的所有实例共享，或者在调用成员方法时，直接使用类名调用。在这些场景中，类的静态成员需要被使用。', 237, 1),
(1226, 134, 122, 1, '静态成员分为静态成员变量（简称静态变量，又称类变量）和静态成员方法（静态方法，又称类方法）。一个类的静态变量是将变量值放在一个该类所有对象都能访问的公共内存位置中的。如果该类的一个实例对静态变量进行了修改，该类的其他实例也会受到影响。静态变量还可以通过类名直接进行修改。一个类的静态方法是无须创建该类的实例就可以被调用的成员方法。例如，Math.sqrt()就是使用类名 Math 调用求平方根运算的方法 sqrt( )，不必创建任何实例。', 237, 2),
(1227, 134, 122, 1, '一个类的静态成员是随着该类被加载到 JVM 时同时加载的。例如，Java 程序执行的入口方法 main 方法是静态方法，当包含 main 方法的类被 JVM 加载时，main 方法也被加载了，从而无须创建任何实例就可以运行 main 方法。', 237, 3),
(1228, 134, 122, 1, 'Java 语言在定义静态成员时，使用关键字 static 修饰变量或方法。关键字 static 修饰变量时，通常放置在数据类型之前，一般形式如下：', 237, 4),
(1229, 134, 122, 1, '例如：static int count;', 237, 5),
(1230, 134, 122, 1, '当关键字 static 修饰方法时，通常放置在返回值类型之前，一般形式如下：', 237, 6),
(1231, 134, 122, 1, '例如：public static void main(String[] args);', 237, 7),
(1232, 134, 122, 1, '下面引入一个使用静态变量和静态成员的场景示例。假设有一个对平面几何形状进行认知和计数的小游戏，游戏开始时随机生产一定数量的平面几何形状（如矩形、圆形、三角形）在屏幕上，这些几何形状可以被增加、移动或涂色，让小孩子进行辨认和计数。', 237, 8),
(1233, 134, 122, 1, '该游戏软件有一个功能就是游戏本身要能统计每种平面几何形状的数量。实现这种统计功能，使用静态变量和静态方法较为便捷。其策略如下：(1)设计一个静态的计数器变量，初值为零。(2)每当创建一个形状对象时，静态的计数器变量自动加 1。(3)再设计一个返回静态变量值的静态方法。下面以矩形类 RectStaticDemo 为例说明如何使用静态成员完成上述策略，该游戏软件的其他功能描述从略。', 237, 9),
(1234, 134, 122, 1, '矩形类 RectStaticDemo 的代码如程序清单 6-5 所示。', 237, 10),
(1235, 134, 122, 1, '程序清单 6-5 第 5 行定义了一个静态的计数器变量，具有默认初始值 0。第 11、18 行在构造方法中静态的计数器变量执行自增 1 的操作，这就表示每当调用构造方法创建对象时，该计数器变量就加 1，自动完成对象统计功能。第 21-23 行定义了一个静态方法 getNumOfObject()，返回静态计数器变量的值。', 238, 1),
(1236, 134, 122, 1, '程序清单 6-6 所示的测试类 TestCircleStaticDemo 对静态变量和静态方法的使用进行了演示，运行结果表明静态的计数器变量正确地统计了被创建对象的数量。', 238, 2),
(1237, 134, 122, 1, '运行结果如下。', 239, 1),
(1238, 134, 122, 1, '程序清单 6-6 第 4 行~6 行的代码表明在没有创建任何对象之前，静态成员可以由类名直接访问。第 6 行和第 8 行分别通过类名调用静态方法和类名引用静态变量对静态变量进行访问。第 10 行创建了一个矩形对象 rect1，第 11 行~13 行访问了对象 rect1 的信息。第 13 行通过对象 rect1 访问静态变量，与通过类名访问，结果一样。', 239, 2),
(1239, 134, 122, 1, '程序清单 6-6 第 16 行创建了一个矩形对象 rect2，指定其宽为 3.0，其高为 4.0。第 18 行~19 行修改了矩形对象 rect1 的数据域，其宽变为 2.5，其高变为 3.5。矩形对象 rect1 与 rect2 的实例变量是相互独立、互不干扰的。静态变量 numOfObject 是被这两个对象共享的。第 22 行~23 行显示了矩形对象 rect1 与 rect2 的实例数据成员。第 24、25、26 行通过三种不同方式访问了静态变量 numOfObject 的值，验证了静态变量 numOfObject 是被该类所有对象共享的。在创建完矩形对象 rect2 和修改矩形对象 rect1 之后，本示例实例变量和静态变量的内存示意图如图 6-8 所示。（图 6-8　示例的静态变量与实例变量内存示意图：内存中一块公共区域存放静态变量 numOfObject 的值为 2，被 rect1、rect2 两个对象共享；rect1 自身的内存区存放实例变量 2.5 width、3.5 height，rect2 自身的内存区存放实例变量 3.0 width、4.0 height）', 239, 3),
(1240, 134, 122, 1, '注意：虽然通过对象名也能访问静态变量，但是不建议这么使用，避免引起阅读上的混淆。而且，Java 编译器会产生警告错误。静态方法也一样，通过对象名可以访问，也有编译警告错误。因此，静态成员最好用类名来访问，即使用“类名.静态变量”的方式访问静态变量，使用“类名.静态方法(实际参数列表)”的方式访问静态方法。这不仅可以避免编译警告错误，而且可以很容易地识别出类中的静态成员。', 239, 4),
(1241, 134, 122, 1, '静态成员和实例成员的访问关系如图 6-9 所示。一个类的实例方法可以访问该类的实例数据域和静态数据域，也可以调用该类的实例方法和静态方法。而一个类的静态方法只能访问该类的静态数据域和调用该类的静态方法，不能访问该类的实例数据域和调用该类的实例方法。因为，静态成员不属于某个特定的对象。（图 6-9　实例成员与静态成员的关系：左侧“实例方法”可以访问实例数据域、调用实例方法、访问静态数据域、调用静态方法；右侧“静态方法”只能访问静态数据域、调用静态方法，对实例数据域和实例方法则不能访问、不能调用）', 239, 5),
(1242, 134, 122, 1, '如果在静态方法中直接访问实例变量和调用实例方法，Java 编译器会报告编译错误。例如，下面的代码就会产生编译错误。', 240, 1),
(1243, 134, 122, 1, '由于 main 方法是静态方法，它不能访问实例变量和调用实例方法。因此，第 5 行访问实例变量 i 是错误的，第 6 行调用实例方法也是错误的。实例方法访问实例成员和静态成员都是没有问题的，如第 11 行所示。', 240, 2),
(1244, 134, 122, 1, '如果一个类的某个静态方法需要访问该类一个对象的实例变量或调用该类的实例方法，那么就必须在该静态方法中使用对象。例如，如果要把上面示例 TestStatic 的程序修改成正确的程序，就要在 main 方法中创建一个对象，然后通过对象名来访问实例数据域和调用实例方法。修改后的代码（第 5 行至第 7 行）如下所示。', 240, 3),
(1245, 134, 122, 1, '第 5 行在静态方法 main 中创建了一个对象 obj，第 6 行通过对象名 obj 访问了实例变量 i，第 7 行通过对象名调用了实例方法 method1。', 241, 1),
(1246, 135, NULL, 1, '可见性修饰符是指确定一个类及其成员可见性的符号，可见性决定了一个类及其成员的可访问性。在 Java 语言中，可见性修饰符有三个：public（公有）、private（私有）、protected（保护），放置在类及其成员之前。可见性修饰符决定了 3 种可访问权限：公有访问权限、私有访问权限、保护访问权限。如果一个类及其成员之前没有使用可见性修饰符，那么该类可以被同一个包中的任何一个类访问。这种默认访问权限被称为包私有（package-private）访问权限或包访问（package-access）权限。', 241, 2),
(1247, 135, NULL, 1, '自 Java SE 9 开始，新增一个访问控制：模块（module）。', 241, 3),
(1248, 136, 123, 1, '包（package）可以将一组相关的类或接口（见 7.11 节）组织在一起。当一个应用程序所包含的类较多时，程序员通常会把这些源代码分组放置到不同的包（package）中，从而可以更好地管理已经开发的源代码。每个包具有一个独一无二的包名，形成自己的命名空间，有助于防止命名冲突。具体来讲，在两个不同包中出现类名相同的类，是不会产生冲突的。', 241, 4),
(1249, 136, 123, 1, '在创建包或将新定义的类、接口放置于某个包中时，需要使用包声明语句。包声明语句要求是程序的第一条非注释和非空白行的语句，而且必须是某源文件的第一条语句，使用关键字 package，其语法形式：', 241, 5),
(1250, 136, 123, 1, 'packageName（包名）既可以是由一个合法标识符确定的名称，也可以是由多个合法标识符用“.”（点号）连接而成的一个名称。', 241, 6),
(1251, 136, 123, 1, '如果一个类在定义时，没有声明包，那么表示该类被放在默认包中。', 241, 7),
(1252, 136, 123, 1, '一个包的成员包括类、接口、子包。其中，一个包的类和接口在该包的编译单元中，而一个包的子包拥有自己的编译单元和子包。需要注意的是，包与子包是两个独立的编译单元。在导入语句中，导入一个包，并不表示导入了其子包。例如，导入语句', 241, 8),
(1253, 136, 123, 1, '可以导入 javafx.scene 包中类和接口，但是不能导入 javafx.scene 的子包 javafx.scene.layout 中的类和接口，因此，不能代替如下导入语句：', 241, 9),
(1254, 136, 123, 1, '一个包中不能包含两个具有相同名字的成员。即，一个包内的类名、接口名、子包名不能重复出现。例如，因为包 java.awt 有一个子包 image，所以它不能包含一个以 image 命名的类或接口。又如，如果一个命名为 chapter6 的包，拥有一个接口 Print，那么就不能定义一个包名为 chapter6.Print 或 chapter6.Print.doc 的包。', 241, 10),
(1255, 136, 123, 1, '下面以 Eclipse 集成开发环境为例，说明包的创建与使用。在 Eclipse 集成开发环境中，完成如下任务：创建一个包，包名为 chapter6；然后，在该包中创建一个类 Hello，一个接口 Print，一个子包 chapter6.temp，在子包中创建一个类 Hello。', 242, 1),
(1256, 136, 123, 1, '首先，创建一个包 chapter6，所在项目名称为 JavaSrc，创建过程如图 6-10 所示。第一步，鼠标移动到项目名上，右键点击项目名，弹出子菜单，依次在子菜单上左键点击选择 new 和 package，如图 6-10（a）。第二步，在弹出的对话框中，可在 Name 对应的编辑框输入包名：chapter，点击按钮 Finish，完成包 chapter6 的创建，如图 6-10（b）。创建完成后，Package explore 窗口中会出现新增的包 chapter6。（图 6-10　创建包 chapter6：a) 在项目名 JavaSrc 上点击鼠标右键弹出的菜单，菜单中依次选择 new→package；b) 弹出的 New Package 对话框，在 Name 编辑框中填写包名 chapter6，下方为 Finish 按钮）', 242, 2),
(1257, 136, 123, 1, '接下来，在包 chapter6 创建一个类 Hello，如图 6-11 所示。第一步，鼠标移动到包名 chapter6 上，右键点击包名，弹出子菜单，在子菜单上依次选择 New、Class，如图 6-11（a）所示。第二步，在创建类的对话框中，输入类名 Hello，如图 6-11（b）所示。然后，弹出类 Hello 创建成功之后的界面，如图 6-11（c）所示。从图 6-11 中，可以看出，自动生成代码的第一行语句为包声明语句：“package chapter6;”。并且，在 chapter6 包中增加了一个类 Hello。（图 6-11　在包 chapter6 中创建类 Hello：a) 右键点击包 chapter6 后在子菜单中依次选择 New→Class；b) 在 Class 创建对话框的 Name 栏输入类名 Hello；c) 创建完成后的界面，包 chapter6 下出现 Hello.java，编辑器中自动生成的第一行代码为 package chapter6;）', 242, 3),
(1258, 136, 123, 1, '接着，在包 chapter6 创建一个接口 Print，如图 6-12 所示。第一步，鼠标移动到包 chapter6，右键点击弹出子菜单，依次点击选择 New、Interface，如图 6-12（a）所示。第二步，在弹出的创建结构对话框中，输入接口名称：Print，点击按钮 Finish，如图 6-12（b）所示。然后，接口 Print 成功创建的界面出现，如图 6-12（c）所示。接口 Print 的自动生成代码的第一行也是包声明语句：（图 6-12　在包 chapter6 中创建一个接口 Print：a) 右键点击包 chapter6，在弹出子菜单中依次选择 New→Interface；b) 在 Interface 创建对话框的 Name 栏输入接口名 Print；c) 接口 Print 创建后的界面，chapter6 包中新增 Print.java，自动生成的第一行代码为 package chapter6;）', 244, 1),
(1259, 136, 123, 1, '并且，包 chapter6 中增加了一个接口 Print。', 244, 2),
(1260, 136, 123, 1, '然后，在包 chapter6 下创建一个子包 temp，如图 6-13 所示。第一步，鼠标移动到包 chapter6，右键点击，在弹出的子菜单上，依次点击选择 New、Package。第二步，在弹出的创建包的对话框上输入包名：chapter6.temp，表示 temp 包是 chapter6 的子包，如图 6-13（a）所示。创建子包成功之后，在 package explore 窗口，可以看到如图 6-13（b）所示的界面，其子包也是一个单独的包，可用来组织类、接口。（图 6-13　在包 chapter6 中创建子包 temp：a) 在创建包的对话框 Name 栏输入 chapter6.temp；b) 子包创建成功后 Package Explorer 窗口中 chapter6 包下出现 temp 子包）', 245, 1),
(1261, 136, 123, 1, '最后，在包 chapter6.temp 下创建一个类 Hello，如图 6-14 所示。第一步，鼠标移动到包 chapter6.temp 上，右键点击，在弹出的子菜单上一次点击选择 New、Class，如图 6-14（a）所示。第二步，在弹出的创建类的对话框中，输入类名 Hello，再点击按钮 Finish，如图 6-14（b）所示。然后，创建类 Hello 成功的界面如图 6-14（c）所示。类 Hello 的第一行代码是包声明语句：“package chapter6.temp;”。并且，包 chapter6.temp 增加了一个类 Hello。（图 6-14　在包 chapter6.temp 中创建类 Hello：a) 右键点击 chapter6.temp，在子菜单上依次点击 New→Class；b) 在创建类的对话框中 Name 栏输入类名 Hello；c) 创建类 Hello 成功之后的界面，temp 子包下出现 Hello.java，第一行代码为 package chapter6.temp;）', 245, 2),
(1262, 138, 125, 1, '模块（module）用于组织一组相关包。如果一些包具有较强的相关性，那么可以将这些包分组为一个模块。项目、模块、包之间的关系如图 6-15 所示。一个项目可以包括多个模块，每个模块可以包括多个包，模块可以看做包的集合。（图 6-15　项目、模块、包之间的关系：三层包含结构图，最外层为“项目”，其内并列两个方框“模块 1”和“模块 2”，模块 1 内含包 1、包 2、包 3、包 4，模块 2 内含包 5、包 6、包 7）', 246, 1),
(1263, 138, 125, 1, '一个模块能够通过两个关键字 requires 和 exports，对自身所依赖（requires）的模块和自身导出（exports）的包（package）进行声明。一个模块只能使用其他模块导出（exports）的包（package），其他模块也只能使用该模块导出（exports）的包（package）。一个模块能将它的部分包或全部包分类为 exported(导出的)，这意味着这些被导出包的类和接口可以通过模块外部的代码访问。如果一个模块的某个包没有被该模块导出，那么只有模块内部的代码可以访问该包的类和接口。如果一个模块中的代码想要访问另一个模块导出的包，那么第一个模块必须显式依赖于第二个模块。', 246, 2),
(1264, 138, 125, 1, '模块的引入，进一步增强了代码的封装性。一个模块可以显式选择向其他模块只暴露需要的类或接口，隐藏其内部实现的细节及其他内部成员，从而实现更强的封装。', 246, 3),
(1265, 138, 125, 1, '创建模块需要如下几个步骤：', 246, 4),
(1266, 138, 125, 1, '（1）创建一个文件夹，通常是一个包名，例如 edu.guet.module。', 246, 5),
(1267, 138, 125, 1, '（2）在该文件夹（如 edu.guet.module）下创建一个 module-info.java 文件，这个文件被称为模块描述符文件。', 246, 6),
(1268, 138, 125, 1, '（3）在模块描述符文件的同级别创建一个 Java 包。', 246, 7),
(1269, 138, 125, 1, '（4）最后，在创建的包下可以创建多个 Java 类文件。', 246, 8),
(1270, 138, 125, 1, '创建模块需要遵守如下几个规则：', 246, 9),
(1271, 138, 125, 1, '（1）模块名称必须是唯一的。', 246, 10),
(1272, 138, 125, 1, '（2）一个模块必须要有模块描述符文件 module-info.java，且仅有一个。', 246, 11),
(1273, 138, 125, 1, '（3）包名称必须是唯一的。即使在不同的模块中，包名也不能相同。', 246, 12),
(1274, 138, 125, 1, '（4）每个模块将创建一个 jar 文件。', 247, 1),
(1275, 138, 125, 1, '模块描述文件的格式如下：', 247, 2),
(1276, 138, 125, 1, '模块名一般是两个单词以上，并用“.”（点号）隔开，例如，模块名为 edu.guet.java。默认情况下，模块里的所有包都是私有的，即使被外部依赖也无法访问。例如，假设 edu.guet.java 模块下有两个非空包 edu.guet.java.basic、edu.guet.java.second，并且希望向外界公开，那么代码如下：', 247, 3),
(1277, 138, 125, 1, 'exports 语句只能导出非空包，不能导出具体的类。', 247, 4),
(1278, 138, 125, 1, 'exports 还支持定向导出包，即导出的包仅仅向特定模块公开，其语法如下：', 247, 5),
(1279, 138, 125, 1, '假如希望将包 edu.guet.java.basic 仅仅导出给模块 edu.guet.test 及模块 edu.guet.teaching，而 edu.guet.java.second 仅仅导出给 edu.guet.test，那么代码如下：', 247, 6),
(1280, 138, 125, 1, '如果一个模块要访问其他模块导出的包，那么该模块必须使用 requires 关键字导入要访问的包所在的模块。例如，如果模块 edu.guet.compuer 想要访问模块 edu.guet.java 中的两个非空包 edu.guet.java.basic、edu.guet.java.second，那么模块 edu.guet.java 的声明中需使用 requires 语句，如下所示：', 247, 7),
(1281, 138, 125, 1, '通常，新版本的集成开发环境（如 Eclipse、Intellij IDEA 等）在创建一个 Java 项目时，均会自动创建一个模块及其模块描述文件 module-info.java。为了不引入复杂性，本书后续的内容和示例不讨论模块的使用以及模块对访问特性的影响。', 247, 8),
(1282, 138, 125, 1, '可见性修饰符 public（公有的）可以放置在类、方法和数据域前，表示这些类、方法和数据域可以被任何其他的类访问。', 247, 9),
(1283, 138, 125, 1, '可见性修饰符 private（私有的）可以放置在方法、数据域前，表示这些方法、数据域只能被它们所在的类访问，不能被其他的类访问。此外，private 不能用来修饰类。', 247, 10),
(1284, 138, 125, 1, '图 6-16 的例子说明了 private 的访问特性：当 private 修饰类的成员时，这些类的私有成员在该类的外部是不能被访问的。如图 6-16 所示，类 Cls1 的私有成员是整型变量 x 和方法 f1()，它们只能在该类的内部被访问。因此，类 Cls1 的 main 方法创建一个类 Cls1 的对象 c，然后，通过对象 c 访问这些私有成员是允许的。然而，在类 Cls1 的外部（如类 Cls2），类 Cls1 的私有成员在类 Cls1 的外部是不可见的，也是不能被访问的。因此，类 Cls2 的 main 方法创建一个类 Cls1 的对象 c，然后，通过对象 c 访问类 Cls1 的私有成员是不允许的，Java 编译器会报告编译错误。', 247, 11),
(1285, 138, 125, 1, '（图 6-16　private 访问权限：左为类 Cls1，其 main 方法创建对象 c 并访问私有数据域 x 与私有方法 f1()，均为正确；右为类 Cls2，其 main 方法同样创建 Cls1 的对象 c 并访问 c.x 与 c.f1()，两处均标注“错误”）', 248, 1),
(1286, 138, 125, 1, '如果没有使用可见性修饰符放置在类、方法和数据域前，那么这些类、方法、数据域默认具有包私有访问权限，可以被同一个包中的成员访问，但是不能被其他包中的成员访问。', 248, 2),
(1287, 138, 125, 1, '一个类的方法和数据域无论使用哪个可见性修饰符，该类总是可以访问自身所有的数据域和方法。因此，可见性修饰符用于指明一个类的数据域和方法是否能在该类之外被访问。', 248, 3),
(1288, 138, 125, 1, '图 6-17 的例子说明了当可见性修饰符修饰数据域和方法时 3 种访问权限的区别。从图 6-17，可以看出，类 Cls1、Cls2、Cls3 都是公有类，类 Cls1 和类 Cls2 处于同一包 pkg1 中，类 Cls2 处于另一个包 pkg2 中，包 pkg1、pkg2 处于同一模块中（避免模块带来的复杂性）。在同一个包中的类 Cls2 可以访问类 Cls1 的公有数据域和方法，也可以访问类 Cls1 的包私有数据域和方法，但不能访问类 Cls1 的私有数据域和方法。在不同包中的类 Cls3 只能访问类 Cls1 的公有数据域和方法，不能访问私有或包私有的数据域和方法。（图 6-17　可见修饰符修饰类的成员：Cls1 声明 private int x、int y、public int z 以及 private f1()、f2()、public f3()；同包的 Cls2 中不可访问 c1.x、可访问 c1.y 和 c1.z、不能调用 c1.f1()、能调用 c1.f2() 和 c1.f3()；不同包的 Cls3 中不可访问 c1.x 和 c1.y、可访问 c1.z、不能调用 c1.f1() 和 c1.f2()、能调用 c1.f3()）', 248, 4),
(1289, 138, 125, 1, '图 6-18 的例子说明可见性修饰符修饰类时访问权限的区别。关键字 class 前面只能使用 public 修饰或无可见性修饰符修饰，不能使用 private 修饰。在这个例子中，类 Cls1 不是公有类，只能被包 pkg1 的其他类（如类 Cls2）访问，但是不能被其他包的类（如类 Cls3）访问。类 Cls2 是公有类，既能被同一包的其他类（如类 Cls1）访问，也能被不同包的类（如类 Cls3）访问。', 248, 5),
(1290, 138, 125, 1, '（图 6-18　可见修饰符修饰类：pkg1 中的包私有类 Cls1 能访问 Cls2、能访问 Cls3；pkg1 中的公有类 Cls2 能访问 Cls1；pkg2 中的公有类 Cls3 不能访问 Cls1、能访问 Cls2）', 249, 1),
(1291, 139, 126, 1, '在程序清单 6-2 中定义了一个类 Person，其数据域（姓名 name、年龄 age、身高 height、血型、健康否 isHealth 等）都是包私有访问权限。在同一包中的其他类可以直接修改这些数据域。如果数据域是公有访问权限，这些数据域被修改的可能性会扩展到其他任何类。这有可能导致如下两个问题。', 249, 2),
(1292, 139, 126, 1, '一是，非私有的数据域可以被其他类篡改。例如，Person 类的数据域在其他类中直接可以被修改。假设一个类 Test，可以将某个 Person 对象的 age 修改-10，这明显是不合理的。', 249, 3),
(1293, 139, 126, 1, '二是，程序的可维护性变差。由于一个类的非私有数据域可能被其他多个类直接修改，使得对程序的维护变得困难。例如，假如想要限制类 Person 的属性 age 是非负整数，身高 height 也是非负整数，即使类 Person 进行了相关的设置以限制这两个属性是非负数，但是由于这两个属性是非私有的，其他类也可以直接修改这两个属性为负数，从而绕过类 Person 所做的限制。', 249, 4),
(1294, 139, 126, 1, '为了避免外部其他类对一个类的数据域直接进行修改，可以使用 private 修饰符将数据域声明为私有的，这被称为数据域封装。将数据域设置为私有的，可以保护数据不被外部其他类直接修改，使得程序更容易维护。', 249, 5),
(1295, 139, 126, 1, '私有数据域在类的外部不能直接被访问，为了访问私有数据域的值，可以提供公有的访问方法供外部其他类调用。为了获取私有数据域的值，可以提供一个获取方法（getter）返回数据域的值。为了修改私有数据域的值，可以提供一个设置方法(setter)为数据域设置新值。', 249, 6),
(1296, 139, 126, 1, '获取方法的签名一般形式如下：', 249, 7),
(1297, 139, 126, 1, '如果返回值类型是 boolean 类型，一般如下定义获取方法：', 249, 8),
(1298, 139, 126, 1, '设置方法的签名如下：', 249, 9),
(1299, 139, 126, 1, '现在创建一个新的矩形类 Rect_v1，将其数据域：宽和高，设置为私有的，并提供获取方法和设置方法，矩形类的代码如程序清单 6-7 所示。', 249, 10),
(1300, 139, 126, 1, '两个设置方法 setWidth()（第 15~20 行）、setHeight()（第 24~29 行）在代码中对矩形的宽、高的值进行了限定，不允许设置为负值。两个获取方法 getWidth()（第 21~23 行）、getHeight()（第 30~32 行）可以分别返回矩形的宽、高值。于是，私有数据域的设置方法和获取方法是设置和获取私有数据域的唯一途径。如果需要调整对私有数据域的限制，可以修改类 Rect_v1，与其他类无关，这使得程序更容易维护。', 250, 1),
(1301, 139, 126, 1, '注意：除非有特殊要求，在设计一个类时，应该将其所有的数据域设置为私有的，其所有的构造方法和方法应该被声明为公有的。', 250, 2),
(1302, 140, 127, 1, '类的实例变量和静态变量都是类的变量（class variable）。无论类的变量在类的何处声明，其作用域是整个类。类的变量和方法可以在类中以任意顺序出现，如图 6-19(a)所示。然而，当类的一个变量基于类的另一个变量来进行初始化时，则另一个变量必须先声明，如图 6-19(b)所示。', 250, 3),
(1303, 140, 127, 1, '（图 6-19　类变量的作用域：a) 类 Cls1 中方法 add 写在数据域 x、y 之前，数据域 x、y 与方法 add 可以以任意顺序声明；b) 类 Cls2 中 private int y = x * x，因此 x 必须在 y 之前声明）', 251, 1),
(1304, 140, 127, 1, '在方法内定义的变量被称为局部变量。局部变量作用域是从声明的地方开始有效，直到包含它的块结束。如果一个局部变量和类的变量同名，那么局部变量优先，而同名的类的变量将被隐藏(hidden)，这被称为变量隐藏。例如，图 6-20(a)展示了类 Cls1 中实例变量 y 被方法 m1 的局部变量 y 隐藏的情形。图 6-20(b)展示了运行测试的情况。在这个例子中，数据域 y 被方法 m1 的局部变量 y 隐藏。在运行测试时，首先创建了一个对象 c，其数据域 x、y 均为零。然后，执行 c.m1()，输出实例变量 x 的值 0，以及局部变量 y 的值 5。\n（图 6-20　局部变量隐藏类变量：a) 类 Cls1 的方法 m1 中定义局部变量 int y = 5，输出 x 与 y，数据域 x、y 声明在 m1 之后；b) 测试类 Test 的 main 方法创建对象 c 并调用 c.m1()，运行结果为 x=0、y=5，说明实例变量 y 被局部变量 y 隐藏）', 251, 2),
(1305, 141, NULL, 1, '对象是一种引用类型，一个对象既可以作为一个方法的形参，也可以作为一个方法的返回值类型，还可以在方法中创建一个对象作为局部变量。', 251, 3),
(1306, 142, 128, 1, '当对象作为方法的形参时，实参将自己的引用值传递给形参，形参和实参会引用同一片内存区域，因此形参对内存区域的改变也会影响到实参。', 251, 4),
(1307, 142, 128, 1, '在 Java 语言中，参数传递本质上仅有一种方式，即值传递。无论一个方法的形参是基本数据类型或是引用数据类型，实参传递给形参的都是实参的值。', 251, 5),
(1308, 142, 128, 1, '然而，传递基本数据类型与传递引用类型是有区别的。当传递基本数据类型时，形参的改变对实参无任何影响；而当传递引用数据类型时，形参的改变也会影响到实参。', 251, 6),
(1309, 142, 128, 1, '程序清单 6-8 中的程序展示了传递基本数据类型和引用数据类型的区别。该示例使用了类 Rect_v1，类 Rect_v1 的代码如程序清单 6-7 所示。', 252, 1),
(1310, 142, 128, 1, '运行结果：', 252, 2),
(1311, 142, 128, 1, '程序清单 6-8 第 15-22 行定义了一个方法 printRect，它需要两个形参，一个是引用类型 Rect_v1，另一个是基本数据类型 n。第 8 行的代码调用了 printRect 方法。执行第 8 行代码后，运行结果中输出了 5 次矩形对象变化的情况。执行第 10-12 行，运行结果展示方法调用结束后，矩形对象发生了变化，而基本数据类型 count 的值没有改变。为什么同样是值传递，传递基本数据类型时，实参不会变化。而传递引用数据类型时，实参会变化。这也基本数据类型、引用数据类型的内存模型有关。', 252, 3),
(1312, 142, 128, 1, '图 6-21 展示了执行程序中方法 printRect 时的内存模型。在传递基本数据类型时，实参 count 的值 5 传递给形参 n，形参 n 的值也变为 5，形参 n 的任何改变均与实参 count 无关。在传递引用数据类型，实参 r1 的引用值 X 传递形参 r，r 的引用值也是 X。于是，实参 r1 与形参 r 均指向同一个对象。这样，当 printRect 方法执行完之后，其占用的栈空间被系统收回，形参 n、r 会消失。然而，通过形参 r 操作的内存堆中的矩形对象不会消失，形参 r 对内存堆中矩形对象的修改都被保存下来。于是，当传递引用数据类型时，形参可以操作实参引用的内存空间，从而带来改变。（图 6-21　方法 printRect 调用时的内存模型：左侧调用栈自下而上为 main 方法（int count：5、r1：引用值 X）和 printRect 方法（int n：5、r：引用值 X）；右侧内存堆中是一个矩形对象，r1 与 r 的引用值同为 X，都指向该对象）', 253, 1),
(1313, 143, 129, 1, '当一个对象类型作为方法返回值，需要使用类名作为方法的返回值类型。下面通过一个示例进行说明，该示例也使用了类 Rect_v1，首先创建一个矩形对象，然后根据该矩形对象的宽和高，创建一个交换了宽和高的新矩形对象，其代码如程序清单 6-9 所示。', 253, 2),
(1314, 143, 129, 1, '运行结果如下：', 254, 1),
(1315, 143, 129, 1, '程序清单 6-9 第 12 行定义了一个方法 reverseRect，其返回值类型是 Rect_v1，表示该方法返回一个 Rect_v1 类型的对象。', 254, 2),
(1316, 144, 130, 1, '在方法中声明一个对象作为局部变量，有两种方式，例如：', 254, 3),
(1317, 144, 130, 1, 'var 声明方式可以使用关键字 var 替代类名，使得代码更简洁。局部变量的类型通过赋值语句右边的表达式进行推断。该声明方式从 Java 10 开始出现，如果可以从变量的初始值推导出它们的类型，那么可以用 var 关键字声明局部变量，而无需指定其类型。', 254, 4),
(1318, 144, 130, 1, '使用关键字 var 还需注意：关键字 var 只能用于方法中的局部变量定义，不能用于形式参数声明。', 254, 5),
(1319, 144, 130, 1, '在如下情况使用关键 var 会发生编译错误：', 254, 6),
(1320, 144, 130, 1, '（1）多个变量声明在一起。', 254, 7),
(1321, 144, 130, 1, '（2）变量声明时没有进行初始化。', 254, 8),
(1322, 144, 130, 1, '（3）变量声明时，赋值操作符左边存在一个或多个方括号对。', 254, 9),
(1323, 144, 130, 1, '（4）变量初始化是一个数组初始化列表。', 254, 10),
(1324, 144, 130, 1, '（5）变量声明在初始化时包含一个对自身的引用。', 254, 11),
(1325, 144, 130, 1, '下面在 Jshell 中验证一下 var 的使用。', 254, 12),
(1326, 144, 130, 1, '(1)合法声明示例。', 254, 13),
(1327, 144, 130, 1, '(2) 多个变量声明在一起的错误示例。', 254, 14),
(1328, 144, 130, 1, '（3）变量声明没有进行初始化的错误示例。', 254, 15),
(1329, 144, 130, 1, '（4）合法声明数组示例。', 254, 16),
(1330, 144, 130, 1, '（5）变量声明时，赋值操作符左边存在一个或多个方括号对的错误示例。', 254, 17),
(1331, 144, 130, 1, '（6）变量初始化是一个数组初始化列表的错误示例。', 255, 1),
(1332, 144, 130, 1, '（7）变量声明在初始化时包含一个对自身的引用的错误示例。', 255, 2),
(1333, 144, 130, 1, '（8）引用类型赋值为 null，无法确定类型，也会产生错误，示例如下。', 255, 3),
(1334, 145, 131, 1, '当数组元素是某种类型的对象时，这样的数组可被称为对象数组。例如，下面的语句声明并创建具有 5 个矩形对象的数组：', 255, 4),
(1335, 145, 131, 1, '该语句创建了一个一维对象数组 rects，其数组元素是一个矩形对象。数组 rects 包含 5 个矩形对象，每个矩形对象的默认值是 null。为了给每个数组元素赋初值，可以使用如下的 for 循环语句：', 255, 5),
(1336, 145, 131, 1, '在初始化之后，对象数组 rects 的内存模型示意图如图 6-22 所示。（图 6-22　对象数组 rects 的内存模型：rects 引用一个含 5 个元素的一维数组，元素 rects[0]～rects[4] 依次存放引用值，分别指向内存中的 Rect_v1 对象 1 至 Rect_v1 对象 5）', 255, 6),
(1337, 145, 131, 1, '访问对象数组的数组元素时，系统会执行两个层次的引用。例如，当访问数组元素 rects[0]事，系统会进行两个层次的引用。第一个层次的引用是对数组的引用，通过 rects 引用整个数组，找到下标为 0 的对象 rects[0]。第二个层次的引用是对具体对象的引用，通过 rects[0]引用 Rect_v1 对象 1。', 255, 7),
(1338, 145, 131, 1, '程序清单 6-10 展示了一个使用对象数组的例子，对象数组既可以作为方法参数，也可以作为返回值。', 256, 1),
(1339, 145, 131, 1, '运行结果如下：', 257, 1),
(1340, 145, 131, 1, '程序清单 6-10 第 3 行调用方法 createRects()，创建了一个由 5 个矩形对象构成的对象数组。方法 createRects()的定义在第 7 行~13 行，其返回值类型是矩形对象数组 Rect_v1[]。第 8 行创建了一个对象数组 rects，第 10 行调用 Math.random()方法随机生成矩形对象的宽、高值。主方法第 4 行以 rects 对象数组作为实参调用方法 printRects()，打印出 rects 数组所有数组元素（矩形对象）的信息，并打印出这些矩形对象的面积和。方法 printRects()的定义在第 22 行-29 行，形参是矩形对象数组 Rect_v1[]。第 28 行以对象数组 rects 作为实参调用了方法 sumArea()，计算了对象数组 rects 所有数组元素的面积和。方法 sumArea()的形参是矩形对象数组（第 15 行~20 行），返回值是所有数组元素的面积之和（double 类型）。', 257, 2),
(1341, 146, 132, 1, '对象数组是长度固定的，如果用于存储个数不定的对象，就会出现问题：要么由于对象数组长度不够而不能存储所有对象，要么由于对象数组长度太大而浪费存储空间。为了避免上述问题，Java 语言提供了一个数组列表类 ArrayList（位于 java.util 包中），用来存储不限定个数的某类对象。', 257, 3),
(1342, 146, 132, 1, 'ArrayList 是一种泛型类，具有一个泛型类型 E，泛型类的详细讲解见 9.1 节。在创建一个 ArrayList 对象时，可以用一个具体的引用类型来替代 E。例如，下面的语句创建了一个 ArrayList 对象 nameOfUniversities，可用于存储数量不定的大学名称：', 257, 4),
(1343, 146, 132, 1, '从 Java SE 7 开始，ArrayList 构造方法中不再要求给出具体引用类型的名称，具体地，语句如下：', 257, 5),
(1344, 146, 132, 1, '可以简化为：', 257, 6),
(1345, 146, 132, 1, '因此，对于上面 nameOfUniversities 对象的创建，还可以进一步简化为：', 257, 7),
(1346, 146, 132, 1, '数组列表类 ArrayList 有三个构造方法：', 257, 8),
(1347, 146, 132, 1, '(1)无参构造方法：ArrayList()，创建一个初始容量为 10 的数组列表对象。例如，数组列表对象 nameOfUniversities 的初始容量为 10，能容纳 10 个字符串对象。', 257, 9),
(1348, 146, 132, 1, '(2)指定初始容量的构造方法：ArrayList(int initialCapacity)，创建一个指定初始容量的数组列表对象。', 257, 10),
(1349, 146, 132, 1, '(3)从其他集合对象创建的构造方法：ArrayList(Collection<? Extends E> c)，创建一个数组列表对象容纳指定集（Collection）对象 c，这种构造方法的形参，可在学习完 9.1 再回顾。', 257, 11),
(1350, 146, 132, 1, '数组列表类 ArrayList 对象在创建时具备初始容量，一个 ArrayList 对象实际上就是一个能够容纳多个同类对象的列表。当一个列表中存储的对象数量快要超过其初始容量时，列表会自动扩充容量。', 257, 12),
(1351, 146, 132, 1, '数组列表类 ArrayList 的一些常用方法如表 6-1 所示。', 257, 13),
(1352, 146, 132, 1, '表 6-1　ArrayList 常用方法\n| 常用方法 | 描述 |\n| --- | --- |\n| public boolean add(E e); | 将指定的元素 e 追加到当前列表的末尾。 |\n| public void add(int index, E element) | 在当前列表中的指定位置 index 插入指定的元素。将当前位于该位置的元素（如果有）和任何后续元素向右移动（在其索引中添加一个）。 |\n| public E set(int index, E element) | 用指定的元素 element 替换当前列表中指定位置 index 的元素。 |\n| public int size() | 获取当前列表中的元素个数。 |\n| public E get(int index); | 返回当前列表中指定位置 index 的元素。 |\n| public boolean contains(Object o) | 如果当前列表包含指定的元素 o，那么返回 true。否则，返回 false。 |\n| public int indexOf(Object o) | 返回当前列表中指定元素 o 第一次出现的索引值，如果当前列表不包含该元素 o，则返回-1。 |\n| public int lastIndexOf(Object o) | 返回当前列表中指定元素 o 最后一次出现的索引值，如果当前列表不包含该元素 o，则返回-1。 |\n| public E remove(int index) | 删除当前列表中指定位置 index 的元素。将任何后续元素向左移动（从其索引中减去 1）。 |\n| public boolean remove(Object o) | 从当前列表中删除指定元素 o 的第一个出现（如果存在）。如果列表中不包含该元素，则该列表将保持不变。如果列表包含指定元素，返回 true，否则返回 false。 |\n| public void clear() | 删除当前列表的所有元素。 |\n| public boolean isEmpty() | 如果当前列表没有元素，返回 true，否则返回 false。 |', 258, 1),
(1353, 146, 132, 1, '程序清单 6-11 给出了一个示例，演示了 ArrayList 各种常用方法的使用。', 258, 2),
(1354, 146, 132, 1, '运行结果如下：', 259, 1),
(1355, 146, 132, 1, '程序清单 6-11 第 1 行导入 ArrayList，第 6 行创建了一个列表 names 存储表示历史人物姓名的字符串对象，第 6 行-11 行连续在列表末尾追加字符串对象，第 13 行打印列表 names 的内容。第 14 行-19 行测试了 ArrayList 的几个常用方法。第 23 行测试 remove 方法，第 25 行测试了另一种形式的 add 方法，第 27 行测试了另一种形式 remove 方法。第 29 行-30 行通过 for 循环输入 ArrayList 的内容。第 34 行、第 37 行测试了 set 方法，第 39 行-40 行通过 foreach 循环输出列表的值。第 43 行-49 行，演示了用自定义类来替代泛型类型 E，并进行了相关操作。', 260, 1),
(1356, 146, 132, 1, '另外，有时候需要从一个对象数组创建一个列表，或者相反。虽然可以通过循环实现，但是代码不够简洁，可以使用 Java 语言提供的 API 更加容易地实现。', 260, 2),
(1357, 146, 132, 1, '首先，使用方法 Arrays.asList()可以实现从一个对象数组创建一个数组列表对象，例如：', 260, 3),
(1358, 146, 132, 1, '其次，使用 ArrayList 的实例方法 toArray()可以实现从一个数组列表对象创建一个对象数组，例如：', 260, 4),
(1359, 147, NULL, 1, '关键字 this 用于一个对象引用自身。通过关键字 this，可以引用对象的实例成员。通常，关键字 this 是被隐式使用的。例如，图 6-23 所示的例子，子图(a)的代码与子图(b)的代码是等价的。在子图(b)中，关键字 this 显式引用了对象的实例成员 width、height。程序员编码时，为了简洁通常是按子图(a)的形式编码。基于子图(a)的代码，Java 编译器会生成子图(b)所示的具有关键字 this 的代码。（图 6-23　this 引用隐式使用：a) 类 Rect 中 getArea 方法写为 return width * height；b) 与之等价的代码为 return this.width * this.height，显式使用关键字 this 引用实例成员）', 260, 5),
(1360, 147, NULL, 1, '然而，this 引用在两种情况下是必须显式使用的：（1）需要引用被方法或构造方法的参数所隐藏的数据域时；（2）需要调用一个重载的构造方法时。', 260, 6),
(1361, 148, 133, 1, '通常，使用数据域作为构造方法或设置方法的参数是一个好方法，这可以使得代码易于阅读，并且避免创建不必要的名字。然而，由于参数与数据域同名，在构造方法或设置方法中，需要显式使用关键字 this 来引用被隐藏的数据域名称。图 6-24 展示了显式使用 this 引用数据域的情况，在构造方法 Rect 中，两个形参与数据域中实例变量 width、height 同名。为了区分形参与数据域中的实例变量，必须显式使用关键字 this。同样地，在设置方法 setWidth 中，形参 width 与数据域中的实例变量 width 同名，这种情况也必须使用 this 关键字。（图 6-24　关键字 this 显式使用：图中为类 Rect 的代码，数据域声明为 double width, height；构造方法 Rect(double width, double height) 的方法体用 this.width = width、this.height = height 给数据域赋值；设置方法 setWidth(double width) 的方法体用 this.width = width 赋值，其余部分以省略号表示）', 261, 1),
(1362, 148, 133, 1, '被隐藏的实例变量，可以通过 this 引用来访问。被隐藏的静态变量，可以通过类名来访问。其访问形式为：类名.静态变量。例如，图 6-25 展示了隐藏实例变量、静态变量示例，关键字 this 引用被隐藏的实例变量 i，类名引用被隐藏的静态变量 j。（图 6-25　隐藏实例变量、静态变量示例：图中左侧是类 Cls 的代码——私有实例变量 private int i = 1、私有静态变量 private static int j = 0、设置方法 setI(int i) 中执行 this.i = i、设置方法 setJ(int j) 中执行 Cls.j = j；右侧说明——假定 c1、c2 是类 Cls 的两个对象；调用 c1.setI(15)时，执行 this.i = 15，this 指向 c1，修改 c1 的数据域 i 的值为 15；调用 c1.setI(25)时，执行 this.i = 25，this 指向 c2，修改 c2 的数据域 i 的值为 25；对于静态方法 setJ()，调用 Cls.setJ(30)时，执行 Cls.j = 30，修改静态数据域 j 的值为 30，j 是被类 Cls 的所有对象所共享的）', 261, 2),
(1363, 149, 134, 1, '关键字 this 可以在一个类的构造方法中使用，用于调用该类的另一个构造方法。例如，如图 6-26 所示，类 Rect 有两个构造方法，第二个无参构造方法通过关键字 this 调用了第一个构造方法。需要注意的是，在一个构造方法使用 this 调用其他构造方法时，this 调用其他构造方法的语句应该是该构造方法的第一条语句。', 261, 3),
(1364, 149, 134, 1, '建议：当一个类有多个构造方法时，尽可能使用 this(参数列表)的方式实现它们，这样做常常可以简化代码。\n（图 6-26　关键字 this 调用构造方法：图中为类 Rect 的代码，含数据域 double width, height，带两个参数的构造方法 Rect(double width, double height) 用 this 给数据域赋值，无参构造方法 Rect( ) 的方法体为 this(1.0, 1.0 )，并以“//关键字 this 调用构造方法”注释说明）', 262, 1),
(1365, 151, 135, 1, 'Java 语言的所有基本类型都有其对应包装类。即，针对八个基本数据类型(byte、short、int、long、float、double、char、boolean)，Java 提供了对应八个包装类（Byte、Short、Integer、Long、Float、Double、Character、Boolean）。在 Java 语言中，为什么既提供基本数据类型，又提供对应的包装类呢？一方面，Java 语言提供基本数据类型是为了性能，如果把基本数据类型作为对象使用的，那么处理对象时，Java 语言是需要额外的系统开销的。另一方面，Java 语言提供的一些数据结构和方法需要将引用类型作为参数，于是，为了让这些数据结构和方法对基本数据类型的值进行处理，Java 语言提供了基本类型对应的包装类。例如，ArrayList<E>是一个动态的对象数组，如果要让该数据结构存储整数，那么必须将整数转化成对应的整数类类型。', 262, 2),
(1366, 151, 135, 1, '数值包装类（Byte、Short、Integer、Long、Float、Double）的使用非常相似，都具有方法：byteValue( )、shortValue( )、intValue( )、longValue( )、floatValue( )、doubleValue( )。这些方法可将对象转化为基本数据类型值。', 262, 3),
(1367, 151, 135, 1, '下面通过 Integer 类、Double 类介绍基本数据类型包装类。Integer 类和 Double 类的数据域、构造方法、常用方法分别如表 6-2、表 6-3 所示。', 262, 4),
(1368, 151, 135, 1, '表 6-2　Integer 类说明\n| 数据域 | 说明 |\n| --- | --- |\n| private int value | 当前 Integer 对象对应的 int 值 |\n| public static final double MAX_VALUE | 正的最大 double 值，(2 − 2⁻⁵²)·2¹⁰²³ |\n| public static final double MIN_VALUE | 正的最小 double 值，2⁻¹⁰⁷⁴ |\n| 构造方法 | 说明 |\n| public Integer(int value) | 以指定值 value 构建一个 Integer 对象。从 Java 9 开始，这个构造方法将成为过时的方法。静态方法 valueOf(int)是一个更好的选择，具有更好地空间和时间性能。 |\n| public Integer(String s) | 以字符串表示的浮点值构建一个 Integer 对象。从 Java 9 开始，这个构造方法将成为过时的方法。使用静态方法 parseInteger(String)将 String 转换为 int 值，或使用静态方法 valueOf(String)将一个 String 对象转换成一个 Integer 对象 |\n| 常用方法 | 说明 |\n| public byte byteValue() | 返回当前 Integer 对象的 byte 值 |\n| public short shortValue() | 返回当前 Integer 对象的 short 值 |\n| public int intValue() | 返回当前 Integer 对象的 int 值 |\n| public long longValue() | 返回当前 Integer 对象的 long 值 |\n| public float floatValue() | 返回当前 Integer 对象的 float 值 |\n| public double doubleValue() | 返回当前 Integer 对象的 double 值 |\n| public static Integer valueOf(int i) | 基于给定的 int 值返回一个 Integer 对象 |\n| public static Integer valueOf(String s) | 返回一个 Integer 对象，参数 s 是该对象拥有的 int 值的字符串表示 |\n| public static Integer valueOf(String s, int radix) | 返回一个 Integer 对象，该对象保存从指定字符串中提取的值，解析指定字符串 s 时，使用第二个参数给定的基数。 |\n| public static int parseInt(String s) | 返回一个新的有符号十进制 int 值，该值通过解析指定字符串 s 获得 |\n| public static int parseInt(String s, int radix) | 返回一个新的有符号 int 值，该值通过解析指定字符串 s 获得，解析字符串 s 时，使用第二个参数给定的基数 |\n| public static int parseUnsignedInt(String s) | 自 Java 8 开始提供该方法，把字符串 s 解析为无符号十进制整数，并返回该整数值 |\n| public static int parseUnsignedInt(String s, int radix) | 自 Java 8 开始提供该方法，把字符串 s 解析为以第二个参数为基数无符号整数，并返回该整数值 |\n| public static Integer valueOf(String s, int radix) | 基于第二个参数给定的基数，把字符串 s 解析为无符号整数，并返回该整数值 |\n| public static String toString(int i) | 基于十进制，返回一个 int 值 i 的字符串表示 |\n| public static String toBinaryString(int i) | 返回整数参数 i 的字符串表示，这个字符串表示是参数 i 对应的以 2 为基数的无符号整数 |\n| public static String toOctalString(int i) | 返回整数参数 i 的字符串表示，这个字符串表示是参数 i 对应的以 8 为基数的无符号整数 |\n| public static String toHexString(int i) | 返回整数参数 i 的字符串表示，这个字符串表示是参数 i 对应的以 16 为基数的无符号整数 |\n| public static String toUnsignedString(int i) | 自 Java 8 开始提供该方法，返回参数 i 的字符串表示，这个字符串表示是参数 i 对应的十进制无符号数。 |\n| public static long toUnsignedLong(int x) | 将参数 i 转换为无符号的 long 类型值 |\n| public String toString() | 返回当前 Integer 对象的字符串表示 |\n| public int compareTo(Integer anotherInteger) | 当前 Integer 对象与给定的 Integer 对象 anotherInteger 进行比较，比较两个对象包含的数值，当前者大于、等于、小于后者时，分别返回 1、0、-1 |', 262, 5),
(1369, 151, 135, 1, '表 6-3　Double 类说明\n| 数据域 | 说明 |\n| --- | --- |\n| private double value | Double 对象对应的 double 值 |\n| public static final double MAX_VALUE | 正的最大 double 值，(2 − 2⁻⁵²)·2¹⁰²³ |\n| public static final double MIN_VALUE | 正的最小 double 值，2⁻¹⁰⁷⁴ |\n| 构造方法 | 说明 |\n| public Double(double value) | 以指定值 value 构建一个 Double 对象。从 Java 9 开始，这个构造方法将成为过时的方法。静态方法 valueOf(double)是一个更好的选择，具有更好地空间和时间性能。 |\n| public Double(String s) | 以字符串表示的浮点值构建一个 Double 对象。从 Java 9 开始，这个构造方法将成为过时的方法。使用静态方法 parseDouble(String)将一个 String 转化为一个 double 值，或使用静态方法 valueOf(String)将一个 String 对象转换成一个 Double 对象 |\n| 常用方法 | 说明 |\n| public byte byteValue() | 返回当前 Double 对象的 byte 值 |\n| public short shortValue() | 返回当前 Double 对象的 short 值 |\n| public int intValue() | 返回当前 Double 对象的 int 值 |\n| public long longValue() | 返回当前 Double 对象的 long 值 |\n| public float floatValue() | 返回当前 Double 对象的 float 值 |\n| public double doubleValue() | 返回当前 Double 对象的 double 值 |\n| public static Double valueOf(double d) | 基于给定的 double 值返回一个 Double 对象 |\n| public static Double valueOf(String s) | 返回一个 Double 对象，参数 s 是该对象拥有的 double 值的字符串表示 |\n| public static double parseDouble(String s) | 返回一个新的 double 值，该值由指定字符串 s 表示 |\n| public static String toString(double d) | 返回一个 double 值 d 的字符串表示 |\n| public static String toHexString(double d) | 返回一个 double 值 d 的十六进制字符串表示 |\n| public String toString() | 返回当前 Double 对象字符串表示 |\n| public int compareTo(Double anotherDouble) | 当前 Double 对象与给定的 Double 对象 anotherDouble 进行比较，比较两个对象包含的数值，当前者大于、等于、小于后者时，分别返回 1、0、-1 |', 264, 1),
(1370, 151, 135, 1, '基本数据类型包装类都是最终类（7.4 节介绍），意味着所有包装类的实例一旦创建，就都是不可变的，即包装类实例包含的值就不能再改变了。', 264, 2),
(1371, 151, 135, 1, '所有基本数据类型包装类的构造方法从 Java 9 开始成为过时方法，在未来的版本中会被移除。为了提升性能，构建基本数据类型包装类对象，建议采用静态的工厂方法 valueOf（工厂模式是一种设计模式，这里不展开介绍）进行创建。这种创建方式具有更好的空间和时间性能。例如，图 6-27 展示了一个例子：在 Jshell 中通过数值创建 Integer 对象和 Double 对象。图 6-28 展示了一个例子：在 Jshell 中通过字符串创建 Integer 对象和 Double 对象。这两个例子验证过时的构造方法以及创建对象的推荐方式。（图 6-27　通过数值创建 Integer、Double 对象示例：图中是在 Jshell 中先后用数值调用 Integer 与 Double 的过时构造方法和静态工厂方法 valueOf 创建 Integer 对象、Double 对象的交互过程及回显结果）（图 6-28　通过字符串创建 Integer、Double 对象示例：图中是在 Jshell 中用数值字符串调用 Integer 与 Double 的过时构造方法和静态工厂方法 valueOf 创建 Integer 对象、Double 对象的交互过程及回显结果）', 264, 3),
(1372, 151, 135, 1, '每一个数值包装类都有常量 MAX_VALUE 和 MIN_VALUE。常量 MAX_VALUE 表示对应的基本数据类型的最大值。对于 Byte、Short、Integer 和 Long 而言，常量 MIN_VALUE 表示对应的基本数据类型的最小值。然而，对于 Float、Double 而言，常量 MIN_VALUE 表示 float 类型和 double 类型的最小正值。在 Jshell 中，对各数据类型的最大值和最小值进行验证，结果如图 6-29 所示。（图 6-29　基本数据类型最大值、最小值：图中是在 Jshell 中逐一输出各数值包装类的 MAX_VALUE 与 MIN_VALUE 常量值的交互结果，其中 Byte、Short、Integer、Long 显示的是最小值，Float、Double 显示的是最小正值）', 265, 1),
(1373, 151, 135, 1, '每个数值包装类包含一些共有方法：doubleValue( )、floatValue( )、longValue( )、intValue( )、shortValue( )、byteValue( )。这些方法返回包装类对象对应的 double、float、long、int、short、byte 值。例如，Double.valueOf(24.4)创建了一个 Double 对象，然后调用各方法，其结果如图 6-30 所示。（图 6-30　数值包装类共有方法调用：图中是在 Jshell 中创建 Double.valueOf(24.4) 对象后，依次调用 byteValue( )、shortValue( )、intValue( )、longValue( )、floatValue( )、doubleValue( ) 各方法及其返回值的交互结果）', 266, 1),
(1374, 151, 135, 1, '数值包装类都有一个 compareTo 方法，用于比较两个数值，如果当前对象包含的数值大于、等于、小于另一个对象包含的数值时，分别返回 1、0、-1。例如，图 6-31 展示了两个 Integer 对象比较的例子。（图 6-31　Integer 类 compareTo 方法调用：图中是在 Jshell 中创建两个 Integer 对象后调用 compareTo 方法进行比较，输出 1、0、-1 三种比较结果的交互过程）', 266, 2),
(1375, 151, 135, 1, '每个数值包装类都提供了相应的静态解析方法 parseXXX(String s)（XXX 代表 Byte、Short、Int、Long、Float、Double 中的任意一个），将字符串转换成相应的基本数据类型。例如，Integer 类的 parseInt 方法将一个数值字符串解析成一个 int 值，Double 类的 parseDouble 可以一个数值字符串解析成一个 double 值。', 266, 3),
(1376, 151, 135, 1, '对于整数包装类，Java 还提供了一个重载的解析方法 parseXXX(String s, int radix)，提供第 2 个参数(radix)指定基数为 2、8、16，可将数值字符串解析为以指定值为基数的数值。图 6-32 展示了方法 parseInt(String s, int radix)的调用示例。方法 parseInt(String s, int radix)的第一个参数的字符串必须是合法的相应进制数的字符串，否则，会产生运行时错误。例如，示例中 Integer.parInt("12", 2)就产生了运行时错误，因为二进制数的合法字符只能是‘0’和‘1’，而这里使用了字符‘2’。方法 parseInt(String s, int radix)的第 2 个参数可用于指定二进制、八进制、十进制、十六进制等，当然也可以指定其他基数。图 6-32 示例展示了把第一个参数指定的数值字符串按第二个参数指定的基数进行转换，得到一个十进制的整数值。（图 6-32　Integer.parseIn 方法调用示例：图中是在 Jshell 中以不同基数（2、8、10、16 等）调用 Integer.parseInt(String s, int radix) 转换数值字符串的输出结果，其中对二进制基数转换 "12" 时给出运行时错误信息）', 267, 1),
(1377, 151, 135, 1, '图 6-33 展示了 Double、Float 的解析方法 parseXXX 的使用。对于浮点类型，合法的字符串，既可以是一个整数数值字符串表示，如“12”，也可以是浮点数值数字符串表示，如 “12.5”。（图 6-33　Double、Float 的解析方法调用示例：图中是在 Jshell 中调用 Double.parseDouble 与 Float.parseFloat 解析整数数值字符串和浮点数值字符串的输出结果）', 267, 2),
(1378, 151, 135, 1, '数值包装类还有静态方法 toString 和实例方法 toString，用于将相应的数据类型值转换成字符串表示。图 6-34 展示了 Integer、Double 类 toString 系列方法的使用示例。Integer 类的 toString 系列方法可以得到十进制整数值的二进制、八进制、十进制、十六进制的字符串表示，Double 类的 toString 系列方法可以得到十进制浮点类型值的十进制、十六进制的字符串表示。double 类型值的十六进制表示不再展开叙述。（图 6-34　Integer、Double 的 toString 系列方法示例：图中是在 Jshell 中调用 Integer 类的 toString、toBinaryString、toOctalString、toHexString 等方法以及 Double 类的 toString、toHexString 等方法得到的字符串表示结果）', 267, 3),
(1379, 151, 135, 1, '基本数据类型和其包装类类型之间可以自动转换。基本数据类型值被转换为包装类对象的过程被称为装箱（boxing），与之相反的过程被称为拆箱（unboxing）。如果一个基本数据类型值出现在需要使用对象的上下文环境中，Java 编译器会对基本数据类型值进行自动装箱。如果一个包装类对象出现在需要使用基本数据类型值的上下文环境中，Java 编译器会对包装类对象进行自动拆箱。这就是基本数据类型和其包装类之间的自动装箱和自动拆箱。', 268, 1),
(1380, 151, 135, 1, '例如，语句：Integer i1 = Integer.valueOf(3);', 268, 2),
(1381, 151, 135, 1, '可以简化为：Integer i1 = 3; //Java 编译器会对赋值语句右边的数值 3 进行自动装箱。', 268, 3),
(1382, 151, 135, 1, '又如，int i2 = i1 + 1; //在这个上下文中，Integer 对象 i1 被自动拆箱成 int 值参与运算。', 268, 4),
(1383, 151, 135, 1, 'Jshell 对上述语句进行验证，如下所示。', 268, 5),
(1384, 151, 135, 1, '由于基本数据类型和其包装类类型之间可以自动进行转换，所以使用 ArrayList 类可以创建存储不定个数的数值（整数或浮点数等）的列表。例如，下面创建一个存储整数的列表，并对列表进行操作，代码如下：', 268, 6),
(1385, 151, 135, 1, '虽然基本数据类型和其包装类类型之间可以自动转换，但是这并不表示在创建 ArrayList 对象时能用基本类型代替包装类。例如，下面的语句是错误的：', 268, 7),
(1386, 151, 135, 1, '这是因为泛型类型 E 必须是引用类型，int 是基本数据类型。', 269, 1),
(1387, 151, 135, 1, '程序清单 6-12 的实力展示了 ArrayList 存储不定个数浮点数的情况，模拟了一个购物结算场景。', 269, 2),
(1388, 151, 135, 1, '假定用户购买了三件商品，价格分别是：5.5， 9.2， 14.8，其运行结果如下所示：', 269, 3),
(1389, 151, 135, 1, '假定用户购买了五件商品，价格分别是：3，4，12.5， 23.1， 18.5，其运行结果如下所示：', 269, 4),
(1390, 151, 135, 1, '程序清单 6-12 第 4 行使用 ArrayList 创建了一个价格列表，这里必须使用包装类 Double，不能使用基本类型 double。第 8 行-12 行通过一个循环输入浮点类型的价格值，第 11 行将输入的基本类型 double 值自动装箱成 Double 对象。第 15 行-16 行是一个循环计算所有商品价格之和，第 16 行将 Double 对象 d 自动拆箱成基本类型 double 值进行加法运算。第 19 行-20 行输出个商品价格，第 19 行将 Double 对象拆箱成基本类型值 d，然后在第 20 行，输出 d 值。', 269, 5),
(1391, 151, 135, 1, '假如在程序清单 6-12 第 13 行空行加一条语句是否正确，语句如下：', 269, 6),
(1392, 151, 135, 1, '这时 Java 编译器会报错。其原因在于 100 是 int 型值不能自动装箱为 Double 对象。', 270, 1),
(1393, 151, 135, 1, '此时，也会有人提出一个疑问，程序清单 6-12 所示程序在执行时，用户输入数据也输入了整数 3、4，为什么程序没有报错呢？这是因为 int 型值可以自动转换为 double 型值，第 9 行的代码会把 int 型值自动转换 double 型值，然后 double 型值会自动装箱成 Double 对象。', 270, 2),
(1394, 152, 136, 1, 'java.math 包中提供了 BigInteger 类和 BigDecimal 类。它们都是最终类，可以分别用于表示任意大小和精度的整数和十进制数，支持非常大的数的计算或者高精度浮点值的计算。', 270, 3),
(1395, 152, 136, 1, 'BigInteger 类具有如下一些常量，如表 6-4 所示。', 270, 4),
(1396, 152, 136, 1, '表 6-4　BigInteger 类的 public static final BigInteger 数据域\n| 数据域 | 说明 |\n| --- | --- |\n| ZERO | BigInteger 常量 0 |\n| ONE | BigInteger 常量 1 |\n| TWO | BigInteger 常量 2 |\n| TEN | BigInteger 常量 10 |', 270, 5),
(1397, 152, 136, 1, 'BigInteger 类的部分构造方法与常用方法如表 6-5 所示。', 270, 6),
(1398, 152, 136, 1, '表 6-5　BigInteger 类的部分构造方法和常用方法\n| 方法头 | 说明 |\n| --- | --- |\n| public BigInteger(String val) | 将一个 BigInteger 的十进制字符串表示翻译成一个 BigInteger 对象 |\n| public BigInteger(String val, int radix) | 将一个 BigInteger、以指定基数 radix 的字符串表示翻译成一个 BigInteger 对象 |\n| public BigInteger add(BigInteger val) | 返回当前对象与给定对象 val 的和 |\n| public BigInteger subtract(BigInteger val) | 返回当前对象减去给定对象 val 的差 |\n| public BigInteger multiply(BigInteger val) | 返回当前对象与给定对象 val 的乘积 |\n| public BigInteger divide(BigInteger val) | 返回当前对象除以给定对象 val 的商 |\n| public BigInteger remainder(BigInteger val) | 返回当前对象除以给定对象 val 的余数 |\n| public BigInteger pow(int exponent) | 返回当前对象的 exponent 次幂 |\n| public BigInteger sqrt() | 返回当前对象的平方根 |\n| public BigInteger gcd(BigInteger val) | 返回当前对象与给定对象 val 的最大公约数 |\n| public BigInteger abs() | 返回一个 BigInteger 对象，其值是当前 BigInteger 对象的绝对值 |\n| public BigInteger negate() | 返回一个 BigInteger 对象，其值是对当前 BigInteger 对象取反（-this） |', 270, 7),
(1399, 152, 136, 1, '图 6-35 的示例展示了 BigInteger 类对象的创建与使用。（图 6-35　BigInteger 使用示例：图中是在 Jshell 中创建 BigInteger 对象，并调用 add、subtract、multiply、divide、remainder、pow 等方法进行大整数运算的交互结果）', 270, 8),
(1400, 152, 136, 1, 'BigDecimal 类的 public static final BigInteger 数据域如表 6-6 所示。', 271, 1),
(1401, 152, 136, 1, '表 6-6　BigDecimal 类的 public static final BigInteger 数据域\n| 数据域 | 说明 |\n| --- | --- |\n| ZERO | BigDecimal 常量 0，scale 为 0 |\n| ONE | BigDecimal 常量 1，scale 为 0 |\n| TEN | BigDecimal 常量 10，scale 为 0 |', 271, 2),
(1402, 152, 136, 1, 'BigDecimal 类的部分构造方法和常用方法如表 6-7 所示。', 271, 3),
(1403, 152, 136, 1, '表 6-7　BigDecimal 类的部分构造方法和常用方法\n| 方法头 | 说明 |\n| --- | --- |\n| public BigDecimal(String val) | 将一个 BigDecimal 的字符串表示翻译成一个 BigDecimal 对象 |\n| public BigDecimal(BigInteger val) | 将一个 BigInteger 翻译成一个 BigDecimal 对象，其 scale 为 0。 |\n| public BigDecimal(double val) | 将双精度值 val 转换为一个 BigDecimal 对象，该对象是双精度二进制浮点值的精确十进制表示。 |\n| public BigDecimal(long val) | 将一个 long 类型值 val 翻译成一个 BigDecimal 对象，其 scale 为 0。 |\n| public BigDecimal(int val) | 将一个 int 类型值 val 翻译成一个 BigDecimal 对象，其 scale 为 0。 |\n| public BigDecimal add(BigDecimal val) | 返回当前对象与给定对象 val 的和 |\n| public BigDecimal subtract(BigDecimal val) | 返回当前对象减去给定对象 val 的差 |\n| public BigDecimal multiply(BigDecimal val) | 返回当前对象与给定对象 val 的乘积 |\n| public BigDecimal divide(BigDecimal val) | 返回当前对象除以给定对象 val 的商 |\n| public BigDecimal remainder(BigDecimal val) | 返回当前对象除以给定对象 val 的余数 |\n| public BigDecimal pow(int n) | 返回当前对象的 n 次幂 |\n| public BigDecimal sqrt() | 返回当前对象的平方根 |\n| public BigDecimal abs() | 返回一个 BigDecimal 对象，其值是当前 BigDecimal 对象的绝对值 |', 271, 4),
(1404, 152, 136, 1, '构造方法 public BigDecimal(String val)的字符串形式可以有多种形式，下面是一些示例（对于左侧的每个字符串，结果表示[BigInteger，scale]显示在右侧）：', 272, 1),
(1405, 152, 136, 1, '这里的 scale 是指浮点数指数部分值取反，例如，"12.3E+7"，取出整数部分为 123，指数部分是 10 的 6 次幂，scale 的值是-6。', 272, 2),
(1406, 152, 136, 1, '图 6-36 的示例展示了 BigDecimal 类对象的创建和使用。其中，方法 divide 被调用时，如果不能终止运行，就会抛出 ArithmeticException 异常。（图 6-36　BigDecimal 使用示例：图中是在 Jshell 中创建 BigDecimal 对象，并调用 add、subtract、multiply、divide 等方法进行高精度十进制数运算的交互结果，其中不能终止运行的除法调用显示出 ArithmeticException 异常信息）', 272, 3),
(1407, 153, 137, 1, 'Java 语言提供了几种产生随机数的方法。2.7.3 节介绍了 Math.random( )，它可以产生一个 0.0 到 1.0（不包括 1.0）之间的随机 double 类型值。另一种产生随机数的方法就是使用 java.util.Random 类，Random 类不仅可以产生随机 double 类型值，还可以产生 int、long、float、boolean 类型的随机值。表 6-8 展示了 Random 类的构造方法与常用方法。', 272, 4),
(1408, 153, 137, 1, '表 6-8　Random 类构造方法与常用方法\n| 方法头 | 说明 |\n| --- | --- |\n| public Random() | 基于 System.nanoTime()返回的纳秒时间值构建的种子创建一个 Random 对象 |\n| public Random(long seed) | 以一个 long 型值 seed 作为种子创建一个 Random 对象 |\n| public int nextInt() | 返回一个随机的 int 值 |\n| public int nextInt(int m) | 返回一个 0 到 m（不包括 m）之间的随机 int 值 |\n| public long nextLong() | 返回一个随机的 long 值 |\n| public double nextDouble() | 返回一个 0.0 到 1.0（不包括 1.0）之间的随机 double 值 |\n| public float nextFloat() | 返回一个 0.0f 到 1.0f(不包括 1.0f)之间的随机 float 值 |\n| public boolean nextBoolean() | 返回一个随机的 boolean 值 |\n| public void setSeed(long seed) | 以指定 seed 值设置随机数生成器的种子 |', 272, 5),
(1409, 153, 137, 1, '当创建一个 Random 对象时，必须设置种子或者使用默认的种子。种子是一个用于初始化随机数生成器的数字。如果 Random 的两个实例是采用相同的种子创建的，那么这两个实例会产生相同的随机数列。程序清单 6-13 展示的代码用相同的种子 5 产生了两个 Random 对象，这两个 Random 对象生成了相同的随机数列。', 273, 1),
(1410, 153, 137, 1, '运行结果如下：', 273, 2),
(1411, 153, 137, 1, '从运行结果可以看出，两个随机对象产生 0 到 100（不包括 100）之间的随机整数，通过循环产生的两个随机数序列完全一样。', 273, 3),
(1412, 154, 138, 1, 'Java 语言提供了与系统无关的对日期和时间的封装类 java.util.Date，它表示以毫秒为单位的具体时刻。在 JDK1.1 之前，Date 类有两个额外的功能。它允许将日期解释为年、月、日、小时、分钟和秒值。它还允许格式化和解析日期字符串。然而，这些功能的 API 不适合国际化。从 JDK1.1 开始，Calendar 类应用于在日期和时间字段之间进行转换，DateFormat 类应用于格式化和解析日期字符串。Date 中的相应方法已被弃用。', 273, 4),
(1413, 154, 138, 1, 'Date 类的构造方法和常用方法如表 6-9 所示', 273, 5),
(1414, 154, 138, 1, '表 6-9　Date 类构造方法和常用方法\n| 方法头 | 说明 |\n| --- | --- |\n| public Date() | 以当前时间创建一个以毫秒为单位的时间值创建一个 Date 对象 |\n| public Date(long date) | 以从格林威治时间 1970 年 1 月 1 日 00:00:00 至当前时刻流逝的以毫秒为单位的时间值，创建一个 Date 对象 |\n| public String toString() | 返回日期对象的字符串表示 |\n| public long getTime() | 返回从格林威治时间 1970 年 1 月 1 日 00:00:00 至当前时刻流逝的以毫秒为单位的时间值 |\n| public void setTime(long time) | 为当前 Date 对象设置一个以毫秒为单位的、自格林威治时间 1970 年 1 月 1 日 00:00:00 起开始的流逝时间 |', 273, 6),
(1415, 154, 138, 1, '其中 toString 方法，返回日期对象的字符串表示，其格式如下：', 274, 1),
(1416, 154, 138, 1, '其中，dow 表示一周的星期几，可取值为：Sun, Mon, Tue, Wed, Thu, Fri, Sat。mon 表示月份，可取值为：Jan, Feb, Mar, Apr, May, Jun, Jul, Aug, Sep, Oct, Nov, Dec。dd 表示每月的第几天，取值为 01-31，是一个两位十进制数。hh 表示小时数，取值为 00-23（24 小时制），也是一个两位十进制数。mm 表示分钟数，取值为 00-59，也是一个两位十进制数。Ss 表示秒数，取值为 00-61，也是一个两位十进制数。zzz 表时区，如果时区信息不可获得，那么 zzz 就是空值。yyyy 是一个四位数字表示的年份。', 274, 2),
(1417, 154, 138, 1, '表 6-9 中出现的时间：1970 年 1 月 1 日零时零分零秒，在 Java 语言中被称为 Unix 时间戳(Unix epoch)。1970 年是操作系统 Unix 正式发布的时间。Unix 时间戳是 Java 语言时间系统的一个基准时间。', 274, 3),
(1418, 154, 138, 1, '下面通过一个示例展示 Date 类的使用，其代码如程序清单 6-14 所示。', 274, 4),
(1419, 154, 138, 1, '运行结果如下。', 274, 5),
(1420, 154, 138, 1, '程序清单 6-14 第 3 行创建了一个 Date 对象 date，第 4-5 行显示了 date 对应的毫秒数，第 6 行显示对象 date 的字符串表示形式，CST 表示 China Standard Time UT+8:00。接下来，第 8 行设置流逝时间是 60 秒，正好 1 分钟，第 9-10 行显示了流逝一分钟后的时间。最后，第 11-12 行使用 System 类的静态方法 currentTimeMillis()获取从格林威治时间 1970 年 1 月 1 日 00:00:00 至当前时刻流逝的以毫秒为单位的时间值。根据运行结果，从创建 Date 对象到最后一行输出，流逝时间的毫秒数为：1674007257553 − 1674007257486 = 67 毫秒。', 274, 6),
(1421, 156, 139, 1, '对应章节：6.1.1 面向过程与面向对象的抽象', 275, 1),
(1422, 156, 139, 1, '课程思政教学设计：', 275, 2),
(1423, 156, 139, 1, '1、在面向对象系统中，一些独立的对象依据某种构造结合在一起，能够形成特有的属性和功能，可以形成一个更大更复杂的对象。这个更大更复杂的对象也可以成为另一个对象的一个组成部分，从而构造出一个更为庞大的系统。在面向对象系统中，每个对象各司其职，对象之间可以通过资源共享、相互合作完成软件功能。从这一点进行引申，在现实生活中，我们也应树立合作共赢观念，培养团队合作精神。', 275, 3),
(1424, 156, 139, 1, '2、合作共赢的观念不仅适用于个人，也适用于国家。二十报告强调，“构建人类命运共同体是世界各国人民前途所在。万物并育而不相害，道并行而不相悖。只有各国行天下之大道，和睦相处、合作共赢，繁荣才能持久，安全才有保障。中国提出了全球发展倡议、全球安全倡议，愿同国际社会一道努力落实。中国坚持对话协商，推动建设一个持久和平的世界；坚持共建共享，推动建设一个普遍安全的世界；坚持合作共赢，推动建设一个共同繁荣的世界；坚持交流互鉴，推动建设一个开放包容的世界；坚持绿色低碳，推动建设一个清洁美丽的世界。”', 275, 4),
(1425, 156, 139, 1, '3、团队合作是指通过团队完成某项制定的事件时所显现出来的自愿合作和协同努力的精神。团队合作如果运用的好，对管理团队特别的重要，可以培养团队的向心力。比如，在一个软件项目开发过程中，软件开发团队的成员各司其职，发挥自己所长，协作完成分配的任务，最终可以高质量地完成软件项目。软件开发团队协作越好，软件开发效率越高。', 275, 5),
(1426, 157, 140, 1, '对应章节：6.5 数据域封装', 275, 6),
(1427, 157, 140, 1, '课程思政教学设计：', 275, 7),
(1428, 157, 140, 1, '1、讲完数据域封装之后，进行总结和引申。如果数据域是公有访问权限，这些数据域被修改的可能性会扩展到其他任何类。这会导致数据域可以被任意篡改以及程序的可维护性变差，如果有人恶意篡改，还会导致软件失效。因此，应从软件开发阶段，就树立软件安全意识。', 275, 8),
(1429, 157, 140, 1, '2、软件安全（Software Security）就是使软件在受到恶意攻击的情形下依然能够继续正确运行及确保软件被在授权范围内合法使用的思想。软件安全可以保护软件中的智力成果、知识产权不被非法使用，包括篡改及盗用等。研究的内容主要包括防止软件盗版、软件逆向工程、授权加密以及非法篡改等。采用的技术包括软件水印（静态水印及动态水印）、代码混淆（源代码级别的混淆，目标代码级别的混淆等）、防篡改技术、授权加密技术以及虚拟机保护技术等。', 275, 9),
(1430, 157, 140, 1, '3、课外了解软件安全相关技术。', 275, 10);
INSERT INTO `knowledge_keyword` (`id`, `chapter_id`, `knowledge_point_id`, `keyword`, `description`, `page`, `page_order`) VALUES
(175, 132, 119, 'class', '定义类的关键字，前面可加 public 等修饰符，后面接类名与类体。', 231, 1),
(177, 132, 119, '+', 'UML 类图中 public 访问权限的前缀符号，# 表 protected，- 表 private。', 233, 3),
(178, 133, 120, 'new', '创建对象的关键字，其后的“类名(实参列表)”表示调用构造方法。', 233, 1),
(179, 133, 120, 'null', '引用类型数据域的默认值，表示引用变量尚未指向任何对象实体。', 235, 2),
(180, 134, 121, '.', '对象成员访问操作符，形式为“对象引用变量.数据域”和“对象引用变量.方法(实参列表)”。', 235, 1),
(181, 135, 122, 'static', '定义静态成员的关键字，修饰变量时置于数据类型前，修饰方法时置于返回值类型前。', 237, 1),
(182, 135, 122, 'numOfObject', '程序清单 6-5 中统计对象个数的静态计数器变量，被该类所有对象共享。', 237, 2),
(183, 135, 122, 'Math.sqrt()', '用类名调用静态方法的例子，无须创建 Math 的任何实例。', 237, 3),
(185, 137, 123, 'package', '包声明关键字，包声明语句必须是源文件的第一条语句。', 241, 1),
(187, 137, 123, 'javafx.scene.*', '通配符导入该包的类和接口，不能代替 import javafx.scene.layout.*;。', 241, 3),
(189, 138, 124, 'module-info.java', '模块描述符文件，创建模块时必须有且仅有一个。', 246, 1),
(190, 138, 124, 'requires', '声明本模块所依赖的模块，访问别模块导出的包时必须显式依赖。', 247, 2),
(191, 138, 124, 'exports', '声明模块导出的包，只能导出非空包，不能导出具体的类。', 247, 3),
