INSERT INTO `knowledge_difficult_point` (`id`, `chapter_id`, `description`, `type`, `page`, `page_order`) VALUES
(66, 133, '引用类型变量存放的是对象实体的引用值：rect2 = rect1 只让两个引用变量指向同一对象实体，不复制对象内容，原 rect2 引用的对象失去引用后成为垃圾被回收。', 3, 233, 1),
(67, 132, '在构造方法定义前加 void（如 public void SimpleRect( ){ }）使该方法退化为普通成员方法，类不再有任何构造方法，此时 new SimpleRect(3.5, 4.5) 会因找不到带参构造方法而编译错误。', 1, 234, 1),
(68, 134, '静态方法（含 main 方法）不能直接访问实例变量或调用实例方法，否则编译错误；需要时必须先创建对象，再通过“对象名.实例成员”访问。', 3, 239, 1),
(69, 134, '静态变量被该类所有对象共享，一个实例修改后其他实例读到的也是新值；静态成员应用“类名.静态成员”访问，通过对象名访问会产生编译警告。', 2, 239, 2),
(70, 137, '包与子包是两个独立的编译单元，import 一个包并不包含其子包；模块的 exports 只能导出非空包，不能导出具体的类，访问别模块导出的包必须显式 requires。', 3, 247, 1),
(71, 138, '三种访问权限的可见范围易混：private 只在类内可见；包私有（不写修饰符）同包可见、异包不可见；public 任何类可见。private 不能修饰类，class 前只能用 public 或不写修饰符。', 1, 248, 1),
(72, 139, '设计类的常规做法：所有数据域设为 private，所有构造方法和方法声明为 public，由 getter/setter 作为访问和修改私有数据域的唯一途径，从而在 setter 中完成合法性限制。', 2, 250, 1),
(73, 140, '局部变量与类变量同名时局部变量优先、类变量被隐藏：方法内要访问被隐藏的实例变量须用 this，要访问被隐藏的静态变量须用“类名.静态变量”。', 1, 251, 1),
(74, 143, 'Java 只有值传递：传引用类型时形参得到实参的引用值，形参修改对象内容会影响实参，但形参改指向新对象不影响实参（swap 与 swapRadius 结果不同即此原因）。', 3, 253, 1),
(75, 145, '对象数组的数组元素默认值是 null，声明并创建数组后必须对每个元素调用构造方法，否则访问 rects[0].getArea() 会抛 NullPointerException。', 1, 255, 1),
(76, 147, 'ArrayList 的泛型参数必须是引用类型：ArrayList<int> 编译错误，存放整数应写 ArrayList<Integer>；初始容量为 10，元素接近容量上限时自动扩充。', 1, 257, 1),
(77, 147, 'ArrayList 的 remove(int index) 与 remove(Object o) 是两个重载版本，intList.remove(2) 删除的是下标 2 的元素而不是值 2；在循环中删除元素会使后续元素左移，需据此调整下标否则漏删。', 2, 258, 1),
(78, 147, 'this 通常被隐式使用，只有两种情况必须显式写：引用被方法或构造方法参数隐藏的数据域、调用本类重载的构造方法；后者必须是构造方法的第一条语句。', 3, 260, 1),
(79, 152, '自动装箱的陷阱：int 值不能装箱成 Double，故 prices.add(100) 编译错误；但 Scanner 输入的整数 3 先被自动转换为 double 值再装箱成 Double，所以程序清单 6-12 运行时不报错。', 1, 270, 1),
(80, 155, 'Date 的时间以自格林威治时间 1970 年 1 月 1 日 00:00:00（Unix 时间戳）起流逝的毫秒数计，1 小时为 3600000 毫秒、120 分钟为 7200000 毫秒，setTime/getTime 换算为高频考点。', 2, 274, 1);
INSERT INTO `knowledge_exercise` (`id`, `chapter_id`, `question`, `answer`, `difficulty`, `knowledge_point`, `page`, `page_order`) VALUES
(370, 124, '1、 关于被私有访问控制符 private 修饰的成员变量，以下说法正确的是（ ）\n(A) 可以被三种类所引用：该类自身、与它在同一个包中的其他类、在其他包中的该类的子类\n(B) 可以被两种类访问和引用：该类本身、该类的所有子类\n(C) 只能被该类自身所访问和修改\n(D) 只能被同一个包中的类访问', 'C', 1, 'public、private、包私有访问权限', 276, 1),
(371, 124, '2、 在 Java 中，一个类可同时定义许多同名的方法，这些方法的形式参数的个数、类型或顺序各不相同，传回的值也可以不相同。这种面向对象程序特性称为（ ）\n(A) 隐藏　(B) 重写\n(C) 重载　(D) Java 不支持此特性', 'C', 1, '类的定义', 276, 2),
(372, 124, '3、 以下有关构造方法的说法，正确的是：（ ）\n(A) 一个类的构造方法可以有多个\n(B) 构造方法在类定义时被调用\n(C) 构造方法只能由对象中的其它方法调用。\n(D) 构造方法可以和类同名，也可以和类名不同', 'A', 1, '对象创建', 276, 3),
(373, 124, '4、 下面关于方法的说法，不正确的是（ ）\n(A) Java 中的构造方法名必须和类名相同\n(B) 方法体是对方法的实现，包括变量声明和合法语句\n(C) 如果一个类定义了构造方法，也可以用该类的默认构造方法\n(D) 类的私有方法不能被其他类直接访问', 'C', 1, '对象创建', 276, 4),
(374, 124, '5、 如果一个类的成员变量只能在所在类中使用，则该成员变量必须使用的修饰是( )\n(A) public　(B) protected　(C) private　(D) static', 'C', 1, 'public、private、包私有访问权限', 276, 5),
(375, 124, '6、 类变量必须带有的修饰符是( )\n(A) static　(B) final　(C) public　(D) volatile', 'A', 1, '静态成员', 276, 6),
(376, 124, '7、 下列关于构造方法的叙述中，错误的是( )\n(A) Java 语言规定构造方法名与类名必须相同\n(B) Java 语言规定构造方法没有返回值，但不用 void 声明\n(C) Java 语言规定构造方法不可以重载\n(D) Java 语言规定构造方法只能通过 new 自动调用', 'C', 1, '对象创建', 276, 7),
(377, 124, '8、 下列关于 Java 对 import 语句规定的叙述中，错误的是( )\n(A) 在 Java 程序中 import 语句可以有多个\n(B) 在 Java 程序中 import 语句可以没有\n(C) 在 Java 程序中 import 语句必须有一个\n(D) 在 Java 程序中 import 语句必须引入在所有类定义之前', 'C', 1, '包', 276, 8),
(378, 124, '9、 在类的定义中可以有两个同名方法，这种现象称为方法（ ）。\n(A) 封装　(B) 继承　(C) 重写　(D) 重载', 'D', 1, '类的定义', 276, 9),
(379, 124, '10、在类的定义中构造方法的作用是（ ）。\n(A)保护成员变量　(B)读取类的成员变量\n(C)描述类的特征　(D)初始化成员变量', 'D', 1, '对象创建', 276, 10),
(380, 124, '11、类与对象的关系是（ ）。\n(A)类是对象的抽象　(B)对象是类的抽象\n(C)对象是类的子类　(D)类是对象的具体实例', 'A', 1, '封装', 276, 11),
(381, 124, '12、当你试着编译运行下面的代码的时候，可能会发生什么？（ ）\n```java\npublic class Crowle{\npublic static void main(String argv[]){\n      Crowle c = new Crowle(); }\nvoid Crowle(){\n      System.out.println("Greetings from Crowle"); }\n}\n```\n(A) 编译正确，运行时输出字符串 "Greetings from Crowle"\n(B) 编译时错误，构造方法没有返回类型\n(C) 编译正确，运行时输出字符串"void"\n(D) 编译正确，运行时无输出', 'D', 1, '对象创建', 277, 12),
(382, 124, '13、（  ）表示一个在真实世界中能被明确区分的实体。\n(A) 一个类　(B) 一个对象\n(C) 一个方法　(D) 一个数据域', 'B', 1, '类的定义', 277, 13),
(383, 124, '14、能被一个类的所有实例共享的变量称为 （ ）。\n(A) 公有变量　(B) 私有变量\n(C) 实例变量　(D) 类变量', 'D', 1, '静态成员', 277, 14),
(384, 124, '15、下面哪个说法不正确（ ）。\n(A)可使用 private 修饰符封装数据域　(B)封装数据域使得程序易于维护\n(C)封装数据域使得程序变短　(D)封装数据域帮助防止程序错误', 'C', 1, '数据域封装', 277, 15),
(385, 124, '16、当向一个方法传递对象参数时，（ ）被传递给方法。\n(A) 对象的内容　(B) 对象的一个 copy\n(C) 对象的引用值 (D) 对象的一个 copy，这个 copy 对象的引用值', 'C', 1, '对象作为方法的形参', 277, 16),
(386, 124, '17、创建一个只能存放 String 的泛型 ArrayList 的语句是哪项？（ ）\n(A) ArrayList<int> al=new ArrayList<int>()；\n(B) ArrayList<String> al=new ArrayList<String>()；\n(C) ArrayList al=new ArrayList<String>()；\n(D) ArrayList<String> al =new List<String>();', 'B', 1, 'ArrayList', 277, 17),
(387, 124, '18、假设一个列表包含 {"red", "red", "green"}，在执行下面代码之后 list 的值是多少？ ( )\n```java\nString element = "red";\nfor (int i = 0; i < list.size(); i++)\n      if (list.get(i).equals(element))\n      list.remove(element);\n```\n(A) {"red", "red", "green"}　(B) {"red", "green"}\n(C) {"green"}　(D) {}', 'B', 1, 'ArrayList', 277, 18),
(388, 124, '19、假设一个列表包含 {"red", "red", "green"}，在执行下面代码之后 list 的值是多少？( )\n```java\nString element = "red";\nfor (int i = 0; i < list.size(); i++)\n      if (list.get(i).equals(element)) {\n         list.remove(element);\n         i--;            }\n```\n(A) {"red", "red", "green"}　(B) {"red", "green"}\n(C) {"green"}　(D) {}', 'C', 1, 'ArrayList', 277, 19),
(389, 124, '1、 面向对象程序设计的主要思想是把构成问题的各个事物抽象成一个个________________，通过对象之间的________________解决问题。', '对象；通信和协作', 1, '教学目标', 278, 20),
(390, 124, '2、 面向对象程序设计具有三大基本特征：________________、________________、________________。', '封装；继承；多态', 1, '面向过程与面向对象的抽象', 278, 21),
(391, 124, '3、 抽象是透过事物的表面现象抽取事物本质特征，同时舍弃事物________________的过程。', '非本质特征', 1, '面向过程与面向对象的抽象', 278, 22),
(392, 124, '4、 面向过程抽象是基于功能分解、________________的方式进行的。', '逐步精化', 1, '面向过程与面向对象的抽象', 278, 23),
(393, 124, '5、 类是创建对象的模板，是一组对象________________的抽象。', '公共属性和行为', 1, '封装', 278, 24),
(394, 124, '6、 继承也体现了现实世界的分类体系，表达了________________关系。', '“是一种”', 1, '继承', 278, 25),
(395, 124, '7、 继承可以分为________________和________________。', '单继承；多继承', 1, '继承', 278, 26),
(396, 124, '8、 多态机制使具有不同内部结构的对象可以共享相同的________________。', '外部接口', 1, '多态', 278, 27),
(397, 124, '9、 在面向对象程序中，每个对象都有自己独特的标识、________________和________________。', '属性；行为', 1, '类的定义', 278, 28),
(398, 124, '10、在面向对象方法中，对象和实例经常可以互换使用。', '对象；实例', 1, '类的定义', 278, 29),
(399, 124, '11、类体一般由三个部分的定义组成，即数据域定义部分、________________部分和________________部分。', '构造方法定义；方法定义', 1, '类的定义', 278, 30),
(400, 124, '12、引用类型变量代表的内存位置存储的值是一个________________。然而，基本数据类型变量代表的内存位置存储的值是________________。', '引用值；基本类型的值', 1, '对象创建', 278, 31),
(401, 124, '13、构造方法只能在创建一个对象时由关键字________________调用。', 'new', 1, '对象创建', 278, 32),
(402, 124, '14、一个类的数值类型数据域的默认值是________________，引用类型数据域的默认值是________________。', '零值；null', 1, '对象创建', 278, 33),
(403, 124, '15、一个类的实例成员可分为________________与________________。', '实例变量；实例方法', 1, '对象访问', 278, 34),
(404, 124, '16、一个类的________________是将变量值放在一个该类所有对象都能访问的公共内存位置中。', '静态变量（静态成员变量，又称类变量）', 1, '静态成员', 278, 35),
(405, 124, '17、Java 语言在定义静态成员时，使用关键字________________修饰变量或方法。', 'static', 1, '静态成员', 278, 36),
(406, 124, '18、可见性修饰符有三个：________________、________________、protected（保护），放置在类及其成员之前。', 'public（公有）；private（私有）', 1, 'public、private、包私有访问权限', 278, 37),
(407, 124, '19、如果一个类在定义时，没有声明包，那么表示该类被放在________________中。', '默认包', 1, '包', 278, 38),
(408, 124, '20、包与子包是 ________________（是/不是）两个独立的编译单元。在导入语句中，导入一个包，并________________（包含/不包含）其子包。', '是；不包含', 1, '包', 278, 39),
(409, 124, '21、如果一些包具有较强的相关性，那么可以将这些包分组为一个________________。', '模块', 1, '模块 module', 278, 40),
(410, 124, '22、一个模块能够通过两个关键字________________和________________，对自身所依赖的模块和自身导出的包进行声明。', 'requires；exports', 1, '模块 module', 278, 41),
(411, 124, '23、模块的引入，增强了代码的________________。', '封装性', 1, '模块 module', 278, 42),
(412, 124, '24、如果一个局部变量和类变量同名，那么________________优先，另一个变量被隐藏。', '局部变量', 1, '变量作用域', 278, 43),
(413, 124, '25、在 Java 语言中，参数传递本质上仅有一种方式，即________________。', '值传递', 1, '对象作为方法的形参', 278, 44),
(414, 124, '26、关键字________________用于一个对象引用自身。', 'this', 1, 'this 引用被隐藏数据域', 278, 45),
(415, 124, '27、写一条语句将字符串“12.5”转换为一个 double 类型值：________________。', 'double d = Double.parseDouble("12.5");', 1, '基本数据类型的包装类', 278, 46),
(416, 124, '28、写一条语句将“12”转为一个 Integer 类型对象：________________。', 'Integer obj = Integer.valueOf("12");', 1, '基本数据类型的包装类', 278, 47),
(417, 124, '29、写一条语句将 12 转为一个 Integer 类型对象：________________。', 'Integer obj = Integer.valueOf(12);', 1, '基本数据类型的包装类', 278, 48),
(418, 124, '30、写一条语句将 12 转换成其对应的十六进制字符串：________________。', 'String s = Integer.toHexString(12);', 1, '基本数据类型的包装类', 278, 49),
(419, 124, '31、Unix 时间戳所指的时间是：________________。', '格林威治时间 1970 年 1 月 1 日 00:00:00（1970 年 1 月 1 日零时零分零秒）', 1, 'Date 类', 278, 50),
(420, 124, '32、写一条语句创建一个存储整数值的 ArrayList：_____________________。', 'ArrayList<Integer> list = new ArrayList<>();', 1, 'ArrayList', 278, 51),
(421, 124, '33、从 ArrayList 对象 list 中移除最后一个元素的语句是：__________________。', 'list.remove(list.size() - 1);', 1, 'ArrayList', 278, 52),
(422, 124, '34、ArrayList 对象 list 清空所有元素的语句是：______________________。', 'list.clear();', 1, 'ArrayList', 278, 53),
(423, 124, '35、一个 ArrayList<String> list 已经存储了一些字符串，在该列表中查找字符串“Monkey”的索引值，其语句是____________________________。', 'list.indexOf("Monkey")', 1, 'ArrayList', 278, 54),
(424, 124, '36、一个 ArrayList<String> list 已经存储了一些字符串，判断该列表中是否有字符串“Monkey”，其语句是____________________________。', 'list.contains("Monkey")', 1, 'ArrayList', 279, 55),
(425, 124, '1、 面向对象方法应对复杂性的原理是什么？', '原理是对象的层层组合（聚合）与数据、操作的封装：一些独立的对象依据某种构造结合在一起，能形成新的、特有的属性和功能，可以形成一个更大更复杂的对象，这个更大更复杂的对象又可以成为另一个更大对象的组成部分，从而构造出更为庞大的系统；同时面向对象抽象把数据和操作封装到一个个能动的对象中，数据和操作之间的对应关系不再由程序员维护而由系统自动维护，因而减轻了大规模软件开发与维护的负担。', 2, '面向过程与面向对象的抽象', 279, 56),
(426, 124, '2、 简述面向对象三大特性。', '封装：把从现实世界抽象出的客观实体封装成类，类隐藏内部实现细节、只对外发布接口，体现了信息隐藏；继承：一个类无需重新编写现有类的代码而具备现有类的所有功能并可在此基础上扩展，体现了分类体系和“是一种”关系；多态：一个父类类型的引用变量在程序运行的不同时刻能够指向其任何不同子类的实例，使具有不同内部结构的对象共享相同的外部接口。', 2, '封装', 279, 57),
(427, 124, '3、 简述类与对象的关系。', '类是创建对象的模板，是一组对象公共属性和行为的抽象，是抽象的定义；对象是类的实例，是通过类创建出来的具体实体，一个类的一个实例就是该类的一个对象。同一个类可以创建许多对象，各对象有自己独特的标识、属性和行为，在面向对象方法中对象和实例经常可以互换使用。', 2, '类的定义', 279, 58),
(428, 124, '4、 举例说明多态性。', '设引用变量 vehicle 的类型是交通工具类，它可以在程序运行的某一时刻指向陆地交通工具类的一个实例，另一时刻指向水上交通工具类或火车类、汽车类的实例，从而表现出相应子类的行为。当一个方法的形式参数是交通工具类对象时，该方法可以接受其任一子类的对象，相同的方法接受不同类型的参数表现出不同行为，即同一操作作用于不同类的实例产生不同的执行结果。', 2, '多态', 279, 59),
(429, 124, '5、 简述构造方法的特殊之处。', '构造方法有三个特殊之处：（1）必须与所在类同名，大小写一致；（2）没有返回值类型，也不能加 void 关键字，加了 void 就变成普通成员方法；（3）只能在创建一个对象时由关键字 new 调用。此外构造方法允许重载，可以有多个同名但方法签名不一样的构造方法，其目的是实例化对象并完成对象属性的初始化。', 2, '对象创建', 279, 60),
(430, 124, '6、 什么时候类会有一个默认构造方法？', '当一个类没有明确定义任何构造方法时，Java 编译器在编译后会自动为该类提供一个默认构造方法，它是方法体为空的无参构造方法，用它创建对象时数据域保持默认值。若一个类明确定义了一个或多个构造方法，默认构造方法就不再被自动提供。', 2, '对象创建', 279, 61),
(431, 124, '7、 下面代码有什么错误？\n```java\npublic class Test{\n      int x;\n      public static void main(String[] args){\n            Test obj = new Test(10);\n            System.out.println("x = "+ obj.x);\n      }\n}\n```', '类 Test 只定义了数据域 int x，没有定义任何构造方法，此时编译器提供的默认构造方法是无参且方法体为空的；main 方法中的 new Test(10) 需要一个带 int 参数的构造方法，该类并不存在这样的构造方法，因此产生编译错误。改正办法是补充构造方法 Test(int x){ this.x = x; }，或把语句改为 new Test()。', 2, '对象创建', 279, 62),
(432, 124, '8、 下面代码有什么错误？\n```java\nclass A{\n      private int x;\n}\npublic class B{\n      public static void main(String[] args){\n            A obj = new A();\n            obj.x++;\n            System.out.println("x = "+ obj.x);\n      }\n}\n```', '数据域 x 被 private 修饰，只能在其所在类 A 的内部被访问。类 B 的 main 方法中 obj.x++ 与 obj.x 都是在类 A 的外部访问类 A 的私有数据域，Java 编译器会报告编译错误。应为类 A 提供公有的获取方法和设置方法（如 getX()、setX()），在方法内部操作 x。', 2, 'public、private、包私有访问权限', 279, 63),
(433, 124, '9、 下面代码有什么错误？\n```java\nclass A{\n      private int x;\n}\npublic class B{\n      public static void main(String[] args){\n            A[] a = new A[10];\n            System.out.println(a[0].x);\n            System.out.println(a[0].toString());\n      }\n}\n```', '有两处错误：一是 a[0].x 在类 B 中访问类 A 的私有数据域 x，违反 private 的访问特性，编译报错；二是对象数组 A[] a = new A[10] 创建后每个数组元素的默认值是 null，程序中并未为 a[0] 创建对象，即使数据域可访问，运行 a[0].x 也会抛出 NullPointerException。应先执行 a[0] = new A() 并通过公开方法访问成员。', 2, '对象数组', 279, 64),
(434, 124, '10、简述类的数据域的默认值取值情况。', '数值类型数据域的默认值是零值（如 int 为 0、long 为 0L、double 为 0.0、float 为 0.0f）；布尔类型数据域的默认值是 false；字符类型数据域的默认值是’\\u0000’；引用类型数据域的默认值是 null。程序清单 6-2 的 Person 对象用默认构造方法创建后，name 为 null、age 为 0、height 为 0.0、血型为 ’\\u0000’、isHealth 为 false。', 2, '对象创建', 279, 65),
(435, 124, '11、简述创建模块需要遵守的规则。', '四条规则：（1）模块名称必须是唯一的；（2）一个模块必须要有模块描述符文件 module-info.java，且仅有一个；（3）包名称必须是唯一的，即使在不同的模块中包名也不能相同；（4）每个模块将创建一个 jar 文件。创建步骤是先建一个通常以包名命名的文件夹，在其下建 module-info.java，再在同级别创建一个 Java 包，包下可创建多个 Java 类文件。', 2, '模块 module', 279, 66),
(436, 124, '12、数据域不设定为私有的，会产什么问题？', '两个问题：一是非私有的数据域可以被其他类篡改，例如可以把某个 Person 对象的 age 修改为 -10 这类明显不合理的值；二是程序的可维护性变差，非私有数据域可能被多个类直接修改，即使类内部已限制属性为非负数，其他类仍能绕过限制直接赋负值，需要调整约束时必须追查所有直接访问这些数据域的类。', 2, '数据域封装', 279, 67),
(437, 124, '13、简述方法在给形参传值时传递基本数据类型参数与传递引用类型参数的区别。', 'Java 语言中参数传递本质上只有值传递一种方式，实参传递给形参的都是实参的值。区别在于：传递基本数据类型时，形参得到值的副本，形参的改变对实参无任何影响；传递引用数据类型时，实参把引用值传给形参，形参与实参引用同一片内存区域，形参对该对象内容的改变会被保存下来，因而影响到实参。', 2, '对象作为方法的形参', 279, 68),
(438, 124, '14、下面的代码有什么错误：\n```java\nArrayList<Double> list = new ArrayList<>();\nfloat f = 5;\nlist.add(f);\n```', '错误在 list.add(f)：列表的元素类型是 Double，float 值 f 自动装箱得到的是 Float 对象，Double 与 Float 之间不存在转换关系，不能满足 add(E e) 的参数类型，编译报错。应把列表声明为 ArrayList<Float>，或把 f 声明为 double（float 值可先自动转换为 double 值再装箱成 Double 对象）。', 2, '基本数据类型的包装类', 280, 69),
(439, 124, '15、this 引用在什么情况下需要显式使用。', '两种情况下必须显式使用 this：（1）需要引用被方法或构造方法的参数所隐藏的数据域时，例如构造方法 Rect(double width, double height) 中用 this.width = width 区分形参与实例变量；（2）需要调用一个重载的构造方法时，且该 this 调用语句应是该构造方法的第一条语句。被隐藏的静态变量则要用类名访问。', 2, 'this 引用被隐藏数据域', 280, 70),
(440, 124, '16、Java 语言为什么既提供基本数据类型，又提供对应的包装类呢？', '一方面，提供基本数据类型是为了性能，如果把基本数据类型当作对象使用，处理对象时需要额外的系统开销；另一方面，Java 提供的一些数据结构和方法需要将引用类型作为参数，为了让这些数据结构和方法能对基本数据类型的值进行处理，就针对八个基本数据类型提供了八个包装类。例如 ArrayList<E> 是动态对象数组，要存储整数必须把整数转换成对应的 Integer 类型。', 2, '基本数据类型的包装类', 280, 71),
(441, 124, '17、Random 类属于哪个包？使用 Random 类创建一个 60~100 之间的随机整数和一个 32.5~125.5 之间的随机 double 类型数值。', 'Random 类属于 java.util 包。语句为：\nRandom random = new Random();\nint n = random.nextInt(41) + 60; //60~100 之间的随机整数\ndouble d = random.nextDouble() * 93.0 + 32.5; //32.5~125.5 之间的随机 double 值', 2, 'Random 类', 280, 72),
(442, 124, '18、编写语句基于当前时间创建一个 Date 对象，并输出其值。', 'Date date = new Date();\nSystem.out.println(date.toString());\n无参构造方法以当前时间创建 Date 对象，toString() 按 dow mon dd hh:mm:ss zzz yyyy 格式输出，如 Wed Jan 18 10:00:57 CST 2023。', 2, 'Date 类', 280, 73),
(443, 124, '1、 给出下面程序的输出结果。\n```java\npublic class TestAnalyze6_1 {\n      boolean flag;\n      String s;\n      double d;\n      public static void main(String[] args) {\n            TestAnalyze6_1 obj = new TestAnalyze6_1();\n            System.out.println("flag = " + obj.flag +\n                        "\\ns = " + obj.s + "\\nd = " + obj.d);\n      }}\n```', 'flag = false\ns = null\nd = 0.0\n三个数据域都没有显式初始化，取类的默认值：boolean 为 false、String 引用类型为 null、double 为零值 0.0。', 2, '对象创建', 280, 74),
(444, 124, '2、 给出下面程序的输出结果。\n```java\npublic class Main6_2 {\n      public static void main(String[] args) {\n            Circle c1 = new Circle(1.5);\n            Circle c2 = new Circle(2.5);\n            swap(c1, c2);\n            System.out.println("调用 swap 之后，c1 的半径：" + c1.radius +\n                        ";c2 的半径：" + c2.radius);\n            swapRadius(c1, c2);\n            System.out.println("调用 swapRaidus 之后，c1 的半径：" + c1.radius +\n                        ";c2 的半径：" + c2.radius);\n      }\n      public static void swap(Circle a, Circle b){\n            Circle tmp = a;\n            a = b;\n            b = tmp;\n      }\n      public static void swapRadius(Circle a, Circle b){\n            double tmp = a.radius;\n            a.radius = b.radius;\n            b.radius = tmp;\n      }\n}\nclass Circle{\n      double radius;\n      Circle(double radius){\n            this.radius = radius;\n      }\n}\n```', '调用 swap 之后，c1 的半径：1.5;c2 的半径：2.5\n调用 swapRaidus 之后，c1 的半径：2.5;c2 的半径：1.5\nswap 交换的是形参这两个引用值，形参重新指向新对象不影响实参；swapRadius 通过形参修改了两个对象实体自身的 radius 数据域，故实参看到交换后的结果。', 2, '对象作为方法的形参', 280, 75),
(445, 124, '3、 给出下面程序的输出结果。\n```java\npublic class Main6_3 {\n      public static void main(String[] args) {\n            int[] a = {3, 5};\n            swap(a[0], a[1]);\n            System.out.println("0:" + a[0] + ";1:" + a[1]);\n      }\n      public static void swap(int i, int j){\n            int tmp = i;\n            i = j;\n            j = tmp;\n      }\n}\n```', '0:3;1:5\nswap(int i, int j) 的形参是基本数据类型，得到的是 a[0]、a[1] 的值 3 和 5 的副本，交换形参对数组元素没有任何影响。', 2, '对象作为方法的形参', 281, 76),
(446, 124, '4、 给出下面程序的输出结果。\n```java\npublic class Main6_4 {\n      public static void main(String[] args) {\n            int[] a = {3, 5};\n            swap(a);\n            System.out.println("0:" + a[0] + ";1:" + a[1]);\n      }\n      public static void swap(int[] a){\n            int tmp = a[0];\n            a[0] = a[1];\n            a[1] = tmp;\n      }\n}\n```', '0:5;1:3\n形参 a 是引用类型，接收到数组的引用值，与实参指向同一个数组对象，因此 a[0] 与 a[1] 的交换作用到了原数组上。', 2, '对象作为方法的形参', 281, 77),
(447, 124, '5、 给出下面程序的输出结果。\n```java\npublic class Main6_5 {\n      public static void main(String[] args) {\n            A a1 = new A();\n            System.out.println("a1 的 x=" + a1.x + ";y=" + a1.y);\n            A a2 = new A();\n            System.out.println("a2 的 x=" + a2.x + ";y=" + a2.y);\n      }\n}\nclass A {\n      static int x = 0;\n      int y = 0;\n      A(){\n            x++;\n            y++;\n      }\n}\n```', 'a1 的 x=1;y=1\na2 的 x=2;y=1\nx 是静态变量，被类 A 的所有对象共享，每调用一次构造方法自增 1；y 是实例变量，每个对象各自持有一份，新建 a2 时 y 从 0 自增为 1。', 2, '静态成员', 281, 78),
(448, 124, '6、 给出下面程序的输出结果，假设当前时间的字符串形式是：Fri Jan 27 22:10:26 CST 2023。\n```java\npublic class Main6_6 {\n      public static void main(String[] args) {\n            Date date = null;\n            f(date);\n            System.out.println(date);\n      }\n      public static void f(Date date){\n            date = new Date();\n      }\n}\n```', 'null\n形参 date 收到的是实参 null 的副本，方法内 date = new Date() 只让形参指向新对象，main 中的 date 仍为 null，故输出 null。', 2, '对象作为方法的形参', 282, 79),
(449, 124, '7、 给出下面程序的输出结果。\n```java\npublic class Main6_7 {\n      public static void main(String[] args) {\n            Date date = new Date(123456);\n            f(date);\n            System.out.println(date.getTime());\n      }\n      public static void f(Date date){\n            date = new Date(654321);\n      }\n}\n```', '123456\nf(date) 中的 date = new Date(654321) 只改变形参的引用值，实参 date 引用的对象未被修改，getTime() 仍返回构造时给定的毫秒值 123456。', 2, '对象作为方法的形参', 282, 80),
(450, 124, '8、 给出下面程序的输出结果。\n```java\npublic class Main6_8 {\n      static int x = 1;\n      static int y = 2;\n      public static void main(String[] args) {\n            int x = 3;\n            int z = 5;\n            {\n                  int y = 4;\n                  System.out.println("x + y = " + (x + y));\n            }\n            z = x + y;\n            System.out.println("z = " + z);\n            System.out.println("y = " + y);\n      }\n}\n```', 'x + y = 7\nz = 5\ny = 2\n代码块内的局部变量 y=4 隐藏了静态变量 y，块内 x 取局部变量 3，故输出 7；块结束后 y 指静态变量 2，z = x + y = 3 + 2 = 5，最后一行输出静态变量 y 的值 2。', 2, '变量作用域', 282, 81),
(451, 124, '9、 给出下面程序的输出结果。\n```java\npublic class Main6_9 {\n      public static void main(String[] args) {\n            System.out.println(Integer.parseInt("101",2));\n            System.out.println(Integer.parseInt("101",8));\n            System.out.println(Integer.parseInt("101"));\n            System.out.println(Integer.parseInt("101",10));\n            System.out.println(Integer.parseInt("101",16));\n      }\n}\n```', '5\n65\n101\n101\n257\nparseInt(String s, int radix) 按第二个参数给定的基数解析字符串：二进制 101 为 5，八进制 101 为 65，不带基数或基数 10 时为 101，十六进制 101 为 257。', 2, '基本数据类型的包装类', 282, 82),
(452, 124, '10、给出下面程序的输出结果。\n```java\npublic class Main6_10 {\n      public static void main(String[] args) {\n            ArrayList<Integer> intList = new ArrayList<>();\n            intList.add(1);\n            intList.add(2);\n            intList.add(3);\n            intList.add(4);\n            intList.add(5);\n            intList.remove(2);\n            intList.set(2, 9);\n            System.out.println(intList);\n      }\n}\n```', '[1, 2, 9, 5]\n列表原为 [1, 2, 3, 4, 5]，remove(2) 是删除索引 2 处的元素 3（不是删除值 2），得 [1, 2, 4, 5]；再 set(2, 9) 把索引 2 的元素替换为 9。', 2, 'ArrayList', 283, 83),
(453, 124, '11、给出下面程序的输出结果。\n```java\npublic class Main6_11 {\n      public static void main(String[] args) {\n            ArrayList<String> colors = new ArrayList<>();\n            colors.add("RED");\n            colors.add("RED");\n            colors.add("BLUE");\n            colors.add("GREEN");\n            colors.add("BLACK");\n            colors.add("RED");\n            for(int i = 0; i< colors.size();i++)\n                  colors.remove("RED");\n            System.out.println(colors);\n      }\n}\n```', '[BLUE, GREEN, BLACK]\nremove("RED") 删除第一次出现的 RED 并使后续元素左移。i=0 删首个 RED，i=1 时列表为 [BLUE, GREEN, BLACK, RED]，索引 1 是 BLUE 不删，i=2、i=3 依次比较 GREEN、BLACK，循环在 size 变为 3 时结束，最后一个 RED 未被删除。', 2, 'ArrayList', 283, 84),
(454, 124, '12、给出下面程序的输出结果。\n```java\npublic class Main6_12 {\n      public static void main(String[] args) {\n            ArrayList<String> colors = new ArrayList<>();\n            colors.add("RED");\n            colors.add("RED");\n            colors.add("BLUE");\n            colors.add("GREEN");\n            colors.add("BLACK");\n            colors.add("RED");\n            for(int i = 0; i< colors.size();i++)\n                  if(colors.get(i) == "RED")\n                        colors.remove(i);\n            System.out.println(colors);\n      }\n}\n```', '[RED, BLUE, GREEN, BLACK]\n列表中的元素都来自同一个字符串字面量 "RED"，与常量池中的 "RED" 是同一对象，故 == 判断为 true。i=0 删除索引 0 后列表为 [RED, BLUE, GREEN, BLACK, RED]，i=1、2、3 分别是 BLUE、GREEN、BLACK，i=4 删除该位置的 RED，i=5 时 5 < 4 不成立，循环结束，索引 0 的 RED 被跳过。', 2, 'ArrayList', 283, 85),
(455, 124, '1、 请设计一个关注个人的身体质量指数 BMI 的类 MyBMI，它包含：\n(1) 数据域部分：所有数据域皆为私有数据域。字符串类型的用户 ID 和用户名称 name，double 类型的属性重量 weight（以千克为单位），double 类型的属性身高 height（以厘米为单位）。\n(2) 构造方法部分：构造方法皆为公有的。提供一个无参构造方法；提供一个具有用户 ID 和用户名称参数的构造方法。\n(3) 方法部分：方法皆为公有的。为每个数据域提供设置方法和获取方法；提供一个计算 BMI 的方法 getBMI()，BMI 的计算公式如下：\n```\nBMI = 体重（以千克为单位）/ 身高²（以米为单位）\n```\n完成要求：\n(1)请画出 MyBMI 类的 UML 类图。\n(2)实现该类并测试：在该类中提供一个主方法对 MyBMI 类进行测试，创建一个对象（ID：BMI230011，name：小明），体重、身高自由设置（例如，体重 75 公斤，身高 175cm），然后，输出用户姓名、体重（斤）、身高（米）、BMI 信息。', '（1）UML 类图：类名 MyBMI；数据域 -ID: String、-name: String、-weight: double、-height: double；构造方法 +MyBMI()、+MyBMI(ID: String, name: String)；方法 +setID(ID: String): void、+getID(): String、+setName(name: String): void、+getName(): String、+setWeight(weight: double): void、+getWeight(): double、+setHeight(height: double): void、+getHeight(): double、+getBMI(): double。\n（2）参考代码：\npublic class MyBMI {\n    private String ID, name;\n    private double weight, height;\n    public MyBMI() { }\n    public MyBMI(String ID, String name) { this.ID = ID; this.name = name; }\n    public void setID(String ID) { this.ID = ID; }\n    public String getID() { return ID; }\n    public void setName(String name) { this.name = name; }\n    public String getName() { return name; }\n    public void setWeight(double weight) { this.weight = weight; }\n    public double getWeight() { return weight; }\n    public void setHeight(double height) { this.height = height; }\n    public double getHeight() { return height; }\n    public double getBMI() { return weight / Math.pow(height / 100, 2); }\n    public static void main(String[] args) {\n        MyBMI b = new MyBMI("BMI230011", "小明");\n        b.setWeight(75); b.setHeight(175);\n        System.out.printf("用户姓名：%s 体重：%.1f斤 身高：%.2f米 BMI：%.2f\\n", b.getName(), b.getWeight() * 2, b.getHeight() / 100, b.getBMI());\n    }\n}', 2, '数据域封装', 284, 86),
(456, 124, '2、 基金是一种投资产品，请设计一个基金类 Fund，它包含：\n(1)数据域部分：所有数据域皆为私有数据域。字符串类型的基金代码 fID 和基金名称 fName，double 类型的单位净值 netAssetValue、近三个月涨幅 month3Var、近 1 年涨幅 annualVar。\n(2)构造方法部分：构造方法皆为公有的。提供一个无参构造方法；提供一个具有基金代码和基金名称参数的构造方法。\n(3)方法部分：方法皆为公有的。为每个数据域提供设置方法和获取方法，\n完成要求：\n(1)请画出 Fund 类的 UML 类图。\n(2)实现该类并测试：在该类中提供一个主方法对 Fund 类进行测试，创建两个基金对象（分别用到两个构造方法），并设置两个基金对象分别表示如下测试数据集中的两个基金。\n| | fID | fName | netAssetValue | month3Var | annualVar |\n| --- | --- | --- | --- | --- | --- |\n| 基金 1 | 516000 | 华夏中证大数据 | 0.8933 | 24.75% | -15.67% |\n| 基金 2 | 512930 | 平安人工智能 ETF | 1.1552 | 16.6280% | -25.5046% |\n最后，显示两个基金的信息，运行结果如下所示：\n```\n基金代码 基金名称          单位净值 近三月涨幅% 近一年涨幅%\n51600 华夏中证大数据 0.89                24.7500       -15.6700\n512930 平安人工智能 ETF 1.16            16.6280       -25.5046\n```', '（1）UML 类图：类名 Fund；数据域 -fID: String、-fName: String、-netAssetValue: double、-month3Var: double、-annualVar: double；构造方法 +Fund()、+Fund(fID: String, fName: String)；方法为每个数据域的 +setXxx(...): void 与 +getXxx(): 类型。\n（2）参考代码：\npublic class Fund {\n    private String fID, fName;\n    private double netAssetValue, month3Var, annualVar;\n    public Fund() { }\n    public Fund(String fID, String fName) { this.fID = fID; this.fName = fName; }\n    public void setfID(String fID) { this.fID = fID; } public String getfID() { return fID; }\n    public void setfName(String fName) { this.fName = fName; } public String getfName() { return fName; }\n    public void setNetAssetValue(double v) { netAssetValue = v; } public double getNetAssetValue() { return netAssetValue; }\n    public void setMonth3Var(double v) { month3Var = v; } public double getMonth3Var() { return month3Var; }\n    public void setAnnualVar(double v) { annualVar = v; } public double getAnnualVar() { return annualVar; }\n    public static void main(String[] args) {\n        Fund f1 = new Fund("516000", "华夏中证大数据");\n        f1.setNetAssetValue(0.8933); f1.setMonth3Var(24.75); f1.setAnnualVar(-15.67);\n        Fund f2 = new Fund(); f2.setfID("512930"); f2.setfName("平安人工智能 ETF");\n        f2.setNetAssetValue(1.1552); f2.setMonth3Var(16.628); f2.setAnnualVar(-25.5046);\n        System.out.printf("%-8s%-18s%-10s%-13s%-13s\\n", "基金代码", "基金名称", "单位净值", "近三月涨幅%", "近一年涨幅%");\n        System.out.printf("%-8s%-18s%-10.2f%-13.4f%-13.4f\\n", f1.getfID(), f1.getfName(), f1.getNetAssetValue(), f1.getMonth3Var(), f1.getAnnualVar());\n        System.out.printf("%-8s%-18s%-10.2f%-13.4f%-13.4f\\n", f2.getfID(), f2.getfName(), f2.getNetAssetValue(), f2.getMonth3Var(), f2.getAnnualVar());\n    }\n}', 2, '数据域封装', 284, 87),
(457, 124, '3、 一个炒股软件需要对股票信息进行处理，请设计一个股票类 Stock，它包含：\n(1)数据域部分包括：所有数据域皆为私有数据域。字符串类型的股票代码 sID 和股票名称 sName，double 型的前一日股票收盘价格 preEndPrice、前一日最高价格 preMaxPrice、前一日最低价格 preMinPrice、当前价 currentPrice。\n(2)构造方法部分：构造方法皆为公有的。提供一个无参构造方法；提供一个具有股票代码和股票名称参数的构造方法。\n(3)方法部分：为每个数据域提供设置方法和获取方法，一个方法名为 getPreVarMax，返回前一日股票的最高价格相对于前一日股票的收盘价格的波动百分比，即返回一个值 varPercent，如下计算：varPercent = (preMaxPrice - preEndPrice) / preEndPrice。类似的，一个方法名为 getPreVarMin 返回前一日股票的最高价格相对于前一日股票的收盘价格的波动百分比，一个方法名为 getCurVar()返回当前股票价格相对于前一日股票的收盘价格的波动百分比。所有方法皆为公有方法。\n完成要求：\n(1)请画出 Stock 类的 UML 类图。\n(2)实现该类并测试：在该类中提供一个主方法对 Stock 类进行测试，创建三个股票对象（两个构造方法要用到），并设置三个股票对象分别表示如下测试数据集中的三只股票。\n| | sID | sName | preEndPrice | preMaxPrice | preMinPrice | currentPrice |\n| --- | --- | --- | --- | --- | --- | --- |\n| 股票 1 | 600536 | 中国软件 | 75.00 | 79.57 | 74.39 | 76.57 |\n| 股票 2 | 601728 | 中国电信 | 4.44 | 4.85 | 4.44 | 4.22 |\n| 股票 3 | 000858 | 五粮液 | 207.89 | 212.00 | 207.10 | 205.32 |\n最后，显示三只股票的信息，运行结果如下所示：\n```\n股票代码 股票名称 前一日收盘价 当前价 前一日涨幅 前一日跌幅 今日涨跌\n600536 中国软件 75.00        76.57 0.06             -0.01     0.02\n601728 中国电信 4.44         4.22        0.09       0.00      -0.05\n000858 五粮液 207.89        205.32 0.02            -0.00     -0.01\n```', '（1）UML 类图：类名 Stock；数据域 -sID: String、-sName: String、-preEndPrice: double、-preMaxPrice: double、-preMinPrice: double、-currentPrice: double；构造方法 +Stock()、+Stock(sID: String, sName: String)；方法 +getPreVarMax(): double、+getPreVarMin(): double、+getCurVar(): double 以及各数据域的获取和设置方法。\n（2）参考代码：\npublic class Stock {\n    private String sID, sName;\n    private double preEndPrice, preMaxPrice, preMinPrice, currentPrice;\n    public Stock() { }\n    public Stock(String sID, String sName) { this.sID = sID; this.sName = sName; }\n    public void setsID(String v) { sID = v; } public String getsID() { return sID; }\n    public void setsName(String v) { sName = v; } public String getsName() { return sName; }\n    public void setPreEndPrice(double v) { preEndPrice = v; } public double getPreEndPrice() { return preEndPrice; }\n    public void setPreMaxPrice(double v) { preMaxPrice = v; } public double getPreMaxPrice() { return preMaxPrice; }\n    public void setPreMinPrice(double v) { preMinPrice = v; } public double getPreMinPrice() { return preMinPrice; }\n    public void setCurrentPrice(double v) { currentPrice = v; } public double getCurrentPrice() { return currentPrice; }\n    public double getPreVarMax() { return (preMaxPrice - preEndPrice) / preEndPrice; }\n    public double getPreVarMin() { return (preMinPrice - preEndPrice) / preEndPrice; }\n    public double getCurVar() { return (currentPrice - preEndPrice) / preEndPrice; }\n    public static void main(String[] args) {\n        Stock[] ss = { new Stock("600536", "中国软件"), new Stock("601728", "中国电信"), new Stock() };\n        ss[0].setPreEndPrice(75.00); ss[0].setPreMaxPrice(79.57); ss[0].setPreMinPrice(74.39); ss[0].setCurrentPrice(76.57);\n        ss[1].setPreEndPrice(4.44); ss[1].setPreMaxPrice(4.85); ss[1].setPreMinPrice(4.44); ss[1].setCurrentPrice(4.22);\n        ss[2].setsID("000858"); ss[2].setsName("五粮液"); ss[2].setPreEndPrice(207.89); ss[2].setPreMaxPrice(212.00); ss[2].setPreMinPrice(207.10); ss[2].setCurrentPrice(205.32);\n        System.out.printf("%-8s%-10s%-12s%-8s%-10s%-10s%-8s\\n", "股票代码", "股票名称", "前一日收盘价", "当前价", "前一日涨幅", "前一日跌幅", "今日涨跌");\n        for (Stock s : ss) System.out.printf("%-8s%-10s%-12.2f%-8.2f%-10.2f%-10.2f%-8.2f\\n", s.getsID(), s.getsName(), s.getPreEndPrice(), s.getCurrentPrice(), s.getPreVarMax(), s.getPreVarMin(), s.getCurVar());\n    }\n}', 2, '数据域封装', 285, 88),
(458, 124, '4、 请设计一个正六边形类 RegularHexagon，它包含：\n(1)数据域部分：double 类型的私有数据域边长 a。\n(2)构造方法部分：构造方法皆为公有的。提供一个无参构造方法；提供一个具有边长参数的构造方法。\n(3)方法部分：方法皆为公有的。为数据域 a 提供设置方法和获取方法；一个名为 getPerimeter()求周长的方法；一个名为 getArea()求面积的方法，计算公式如下：\n```\n正六边形面积 = 3√3 / 2 × a²\n```\n完成要求：\n(1)请画出 RegularHexagon 类的 UML 类图。\n(2)实现该类并测试：在该类中提供一个主方法对 RegularHexagon 类进行测试，分别用两个构造方法创建两个正六边形对象，并输出正六边形的面积和周长。\n一个可能的运行示例如下。\n```\n对象 边长 面积 周长\nhg1 5.50 78.59 33.00\nhg2 12.50 405.95 75.00\n```', '（1）UML 类图：类名 RegularHexagon；数据域 -a: double；构造方法 +RegularHexagon()、+RegularHexagon(a: double)；方法 +setA(a: double): void、+getA(): double、+getPerimeter(): double、+getArea(): double。\n（2）参考代码：\npublic class RegularHexagon {\n    private double a;\n    public RegularHexagon() { a = 1.0; }\n    public RegularHexagon(double a) { this.a = a; }\n    public void setA(double a) { this.a = a; }\n    public double getA() { return a; }\n    public double getPerimeter() { return 6 * a; }\n    public double getArea() { return 3 * Math.sqrt(3) / 2 * a * a; }\n    public static void main(String[] args) {\n        RegularHexagon hg1 = new RegularHexagon(5.5);\n        RegularHexagon hg2 = new RegularHexagon(); hg2.setA(12.5);\n        System.out.printf("%-6s%-8s%-10s%-10s\\n", "对象", "边长", "面积", "周长");\n        System.out.printf("%-6s%-8.2f%-10.2f%-10.2f\\n", "hg1", hg1.getA(), hg1.getArea(), hg1.getPerimeter());\n        System.out.printf("%-6s%-8.2f%-10.2f%-10.2f\\n", "hg2", hg2.getA(), hg2.getArea(), hg2.getPerimeter());\n    }\n}\n运行结果：hg1 边长 5.50、面积 78.59、周长 33.00；hg2 边长 12.50、面积 405.95、周长 75.00。', 2, '类的定义', 285, 89),
(459, 124, '5、 请设计一个正 n 边形类 RegularPolygon，它包含：\n(1)数据域部分：所有数据域皆为私有数据域。一个定义正多边形边数的 int 类型属性 n，默认值为 3；一个定义正多边形边长的 double 类型属性 a，默认值为 1；定义正多边形中心平面坐标的两个 double 类型 x、y，默认值均为 0.\n(2)构造方法部分：构造方法皆为公有的。提供一个无参构造方法；提供一个平面坐标为(0, 0)、指定边长和边数的构造方法；提供一个平面坐标为(x, y)、指定边长和边数的构造方法。\n(3)方法部分：方法皆为公有的。提供所有数据域的获取方法和设置方法；提供计算正多边形周长的方法 getPerimeter()；提供计算正多边形面积的方法 getArea()，其计算公式如下：\n```\n正 n 边形面积 = n × a² / (4 × tan(π/n))\n```\n完成要求：\n(1)请画出 RegularPolygon 类的 UML 类图。\n(2)实现该类并测试：在该类中提供一个主方法对 RegularPolygon 类进行测试，分别用三个构造方法创建三个正六边形对象，并输出正 n 边形的面积和周长。一个可能的运行示例如下。\n```\n对象 边数 边长 面积 周长\nrp1 3          1.00 0.43 3.00\nrp2 5          6.50 72.69 32.50\nrp3 8          6.50 204.00 52.00\n```', '（1）UML 类图：类名 RegularPolygon；数据域 -n: int、-a: double、-x: double、-y: double；构造方法 +RegularPolygon()、+RegularPolygon(a: double, n: int)、+RegularPolygon(x: double, y: double, a: double, n: int)；方法为各数据域的获取和设置方法、+getPerimeter(): double、+getArea(): double。\n（2）参考代码：\npublic class RegularPolygon {\n    private int n = 3;\n    private double a = 1, x = 0, y = 0;\n    public RegularPolygon() { }\n    public RegularPolygon(double a, int n) { this.a = a; this.n = n; }\n    public RegularPolygon(double x, double y, double a, int n) { this.x = x; this.y = y; this.a = a; this.n = n; }\n    public int getN() { return n; } public void setN(int n) { this.n = n; }\n    public double getA() { return a; } public void setA(double a) { this.a = a; }\n    public double getX() { return x; } public void setX(double x) { this.x = x; }\n    public double getY() { return y; } public void setY(double y) { this.y = y; }\n    public double getPerimeter() { return n * a; }\n    public double getArea() { return n * a * a / (4 * Math.tan(Math.PI / n)); }\n    public static void main(String[] args) {\n        RegularPolygon rp1 = new RegularPolygon();\n        RegularPolygon rp2 = new RegularPolygon(6.5, 5);\n        RegularPolygon rp3 = new RegularPolygon(2.0, 3.0, 6.5, 8);\n        System.out.printf("%-6s%-8s%-8s%-10s%-10s\\n", "对象", "边数", "边长", "面积", "周长");\n        System.out.printf("%-6s%-8d%-8.2f%-10.2f%-10.2f\\n", "rp1", rp1.getN(), rp1.getA(), rp1.getArea(), rp1.getPerimeter());\n        System.out.printf("%-6s%-8d%-8.2f%-10.2f%-10.2f\\n", "rp2", rp2.getN(), rp2.getA(), rp2.getArea(), rp2.getPerimeter());\n        System.out.printf("%-6s%-8d%-8.2f%-10.2f%-10.2f\\n", "rp3", rp3.getN(), rp3.getA(), rp3.getArea(), rp3.getPerimeter());\n    }\n}', 2, '类的定义', 286, 90),
(460, 124, '6、 请设计一个秒表类 StopWatch，它包含：\n(1)数据域部分：所有数据域皆为私有数据域。一个表示起始时间的 long 类型属性 startTime，一个表示结束时间的 long 类型属性 endTime。\n(2)构造方法部分：构造方法皆为公有的。提供一个无参构造方法，用当前时间初始化起始时间。（提示：System.currentTimeMillis()可以返回自 Unix 时间戳至当前时间流逝的毫秒数）\n(3)方法部分：方法皆为公有的。提供所有数据域的获取方法和设置方法；提供计算流逝时间的方法 getElapseTime()，返回以毫秒为单位的流逝时间。\n完成要求：\n(1)请画出 StopWatch 类的 UML 类图。\n(2)实现该类并测试：在该类中提供一个主方法对 StopWatch 类进行测试，在主方法中完成 1 到 10 万的累加求和，用 StopWatch 类测量其执行时间，即执行完如下代码：\n```java\nlong sum = 0;\nfor(long i = 0; i<= 100000; i++)\n      sum += i;\nSystem.out.println("1 到 100000 的和是：" + sum);\n```\n然后，StopWatch 类记录这段代码的开始执行时间和结束执行时间，然后计算其执行时间。根据机器配置不一，一个可能的执行结果如下。\n```\n1 到 100000 的和是：5000050000\n流逝的时间为：7 毫秒\n```', '（1）UML 类图：类名 StopWatch；数据域 -startTime: long、-endTime: long；构造方法 +StopWatch()；方法 +getStartTime(): long、+setStartTime(startTime: long): void、+getEndTime(): long、+setEndTime(endTime: long): void、+getElapseTime(): long。\n（2）参考代码：\npublic class StopWatch {\n    private long startTime, endTime;\n    public StopWatch() { startTime = System.currentTimeMillis(); }\n    public long getStartTime() { return startTime; }\n    public void setStartTime(long startTime) { this.startTime = startTime; }\n    public long getEndTime() { return endTime; }\n    public void setEndTime(long endTime) { this.endTime = endTime; }\n    public long getElapseTime() { return endTime - startTime; }\n    public static void main(String[] args) {\n        StopWatch watch = new StopWatch();\n        long sum = 0;\n        for (long i = 0; i <= 100000; i++) sum += i;\n        watch.setEndTime(System.currentTimeMillis());\n        System.out.println("1 到 100000 的和是：" + sum);\n        System.out.println("流逝的时间为：" + watch.getElapseTime() + " 毫秒");\n    }\n}\n运行结果中 1 到 100000 的和是 5000050000，流逝时间的毫秒数依机器配置而不同。', 2, '数据域封装', 286, 91),
(461, 124, '7、 请设计一个电视机类 TV，它包含：\n(1)数据域部分：所有数据域皆为私有数据域。一个表示频道的 int 类型属性 channel，默认值是 1，变化范围是 1~99；一个表示音量的 int 类型属性 volume，默认值是 10，变化范围是 0~50，其中 0 表示无声。\n(2)构造方法部分：构造方法皆为公有的。提供一个无参构造方法；提供一个指定频道的构造方法；提供一个指定频道和音量的构造方法。\n(3)方法部分：方法皆为公有的。提供所有数据域的获取方法和设置方法；提供一个频道递增的方法 upChannel()，当 channel 递增到 99 时，再次递增 channel 会回退到 1；提供一个频道递减的方法 downChanne()，当 channel 递减到 1 时，再次递减 channel 变为 99；提供一个音量递增的方法 upVolume()，当 volume 递增到 25 时，再次递增 volume 变为 0；提供一个音量递减的方法 downVolume()，当 volume 递减到 0 时，再次递减 volume 变为 25。\n完成要求：\n(1)请画出 TV 类的 UML 类图。\n(2)实现该类并测试：创建一个电视机对象，设置其频道为 55，设置其音量为 30，输出该电视机对象的频道信息和音量信息。然后，通过一个循环语句调用音量递增方法，对音量进行调整，直到音量调整到 25，输出调整后的音量信息。测试的运行结果如下。\n```\n电视机的频道：55\n电视机的音量：30\n调整后的音量：25\n```', '（1）UML 类图：类名 TV；数据域 -channel: int、-volume: int；构造方法 +TV()、+TV(channel: int)、+TV(channel: int, volume: int)；方法 +getChannel(): int、+setChannel(channel: int): void、+getVolume(): int、+setVolume(volume: int): void、+upChannel(): void、+downChannel(): void、+upVolume(): void、+downVolume(): void。\n（2）参考代码：\npublic class TV {\n    private int channel = 1, volume = 10;\n    public TV() { }\n    public TV(int channel) { this.channel = channel; }\n    public TV(int channel, int volume) { this.channel = channel; this.volume = volume; }\n    public int getChannel() { return channel; }\n    public void setChannel(int channel) { if (channel >= 1 && channel <= 99) this.channel = channel; }\n    public int getVolume() { return volume; }\n    public void setVolume(int volume) { if (volume >= 0 && volume <= 50) this.volume = volume; }\n    public void upChannel() { channel = (channel == 99) ? 1 : channel + 1; }\n    public void downChannel() { channel = (channel == 1) ? 99 : channel - 1; }\n    public void upVolume() { volume = (volume >= 25) ? 0 : volume + 1; }\n    public void downVolume() { volume = (volume <= 0) ? 25 : volume - 1; }\n    public static void main(String[] args) {\n        TV t = new TV();\n        t.setChannel(55); t.setVolume(30);\n        System.out.println("电视机的频道：" + t.getChannel());\n        System.out.println("电视机的音量：" + t.getVolume());\n        while (t.getVolume() != 25) t.upVolume();\n        System.out.println("调整后的音量：" + t.getVolume());\n    }\n}\n题面的 downChanne() 为拼写疏漏，代码按 downChannel() 命名。音量 30 按“递增到 25 后再递增变为 0”的规则先回 0 再递增到 25 结束循环。', 2, '数据域封装', 286, 92),
(462, 124, '8、 请设计一个用户自定义整数类 UserInteger，它包含：\n(1)数据域部分：所有数据域皆为私有数据域。一个 long 类型的属性 value。\n(2)构造方法部分：构造方法皆为公有的。提供一个无参构造方法；提供一个指定 long 类型值的构造方法。\n(3)方法部分：方法皆为公有的。提供所有数据域的获取方法和设置方法；对于对象拥有的值，提供三个方法 isOdd()、isEven()、isPrime()分别判别奇数、偶数和素数；提供两个静态方法 isPrime(int)、isPrime(long)判别一个 int 类型值、long 类型值是否为素数；提供一个静态方法 parseInt(String)将整数字符串转换成一个 UserInteger 对象。\n完成要求：\n(1)请画出 UserInteger 类的 UML 类图。\n(2)实现该类并测试其各个方法，测试结果信息要对用户友好，不做其他要求。', '（1）UML 类图：类名 UserInteger；数据域 -value: long；构造方法 +UserInteger()、+UserInteger(value: long)；方法 +getValue(): long、+setValue(value: long): void、+isOdd(): boolean、+isEven(): boolean、+isPrime(): boolean、静态方法 +isPrime(n: int): boolean、+isPrime(n: long): boolean、+parseInt(s: String): UserInteger。\n（2）参考代码：\npublic class UserInteger {\n    private long value;\n    public UserInteger() { }\n    public UserInteger(long value) { this.value = value; }\n    public long getValue() { return value; }\n    public void setValue(long value) { this.value = value; }\n    public boolean isOdd() { return Math.abs(value) % 2 != 0; }\n    public boolean isEven() { return value % 2 == 0; }\n    public boolean isPrime() { return isPrime(value); }\n    public static boolean isPrime(int n) { return isPrime((long) n); }\n    public static boolean isPrime(long n) { if (n < 2) return false; for (long i = 2; i * i <= n; i++) if (n % i == 0) return false; return true; }\n    public static UserInteger parseInt(String s) { return new UserInteger(Long.parseLong(s)); }\n    public static void main(String[] args) {\n        UserInteger u = UserInteger.parseInt("29");\n        System.out.println("整数 29：奇数=" + u.isOdd() + "，偶数=" + u.isEven() + "，素数=" + u.isPrime());\n        System.out.println("静态方法判别：100 是素数=" + isPrime(100) + "，-7 是素数=" + isPrime(-7L) + "，97 是素数=" + isPrime(97));\n    }\n}\nisPrime(int) 与 isPrime(long) 由重载区分，静态 isPrime(long) 把 int 值自动转换为 long 后复用同一实现。', 2, '静态成员', 287, 93),
(463, 124, '9、 请设计一个三维坐标点类 ThreeCoordinatePoint，它包含：\n(1)数据域部分：所有数据域皆为私有数据域。三个 double 类型的属性坐标 x、y、z。\n(2)构造方法部分：构造方法皆为公有的。提供一个无参构造方法；提供一个带指定坐标的构造方法。\n(3)方法部分：方法皆为公有的。提供所有数据域的获取方法和设置方法；提供一个方法 getDist(double x, double y, double z)，返回当前三维坐标点类的对象与指定坐标之间的距离；提供一个方法 getDist(ThreeCoordinatePoint p)，返回当前三维坐标点类的对象与指定坐标点类的对象之间的距离；提供一个静态方法 getDist(ThreeCoordinatePoint p1, ThreeCoordinatePoint p2)，返回对象 p1 与对象 p2 之间的距离。两个三维坐标点(x1, y1, z1)、(x2, y2, z2)之间的距离计算公式如下：\n```\n距离 = √((x1 − x2)² + (y1 − y2)² + (z1 − z2)²)\n```\n完成要求：\n(1)请画出 ThreeCoordinatePoint 类的 UML 类图。\n(2)实现该类并测试其各个方法，测试结果信息要对用户友好，不做其他要求。', '（1）UML 类图：类名 ThreeCoordinatePoint；数据域 -x: double、-y: double、-z: double；构造方法 +ThreeCoordinatePoint()、+ThreeCoordinatePoint(x: double, y: double, z: double)；方法 +getX()/+getY()/+getZ() 与对应设置方法、+getDist(x: double, y: double, z: double): double、+getDist(p: ThreeCoordinatePoint): double、静态 +getDist(p1: ThreeCoordinatePoint, p2: ThreeCoordinatePoint): double。\n（2）参考代码：\npublic class ThreeCoordinatePoint {\n    private double x, y, z;\n    public ThreeCoordinatePoint() { }\n    public ThreeCoordinatePoint(double x, double y, double z) { this.x = x; this.y = y; this.z = z; }\n    public double getX() { return x; } public void setX(double x) { this.x = x; }\n    public double getY() { return y; } public void setY(double y) { this.y = y; }\n    public double getZ() { return z; } public void setZ(double z) { this.z = z; }\n    public double getDist(double x, double y, double z) {\n        return Math.sqrt(Math.pow(this.x - x, 2) + Math.pow(this.y - y, 2) + Math.pow(this.z - z, 2));\n    }\n    public double getDist(ThreeCoordinatePoint p) { return getDist(p.x, p.y, p.z); }\n    public static double getDist(ThreeCoordinatePoint p1, ThreeCoordinatePoint p2) { return p1.getDist(p2); }\n    public static void main(String[] args) {\n        ThreeCoordinatePoint p1 = new ThreeCoordinatePoint(), p2 = new ThreeCoordinatePoint(3, 4, 5);\n        System.out.println("原点 p1 到点 (1,1,1) 的距离：" + p1.getDist(1, 1, 1));\n        System.out.println("p1 到 p2 的距离（对象作参数）：" + p1.getDist(p2));\n        System.out.println("静态方法求得 p1 与 p2 的距离：" + ThreeCoordinatePoint.getDist(p1, p2));\n    }\n}\n三个 getDist 由重载区分，实例方法内用 this 区分被形参隐藏的 x、y、z。', 2, '对象作为方法的形参', 287, 94),
(464, 124, '10、请设计一个计算个人所得税（individual income tax）的类 IndivTax，它包含：\n(1)数据域部分：所有数据域皆为私有数据域。一个 String 类型的属性纳税人身份证号 ID；一个 String 类型的属性纳税人姓名 name；一个 double 类型的属性纳税人综合所得 income；一个 double 类型的属性每个月免税额度 freeTaxNum，默认值是 5000。\n(2)构造方法部分：构造方法皆为公有的。提供一个无参构造方法；提供一个指定身份证号和姓名的构造的方法。\n(3)方法部分：方法皆为公有的。提供所有数据域的获取方法和设置方法；提供一个方法 getTax()，返回纳税人应缴纳的个人所得税；提供一个方法 getCurTaxRate()，返回纳税人当前的最高税率。\n补充说明：个人所得税采用累进税率，纳税人的综合所得，先行以每月收入额减除费用五千元以及专项扣除和依法确定的其他扣除后的余额为应纳税所得额，个人所得税税率表如下所示。\n| 级数 | 全年应纳税所得额 x | 税率（%） |\n| --- | --- | --- |\n| 1 | 不超过 36000 元的部分 | 3 |\n| 2 | 超过 36000 元至 144000 元的部分 | 10 |\n| 3 | 超过 144000 元至 300000 元部分 | 20 |\n| 5 | 超过 300000 元至 420000 元部分 | 25 |\n| 6 | 超过 420000 元至 660000 元部分 | 30 |\n| 7 | 超过 660000 元至 960000 元部分 | 35 |\n| 8 | 超过 960000 元部分 | 45 |\n完成要求：\n(1)请画出 IndivTax 类的 UML 类图。\n(2)实现该类并测试，基于纳税人信息（ID：450305198011112516，name：张东）创建一个 IndivTax 对象，其全年收入为 4458760 元，请输出该纳税人的最高税率，以及应缴纳的税款。', '（1）UML 类图：类名 IndivTax；数据域 -ID: String、-name: String、-income: double、-freeTaxNum: double；构造方法 +IndivTax()、+IndivTax(ID: String, name: String)；方法 +getID()/+setID(...)、+getName()/+setName(...)、+getIncome()/+setIncome(...)、+getFreeTaxNum()/+setFreeTaxNum(...)、+getTax(): double、+getCurTaxRate(): double。\n（2）参考代码：\npublic class IndivTax {\n    private String ID, name;\n    private double income, freeTaxNum = 5000;\n    private static final double[] LEVEL = {36000, 144000, 300000, 420000, 660000, 960000};\n    private static final double[] RATE = {0.03, 0.10, 0.20, 0.25, 0.30, 0.35, 0.45};\n    public IndivTax() { }\n    public IndivTax(String ID, String name) { this.ID = ID; this.name = name; }\n    public void setID(String ID) { this.ID = ID; } public String getID() { return ID; }\n    public void setName(String name) { this.name = name; } public String getName() { return name; }\n    public void setIncome(double income) { this.income = income; } public double getIncome() { return income; }\n    public void setFreeTaxNum(double v) { freeTaxNum = v; } public double getFreeTaxNum() { return freeTaxNum; }\n    private double taxable() { return income - freeTaxNum * 12; }\n    public double getTax() { double x = taxable(), tax = 0, low = 0; for (int i = 0; i < 6 && x > low; i++) { tax += (Math.min(x, LEVEL[i]) - low) * RATE[i]; low = LEVEL[i]; } if (x > low) tax += (x - low) * RATE[6]; return tax > 0 ? tax : 0; }\n    public double getCurTaxRate() { double x = taxable(); for (int i = 0; i < 6; i++) if (x <= LEVEL[i]) return RATE[i]; return RATE[6]; }\n    public static void main(String[] args) {\n        IndivTax t = new IndivTax("450305198011112516", "张东");\n        t.setIncome(4458760);\n        System.out.printf("纳税人：%s %s 最高税率：%.0f%% 应缴税款：%.2f 元\\n", t.getID(), t.getName(), t.getCurTaxRate() * 100, t.getTax());\n    }\n}\n全年应纳税所得额 = 4458760 − 5000×12 = 4398760 元，累进计算后最高税率为 45%，应缴税款 1797522.00 元。', 2, '数据域封装', 287, 95),
(465, 124, '11、使用 30 位精度的 BigDecimal 计算 e 的近似值，e 的计算公式如下：\n```\ne = 1 + 1/1! + 1/2! + 1/3! + 1/4! + 1/5! + 1/6! + 1/7! + ⋯ + 1/n!\n```\n计算当 n=1000, 1100, 1200, 1300, 1400, 1500, .., 2000 时 e 的值并输出计算结果。', '参考代码：\nimport java.math.BigDecimal;\nimport java.math.MathContext;\npublic class Exercise6_11 {\n    public static void main(String[] args) {\n        MathContext mc = new MathContext(30); //30 位精度\n        BigDecimal e = BigDecimal.ONE, factorial = BigDecimal.ONE;\n        for (int i = 1; i <= 2000; i++) {\n            factorial = factorial.multiply(new BigDecimal(i), mc); //i 的阶乘\n            e = e.add(BigDecimal.ONE.divide(factorial, mc), mc); //累加 1/i!\n            if (i >= 1000 && i % 100 == 0) System.out.println("n=" + i + " 时 e = " + e);\n        }\n    }\n}', 2, 'BigInteger 类和 BigDecimal 类', 288, 96),
(466, 124, '12、使用 20 位精度的 BigDecimal 计算π的近似值，π的计算公式如下：\n```\nπ = 4 × (1 − 1/3 + 1/5 − 1/7 + 1/9 − 1/11 + 1/13 − ⋯ + (−1)ⁿ × 1/(2n + 1))\n```\n计算当 n=500, 600, …, 1000 时π的值并输出计算结果。', '参考代码：\nimport java.math.BigDecimal;\nimport java.math.MathContext;\npublic class Exercise6_12 {\n    public static void main(String[] args) {\n        MathContext mc = new MathContext(20); //20 位精度\n        BigDecimal four = new BigDecimal(4), sum = BigDecimal.ONE, sign = BigDecimal.ONE;\n        for (int i = 1; i <= 1000; i++) {\n            sign = sign.negate(); //(-1)^i\n            sum = sum.add(sign.divide(new BigDecimal(2L * i + 1), mc), mc);\n            if (i >= 500 && i % 100 == 0) System.out.println("n=" + i + " 时 π = " + sum.multiply(four, mc));\n        }\n    }\n}', 2, 'BigInteger 类和 BigDecimal 类', 288, 97),
(467, 124, '13、编写程序，找到大于 Long.MAX_VALUE 的前 10 个素数并输出。', '参考代码：\nimport java.math.BigInteger;\npublic class Exercise6_13 {\n    public static void main(String[] args) {\n        BigInteger n = BigInteger.valueOf(Long.MAX_VALUE).add(BigInteger.ONE);\n        int count = 0;\n        while (count < 10) {\n            if (n.isProbablePrime(50)) {\n                System.out.println("第 " + (++count) + " 个素数：" + n);\n            }\n            n = n.add(BigInteger.ONE);\n        }\n    }\n}\nlong 类型无法表示大于 Long.MAX_VALUE 的整数，用 BigInteger 逐一试探；isProbablePrime(50) 表示 50 位确定度的素数判断。', 2, 'BigInteger 类和 BigDecimal 类', 288, 98),
(468, 124, '14、编写程序，以整数 12345 作为种子，创建一个 Random 对象，然后产生 100 个 0~50 之间（包括 0 和 50）随机整数序列，并显示该随机序列。', '参考代码：\nimport java.util.Random;\npublic class Exercise6_14 {\n    public static void main(String[] args) {\n        Random random = new Random(12345); //以 12345 为种子\n        System.out.println("0~50 之间（含两端）的 100 个随机整数：");\n        for (int i = 0; i < 100; i++) {\n            System.out.print(random.nextInt(51) + (i % 10 == 9 ? "\\n" : " "));\n        }\n    }\n}\nnextInt(51) 返回 0 到 51（不包括 51）的随机整数，即 0~50；种子固定，重复运行得到的序列相同。', 2, 'Random 类', 288, 99),
(469, 124, '15、编写程序，以一个小时的流逝时间创建一个 Date 对象，通过方法 toString()显示时间信息。然后，设置其流逝时间分别是 120 分钟、180 分钟、360 分钟，使用方法 toString()分别显示时间信息。（提示：编程要把流逝时间转换成以毫秒单位。）', '参考代码：\nimport java.util.Date;\npublic class Exercise6_15 {\n    public static void main(String[] args) {\n        Date date = new Date(60 * 60 * 1000); //流逝 1 小时，即 3600000 毫秒\n        System.out.println("流逝 1 小时：" + date.toString());\n        date.setTime(120 * 60 * 1000);\n        System.out.println("流逝 120 分钟：" + date.toString());\n        date.setTime(180 * 60 * 1000);\n        System.out.println("流逝 180 分钟：" + date.toString());\n        date.setTime(360 * 60 * 1000);\n        System.out.println("流逝 360 分钟：" + date.toString());\n    }\n}\n按东八区显示，四行结果分别为 Thu Jan 01 09:00:00 CST 1970、11:00:00、13:00:00、19:00:00。', 2, 'Date 类', 288, 100),
(470, 124, '16、编写程序，使用 ArrayList 创建一个整数列表，然后使用循环输入多个（不少于 5 个）整数值（输入 0 结束）给整数列表增加元素，要求输入值中有重复的整数值。接着，程序去除重复的整数值（重复的整数值只保留一个），最后使用 foreach 循环输出整数列表的结果，输出的整数之间采用逗号(,)分隔。', '参考代码：\nimport java.util.ArrayList;\nimport java.util.Scanner;\npublic class Exercise6_16 {\n    public static void main(String[] args) {\n        ArrayList<Integer> list = new ArrayList<>();\n        Scanner input = new Scanner(System.in);\n        System.out.println("请输入整数值（输入 0 结束）：");\n        int v = input.nextInt();\n        while (v != 0) {\n            if (!list.contains(v)) list.add(v); //重复值只保留一个\n            v = input.nextInt();\n        }\n        System.out.print("去重后的整数列表：");\n        boolean first = true;\n        for (int n : list) {\n            if (!first) System.out.print(",");\n            System.out.print(n);\n            first = false;\n        }\n        System.out.println();\n    }\n}', 2, 'ArrayList', 288, 101),
(471, 124, '17、编写程序，使用 ArrayList 创建一个整数列表，然后使用循环输入多个（不少于 5 个）整数值（输入 0 结束）给整数列表增加元素。接着，要求对整数列表进行排序（升序），并输出排序后的结果。', '参考代码：\nimport java.util.ArrayList;\nimport java.util.Scanner;\npublic class Exercise6_17 {\n    public static void main(String[] args) {\n        ArrayList<Integer> list = new ArrayList<>();\n        Scanner input = new Scanner(System.in);\n        System.out.println("请输入整数值（输入 0 结束）：");\n        for (int v = input.nextInt(); v != 0; v = input.nextInt()) list.add(v);\n        for (int i = 0; i < list.size() - 1; i++)\n            for (int j = 0; j < list.size() - 1 - i; j++)\n                if (list.get(j) > list.get(j + 1)) {\n                    int t = list.get(j);\n                    list.set(j, list.get(j + 1));\n                    list.set(j + 1, t);\n                }\n        System.out.print("升序排序后：" + list);\n    }\n}\nlist.get(j) 与 int 比较时 Integer 对象自动拆箱，交换元素用 set 方法完成。', 2, 'ArrayList', 288, 102),
(472, 124, '18、编写程序，使用 ArrayList 创建一个整数列表，然后使用循环输入多个（不少于 5 个）整数值（输入 0 结束）给整数列表增加元素。接着，要求找到整数列表的最小值，并输出。', '参考代码：\nimport java.util.ArrayList;\nimport java.util.Scanner;\npublic class Exercise6_18 {\n    public static void main(String[] args) {\n        ArrayList<Integer> list = new ArrayList<>();\n        Scanner input = new Scanner(System.in);\n        System.out.println("请输入整数值（输入 0 结束）：");\n        for (int v = input.nextInt(); v != 0; v = input.nextInt()) list.add(v);\n        if (list.isEmpty()) {\n            System.out.println("列表为空，没有最小值。");\n            return;\n        }\n        int min = list.get(0);\n        for (int n : list)\n            if (n < min) min = n;\n        System.out.println("整数列表：" + list);\n        System.out.println("最小值是：" + min);\n    }\n}', 2, 'ArrayList', 288, 103),
(473, 124, '19、编写程序，使用 ArrayList 创建一个整数列表，然后使用循环输入多个（不少于 5 个）整数值（输入 0 结束）给整数列表增加元素。接着，要求找到整数列表的最大值，并输出。', '参考代码：\nimport java.util.ArrayList;\nimport java.util.Scanner;\npublic class Exercise6_19 {\n    public static void main(String[] args) {\n        ArrayList<Integer> list = new ArrayList<>();\n        Scanner input = new Scanner(System.in);\n        System.out.println("请输入整数值（输入 0 结束）：");\n        for (int v = input.nextInt(); v != 0; v = input.nextInt()) list.add(v);\n        if (list.isEmpty()) {\n            System.out.println("列表为空，没有最大值。");\n            return;\n        }\n        int max = list.get(0);\n        for (int n : list)\n            if (n > max) max = n;\n        System.out.println("整数列表：" + list);\n        System.out.println("最大值是：" + max);\n    }\n}', 2, 'ArrayList', 289, 104),
(474, 124, '20、编写程序，使用 ArrayList 创建一个整数列表，然后使用循环输入多个（不少于 5 个）整数值（输入 0 结束）给整数列表增加元素，这些整数值在 30-99 之间。接着，创建一个新的整数列表保存整数值不低于 80 的整数值。最后输出两个整数列表的信息。', '参考代码：\nimport java.util.ArrayList;\nimport java.util.Scanner;\npublic class Exercise6_20 {\n    public static void main(String[] args) {\n        ArrayList<Integer> list = new ArrayList<>(), notBelow80 = new ArrayList<>();\n        Scanner input = new Scanner(System.in);\n        System.out.println("请输入 30~99 之间的整数值（输入 0 结束）：");\n        for (int v = input.nextInt(); v != 0; v = input.nextInt()) list.add(v);\n        for (int n : list)\n            if (n >= 80) notBelow80.add(n);\n        System.out.println("原整数列表：" + list);\n        System.out.println("不低于 80 的整数列表：" + notBelow80);\n    }\n}', 2, 'ArrayList', 289, 105),
(475, 124, '21、编写程序，使用 ArrayList 创建两个整数列表，然后使用两个循环分别输入多个（不少于 5 个）整数值（输入 0 结束）给这两个整数列表增加元素。接着，创建第三个列表，把前面两个列表的元素合并到第三个列表中。', '参考代码：\nimport java.util.ArrayList;\nimport java.util.Scanner;\npublic class Exercise6_21 {\n    public static void main(String[] args) {\n        ArrayList<Integer> list1 = new ArrayList<>(), list2 = new ArrayList<>(), list3 = new ArrayList<>();\n        Scanner input = new Scanner(System.in);\n        System.out.println("输入第一个列表的整数值（输入 0 结束）：");\n        for (int v = input.nextInt(); v != 0; v = input.nextInt()) list1.add(v);\n        System.out.println("输入第二个列表的整数值（输入 0 结束）：");\n        for (int v = input.nextInt(); v != 0; v = input.nextInt()) list2.add(v);\n        for (int n : list1) list3.add(n);\n        for (int n : list2) list3.add(n);\n        System.out.println("第一个列表：" + list1);\n        System.out.println("第二个列表：" + list2);\n        System.out.println("合并后的第三个列表：" + list3);\n    }\n}', 2, 'ArrayList', 289, 106),
(476, 124, '22、编写程序，使用 ArrayList 创建两个整数列表，然后使用两个循环分别输入多个（不少于 5 个）整数值（输入 0 结束）给这两个整数列表增加元素。接着，这两个整数列表分别进行排序（升序）。最后，创建第三个列表，有序合并排序后的前两个列表，输出这三个有序列表的值。', '参考代码：\nimport java.util.ArrayList;\nimport java.util.Scanner;\npublic class Exercise6_22 {\n    static void sortAsc(ArrayList<Integer> list) {\n        for (int i = 0; i < list.size() - 1; i++)\n            for (int j = 0; j < list.size() - 1 - i; j++)\n                if (list.get(j) > list.get(j + 1)) {\n                    int t = list.get(j);\n                    list.set(j, list.get(j + 1));\n                    list.set(j + 1, t);\n                }\n    }\n    public static void main(String[] args) {\n        ArrayList<Integer> list1 = new ArrayList<>(), list2 = new ArrayList<>(), list3 = new ArrayList<>();\n        Scanner input = new Scanner(System.in);\n        for (int k = 1; k <= 2; k++) {\n            System.out.println("输入第 " + k + " 个列表的整数值（输入 0 结束）：");\n            ArrayList<Integer> cur = k == 1 ? list1 : list2;\n            for (int v = input.nextInt(); v != 0; v = input.nextInt()) cur.add(v);\n        }\n        sortAsc(list1); sortAsc(list2);\n        int i = 0, j = 0;\n        while (i < list1.size() && j < list2.size())\n            list3.add(list1.get(i) <= list2.get(j) ? list1.get(i++) : list2.get(j++));\n        while (i < list1.size()) list3.add(list1.get(i++));\n        while (j < list2.size()) list3.add(list2.get(j++));\n        System.out.println(list1 + "\\n" + list2 + "\\n有序合并结果：" + list3);\n    }\n}', 2, 'ArrayList', 289, 107),
(477, 124, '23、（挑战型题目）给定一个由 n 个整数组成的数组 S，S 中是否存在元素 a、b、c，使得 a+b+c=0？在给出零和的数组中查找所有不同的三元组，返回三元组的下标值。请用多种解法求解该题。', '（1）解法一：三重循环枚举下标，时间复杂度 O(n³)，天然保证 i<j<k，三元组不重复。\nint[] S = {-1, 0, 1, 2, -1, -4};\nint n = S.length;\nfor (int i = 0; i < n; i++)\n    for (int j = i + 1; j < n; j++)\n        for (int k = j + 1; k < n; k++)\n            if (S[i] + S[j] + S[k] == 0)\n                System.out.println("下标 (" + i + ", " + j + ", " + k + ") 值 (" + S[i] + ", " + S[j] + ", " + S[k] + ")");\n（2）解法二：固定下标 i，用 HashMap 保存其右侧元素值到上标的映射，一次查找得到第三个下标，时间复杂度 O(n²)。\nimport java.util.HashMap;\nint n = S.length;\nfor (int i = 0; i < n - 2; i++) {\n    HashMap<Integer, Integer> map = new HashMap<>();\n    for (int k = n - 1; k > i; k--) {\n        int need = -S[i] - S[k]; //a+b+c=0 时 c = -a-b\n        if (map.containsKey(need))\n            System.out.println("下标 (" + i + ", " + map.get(need) + ", " + k + ")");\n        map.put(S[k], k);\n    }\n}\n解法二按元素值建索引，同值只保留一个下标，返回的是按值不重复的下标三元组。', 2, '对象数组', 289, 108),
(478, 124, '24、（挑战型题目）给定一个由 n 个整数组成的数组 S，S 中是否存在元素 a、b、c、d，使得 a+b+c+d=target？在数组中查找所有不同的四元组。请用多种解法求解该题。', '（1）解法一：四重循环枚举下标，时间复杂度 O(n⁴)，保证下标互不相同且有序。\nint n = S.length;\nfor (int i = 0; i < n; i++)\n    for (int j = i + 1; j < n; j++)\n        for (int k = j + 1; k < n; k++)\n            for (int m = k + 1; m < n; m++)\n                if (S[i] + S[j] + S[k] + S[m] == target)\n                    System.out.println("下标 (" + i + ", " + j + ", " + k + ", " + m + ")");\n（2）解法二：固定 i、j，把剩下两个数之和转化为两数之和问题，用 HashMap 查找，时间复杂度 O(n³)。\nimport java.util.HashMap;\nint n = S.length;\nfor (int i = 0; i < n; i++)\n    for (int j = i + 1; j < n; j++) {\n        HashMap<Integer, Integer> map = new HashMap<>();\n        for (int m = n - 1; m > j; m--) {\n            int need = target - S[i] - S[j] - S[m];\n            if (map.containsKey(need))\n                System.out.println("下标 (" + i + ", " + j + ", " + map.get(need) + ", " + m + ")");\n            map.put(S[m], m);\n        }\n    }\n解法二在数组已排序的前提下可再加同值跳过，得到按值不重复的四元组；也可先排序后用双指针把内层降为线性扫描。', 2, '对象数组', 289, 109);
